CREATE OR REPLACE FUNCTION chat.vip_customer_rows()
 RETURNS TABLE(customer_id uuid, orders_in_window bigint, net_spend_in_window numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select v.customer_id, v.orders, v.spend
  from public.shops s
  cross join lateral public.vip_customers(
    s.id,
    s.vip_min_spend,
    s.vip_min_orders,
    s.vip_window_months,
    coalesce(
      (select array_agg(h) from public.sales_channels c cross join lateral unnest(c.handles) h where c.shop_id = s.id),
      '{}'::text[]
    )
  ) v
  where s.vip_min_spend is not null
    and s.vip_min_orders is not null
    and s.vip_window_months is not null;
$function$;

CREATE OR REPLACE FUNCTION public.advisory_events_purge(p_before timestamp with time zone)
 RETURNS integer
 LANGUAGE sql
 SET search_path TO ''
AS $function$
  with gone as (
    delete from public.advisory_events e
    where e.created_at < p_before
    returning 1
  )
  select count(*)::integer from gone;
$function$;

CREATE OR REPLACE FUNCTION public.customer_segment_find(p_shop uuid, p_window_months integer, p_groups jsonb, p_not_channels text[] DEFAULT NULL::text[], p_limit integer DEFAULT 25)
 RETURNS TABLE(customer_id uuid, customer_name text, orders bigint, spend numeric, lifetime_spend numeric, last_order_at timestamp with time zone, on_marketing_list boolean, matched_customers bigint, matched_on_marketing_list bigint, matched_spend numeric, matched_lifetime_spend numeric, base_customers bigint, base_buyers bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with order_facts as (
    select
      o.shopify_customer_id as customer_key,
      count(*) filter (
        where o.processed_at >= now() - make_interval(months => p_window_months)
      ) as orders,
      coalesce(sum(o.total_price - coalesce(o.total_refunded, 0)) filter (
        where o.processed_at >= now() - make_interval(months => p_window_months)
      ), 0) as spend,
      coalesce(sum(o.total_price - coalesce(o.total_refunded, 0)), 0) as lifetime_spend,
      max(o.processed_at) as last_order_at
    from public.orders o
    where o.shop_id = p_shop
      and o.deleted_at is null
      and o.cancelled_at is null
      and o.shopify_customer_id is not null
      and (
        p_not_channels is null
        or o.sales_channel_handle is null
        or not (o.sales_channel_handle = any(p_not_channels))
      )
    group by 1
  ),
  marketplace_keys as (
    select distinct o.shopify_customer_id as customer_key
    from public.orders o
    where o.shop_id = p_shop
      and o.shopify_customer_id is not null
      and p_not_channels is not null
      and o.sales_channel_handle = any(p_not_channels)
  ),
  base as (
    select
      c.id as customer_id,
      coalesce(c.display_name, nullif(concat_ws(' ', c.first_name, c.last_name), '')) as customer_name,
      coalesce(f.orders, 0) as orders,
      coalesce(f.spend, 0) as spend,
      coalesce(f.lifetime_spend, 0) as lifetime_spend,
      f.last_order_at,
      coalesce(c.on_email_marketing_list, false) as on_marketing_list
    from public.customers c
    left join order_facts f on f.customer_key = c.shopify_customer_id
    where c.shop_id = p_shop
      and c.deleted_at is null
      and not exists (
        select 1 from marketplace_keys mk where mk.customer_key = c.shopify_customer_id
      )
  ),
  matched as (
    select b.*
    from base b
    where exists (
      select 1
      from jsonb_array_elements(
        case when jsonb_typeof(p_groups) = 'array' then p_groups else '[]'::jsonb end
      ) as grp(conditions)
      where jsonb_typeof(grp.conditions) = 'array'
        and jsonb_array_length(grp.conditions) > 0
        and not exists (
          select 1
          from jsonb_array_elements(grp.conditions) as cond(rule)
          cross join lateral (
            select case cond.rule ->> 'metric'
              when 'orders' then b.orders::numeric
              when 'spend' then b.spend
              when 'lifetime_spend' then b.lifetime_spend
            end as actual
          ) m
          where not coalesce(
            case cond.rule ->> 'op'
              when 'gt' then m.actual > (cond.rule ->> 'value')::numeric
              when 'lt' then m.actual < (cond.rule ->> 'value')::numeric
            end,
            false
          )
        )
    )
  ),
  totals as (
    select
      (select count(*) from base) as base_customers,
      (select count(*) from base where base.last_order_at is not null) as base_buyers,
      count(*) as matched_customers,
      count(*) filter (where mt.on_marketing_list) as matched_on_marketing_list,
      coalesce(sum(mt.spend), 0) as matched_spend,
      coalesce(sum(mt.lifetime_spend), 0) as matched_lifetime_spend
    from matched mt
  ),
  shown as (
    select mt.*
    from matched mt
    order by mt.lifetime_spend desc, mt.customer_id
    limit greatest(coalesce(p_limit, 25), 0)
  )
  select
    s.customer_id,
    s.customer_name,
    s.orders,
    s.spend,
    s.lifetime_spend,
    s.last_order_at,
    s.on_marketing_list,
    t.matched_customers,
    t.matched_on_marketing_list,
    t.matched_spend,
    t.matched_lifetime_spend,
    t.base_customers,
    t.base_buyers
  from totals t
  left join shown s on true
  order by s.lifetime_spend desc nulls last, s.customer_id;
$function$;

CREATE OR REPLACE FUNCTION public.customer_vip_ticket_categories(p_shop uuid, p_min_spend numeric, p_min_orders integer, p_window_months integer, p_not_channels text[] DEFAULT NULL::text[])
 RETURNS TABLE(category text, tickets bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select f.category, count(*)
  from public.customer_ticket_facts f
  join public.vip_customers(p_shop, p_min_spend, p_min_orders, p_window_months, p_not_channels) v
    on v.customer_id = f.customer_id
  where f.shop_id = p_shop
  group by f.category;
$function$;

CREATE OR REPLACE FUNCTION public.customer_vip_ticket_stats(p_shop uuid, p_min_spend numeric, p_min_orders integer, p_window_months integer, p_not_channels text[] DEFAULT NULL::text[], p_closed_statuses text[] DEFAULT '{}'::text[], p_unhappy_from integer DEFAULT 3)
 RETURNS TABLE(tickets_linked bigint, vip_tickets bigint, vip_contacted bigint, spend_exposed numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select
    (select count(*) from public.customer_ticket_facts f where f.shop_id = p_shop),
    (
      select count(*)
      from public.customer_ticket_facts f
      join public.vip_customers(p_shop, p_min_spend, p_min_orders, p_window_months, p_not_channels) v
        on v.customer_id = f.customer_id
      where f.shop_id = p_shop
    ),
    (
      select count(distinct f.customer_id)
      from public.customer_ticket_facts f
      join public.vip_customers(p_shop, p_min_spend, p_min_orders, p_window_months, p_not_channels) v
        on v.customer_id = f.customer_id
      where f.shop_id = p_shop
    ),
    -- Deduplicated by customer: amount_spent is a customer column, so a person
    -- with three open unhappy cases must count once.
    (
      select coalesce(sum(d.amount_spent), 0)
      from (
        select distinct on (f.customer_id) f.amount_spent
        from public.customer_ticket_facts f
        where f.shop_id = p_shop
          and not (f.status = any(p_closed_statuses))
          and f.happiness >= p_unhappy_from
        order by f.customer_id
      ) d
    );
$function$;

CREATE OR REPLACE FUNCTION public.insights_agent_blockers(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text)
 RETURNS TABLE(need text, state text, finding text, occurrences bigint, tickets bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select
    g.value ->> 'need',
    g.value ->> 'state',
    g.value ->> 'finding',
    count(*),
    count(distinct i.ticket_id)
  from public.ticket_investigations i
  cross join lateral jsonb_array_elements(
    case when jsonb_typeof(i.evidence_gaps) = 'array' then i.evidence_gaps else '[]'::jsonb end
  ) as g
  where i.shop_id = p_shop
    and i.created_at >= (p_from at time zone p_tz)
    and i.created_at < (p_to at time zone p_tz)
  group by 1, 2, 3
  order by 4 desc;
$function$;

CREATE OR REPLACE FUNCTION public.insights_agent_funnel(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text)
 RETURNS TABLE(tickets bigint, categorised bigint, customer_linked bigint, order_linked bigint, context_built bigint, investigated bigint, low_confidence bigint, awaiting_categorisation bigint, awaiting_investigation bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select
    count(*),
    count(*) filter (where t.categorised_at is not null),
    count(*) filter (where t.customer_id is not null),
    count(*) filter (where t.shopify_order_number is not null),
    count(*) filter (where t.context_resolved_at is not null),
    count(*) filter (where t.investigated_at is not null),
    count(*) filter (where t.categorisation_confidence = 'low'),
    count(*) filter (where t.needs_categorisation),
    count(*) filter (where t.needs_investigation)
  from public.tickets t
  where t.shop_id = p_shop
    and t.deleted_at is null
    and t.first_message_at >= (p_from at time zone p_tz)
    and t.first_message_at < (p_to at time zone p_tz);
$function$;

CREATE OR REPLACE FUNCTION public.insights_agent_situations(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text)
 RETURNS TABLE(tickets bigint, matched bigint, tie_by_rules bigint, chosen_by_model bigint, near_chooser_none bigint, near_not_settled bigint, no_match bigint, not_recorded bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with latest as (
    select distinct on (i.ticket_id)
      i.exemplar_match as m
    from public.ticket_investigations i
    where i.shop_id = p_shop
      and i.created_at >= (p_from at time zone p_tz)
      and i.created_at < (p_to at time zone p_tz)
    order by i.ticket_id, i.created_at desc
  )
  select
    count(*),
    count(*) filter (where m->>'verdict' = 'matched'),
    count(*) filter (
      where m->>'verdict' = 'ambiguous'
        and m->>'exemplar_key' is not null
        and m->>'chosen_by' is distinct from 'model'
    ),
    count(*) filter (where m->>'verdict' in ('near', 'ambiguous') and m->>'chosen_by' = 'model'),
    count(*) filter (
      where m->>'verdict' in ('near', 'ambiguous')
        and m->>'exemplar_key' is null
        and m->'chooser'->>'choice' = 'none'
    ),
    count(*) filter (
      where m->>'verdict' in ('near', 'ambiguous')
        and m->>'exemplar_key' is null
        and coalesce(m->'chooser'->>'choice', '') <> 'none'
    ),
    count(*) filter (where m->>'verdict' = 'none'),
    count(*) filter (
      where m->>'verdict' is null
        or m->>'verdict' not in ('matched', 'near', 'ambiguous', 'none')
    )
  from latest;
$function$;

CREATE OR REPLACE FUNCTION public.insights_agent_verdicts(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text)
 RETURNS TABLE(verdict text, investigations bigint, tickets bigint, with_handoff bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select
    i.verdict,
    count(*),
    count(distinct i.ticket_id),
    count(*) filter (where i.handoff is not null)
  from public.ticket_investigations i
  where i.shop_id = p_shop
    and i.created_at >= (p_from at time zone p_tz)
    and i.created_at < (p_to at time zone p_tz)
  group by 1
  order by 2 desc;
$function$;

CREATE OR REPLACE FUNCTION public.insights_capture_series(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_grain text, p_checkout_minutes integer, p_channels text[] DEFAULT NULL::text[], p_not_channels text[] DEFAULT NULL::text[])
 RETURNS TABLE(bucket timestamp without time zone, first_orders bigint, subscribed_before bigint, subscribed_at_checkout bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with firsts as (
    select o.shopify_customer_id as customer, min(o.processed_at) as first_at
    from public.orders o
    where o.shop_id = p_shop
      and o.deleted_at is null
      and o.cancelled_at is null
      and o.shopify_customer_id is not null
      and (p_channels is null or o.sales_channel_handle = any(p_channels))
      and (
        p_not_channels is null
        or o.sales_channel_handle is null
        or not (o.sales_channel_handle = any(p_not_channels))
      )
    group by 1
  )
  select
    date_trunc(p_grain, f.first_at at time zone p_tz),
    count(*),
    count(*) filter (
      where c.email_marketing_state = 'SUBSCRIBED'
        and c.email_marketing_consent_updated_at < f.first_at - make_interval(mins => p_checkout_minutes)
    ),
    count(*) filter (
      where c.email_marketing_state = 'SUBSCRIBED'
        and c.email_marketing_consent_updated_at >= f.first_at - make_interval(mins => p_checkout_minutes)
        and c.email_marketing_consent_updated_at <= f.first_at + make_interval(mins => p_checkout_minutes)
    )
  from firsts f
  left join public.customers c
    on c.shop_id = p_shop
   and c.shopify_customer_id = f.customer
  where f.first_at >= (p_from at time zone p_tz)
    and f.first_at < (p_to at time zone p_tz)
  group by 1
  order by 1;
$function$;

CREATE OR REPLACE FUNCTION public.insights_collection_sales(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_channels text[] DEFAULT NULL::text[], p_not_channels text[] DEFAULT NULL::text[], p_limit integer DEFAULT 10, p_handles text[] DEFAULT NULL::text[])
 RETURNS TABLE(collection_id text, title text, handle text, products bigint, orders bigint, units bigint, revenue numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with ranged_lines as (
    select
      o.id as order_id,
      li.product_id as product_id,
      coalesce((li.current_quantity)::int, (li.quantity)::int, 0) as units,
      (li.discounted_total)::numeric as revenue
    from public.orders_in_range(p_shop, p_from, p_to, p_tz, p_channels, p_not_channels) o
    join public.order_lines li on li.order_id = o.id
    where li.product_id is not null
      and coalesce((li.discounted_total)::numeric, 0) > 0
  ),
  known as (
    select c.shopify_collection_id, c.title, c.handle, c.product_ids
    from public.advice_collections c
    where c.shop_id = p_shop
      and c.deleted_at is null
      and cardinality(c.product_ids) > 0
      and (p_handles is null or c.handle = any(p_handles))
  ),
  per_collection as (
    select
      k.shopify_collection_id as collection_id,
      max(k.title) as title,
      max(k.handle) as handle,
      count(distinct l.product_id) as products,
      count(distinct l.order_id) as orders,
      coalesce(sum(l.units), 0)::bigint as units,
      coalesce(sum(l.revenue), 0) as revenue
    from known k
    join ranged_lines l on l.product_id = any(k.product_ids)
    group by 1
    order by 7 desc, 2
    limit greatest(coalesce(p_limit, 10), 0)
  ),
  uncollected as (
    select
      null::text as collection_id,
      null::text as title,
      null::text as handle,
      count(distinct l.product_id) as products,
      count(distinct l.order_id) as orders,
      coalesce(sum(l.units), 0)::bigint as units,
      coalesce(sum(l.revenue), 0) as revenue
    from ranged_lines l
    where not exists (select 1 from known k where l.product_id = any(k.product_ids))
  )
  select * from per_collection
  union all
  select * from uncollected;
$function$;

CREATE OR REPLACE FUNCTION public.insights_country_product_sales(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_metric text, p_limit integer, p_vip_only boolean DEFAULT false, p_min_spend numeric DEFAULT NULL::numeric, p_min_orders integer DEFAULT NULL::integer, p_window_months integer DEFAULT NULL::integer, p_vip_not_channels text[] DEFAULT NULL::text[], p_channels text[] DEFAULT NULL::text[], p_not_channels text[] DEFAULT NULL::text[])
 RETURNS TABLE(country_code text, country_orders bigint, country_revenue numeric, product_id text, title text, orders bigint, units bigint, revenue numeric, rank bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with vip_keys as (
    select c.shopify_customer_id as customer_key
    from public.vip_customers(p_shop, p_min_spend, p_min_orders, p_window_months, p_vip_not_channels) v
    join public.customers c
      on c.id = v.customer_id
    where coalesce(p_vip_only, false)
  ),
  lines as (
    select
      coalesce(o.shipping_destination ->> 'country_code', '??') as country_code,
      o.id as order_id,
      o.total_price - coalesce(o.total_refunded, 0) as order_revenue,
      li.product_id as product_id,
      li.title as line_title,
      coalesce((li.current_quantity)::int, (li.quantity)::int, 0) as units,
      coalesce((li.discounted_total)::numeric, 0) as line_revenue
    from public.orders_in_range(p_shop, p_from, p_to, p_tz, p_channels, p_not_channels) o
    join public.order_lines li on li.order_id = o.id
    where li.product_id is not null
      and coalesce((li.discounted_total)::numeric, 0) > 0
      and (
        not coalesce(p_vip_only, false)
        or o.shopify_customer_id in (select vk.customer_key from vip_keys vk)
      )
  ),
  countries as (
    select
      c.country_code,
      count(distinct c.order_id) as country_orders,
      sum(c.order_revenue) as country_revenue
    from (select distinct l.country_code, l.order_id, l.order_revenue from lines l) c
    group by 1
  ),
  per_product as (
    select
      l.country_code,
      l.product_id,
      max(l.line_title) as line_title,
      count(distinct l.order_id) as orders,
      sum(l.units)::bigint as units,
      sum(l.line_revenue) as revenue
    from lines l
    group by 1, 2
  ),
  ranked as (
    select
      pp.*,
      row_number() over (
        partition by pp.country_code
        order by case when p_metric = 'orders' then pp.orders::numeric else pp.revenue end desc, pp.product_id
      ) as rank
    from per_product pp
  )
  select
    r.country_code,
    c.country_orders,
    c.country_revenue,
    r.product_id,
    coalesce(p.title, r.line_title),
    r.orders,
    r.units,
    r.revenue,
    r.rank
  from ranked r
  join countries c on c.country_code = r.country_code
  left join public.products p
    on p.shop_id = p_shop
   and p.shopify_product_id = r.product_id
  where r.rank <= p_limit
  order by c.country_revenue desc, r.country_code, r.rank;
$function$;

CREATE OR REPLACE FUNCTION public.insights_customer_mix(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_channels text[] DEFAULT NULL::text[], p_not_channels text[] DEFAULT NULL::text[])
 RETURNS TABLE(new_customers bigint, returning_customers bigint, new_customer_orders bigint, returning_customer_orders bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with ranged as (
    select o.shopify_customer_id as customer, count(*) as orders
    from public.orders o
    where o.shop_id = p_shop
      and o.deleted_at is null
      and o.cancelled_at is null
      and o.shopify_customer_id is not null
      and o.processed_at >= (p_from at time zone p_tz)
      and o.processed_at < (p_to at time zone p_tz)
      and (p_channels is null or o.sales_channel_handle = any(p_channels))
      and (
        p_not_channels is null
        or o.sales_channel_handle is null
        or not (o.sales_channel_handle = any(p_not_channels))
      )
    group by 1
  ),
  classified as (
    -- The first order is looked for on every channel, as before: "returning"
    -- means any earlier order of ours, whatever the filter shows.
    select
      r.orders,
      (
        select min(o.processed_at)
        from public.orders o
        where o.shop_id = p_shop
          and o.deleted_at is null
          and o.cancelled_at is null
          and o.shopify_customer_id = r.customer
      ) >= (p_from at time zone p_tz) as is_new
    from ranged r
  )
  select
    count(*) filter (where c.is_new),
    count(*) filter (where not c.is_new),
    coalesce(sum(c.orders) filter (where c.is_new), 0)::bigint,
    coalesce(sum(c.orders) filter (where not c.is_new), 0)::bigint
  from classified c;
$function$;

CREATE OR REPLACE FUNCTION public.insights_freshness(p_shop uuid)
 RETURNS TABLE(orders_synced_at timestamp with time zone, first_order_at timestamp with time zone, last_order_at timestamp with time zone, customers_synced_at timestamp with time zone, first_mail_at timestamp with time zone, mail_synced_through timestamp with time zone, topic_map_built_at timestamp with time zone, last_llm_call_at timestamp with time zone, nightly_sync_status text, nightly_sync_started_at timestamp with time zone, nightly_sync_finished_at timestamp with time zone)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with last_complete as (
    select max(ie.finished_at) as finished_at
    from public.integration_events ie
    where ie.shop_id = p_shop
      and ie.event_type = 'nightly_sync'
      and ie.status = 'completed'
  )
  select
    greatest(
      (select max(o.updated_at) from public.orders o where o.shop_id = p_shop),
      (select lc.finished_at from last_complete lc)
    ),
    (select min(o.processed_at) from public.orders o where o.shop_id = p_shop and o.deleted_at is null),
    (select max(o.processed_at) from public.orders o where o.shop_id = p_shop and o.deleted_at is null),
    greatest(
      (select max(c.updated_at) from public.customers c where c.shop_id = p_shop),
      (select lc.finished_at from last_complete lc)
    ),
    (select min(t.first_message_at) from public.tickets t where t.shop_id = p_shop and t.deleted_at is null),
    (
      select max(coalesce(m.sent_at, m.received_at))
      from public.ticket_messages m
      where m.shop_id = p_shop and m.deleted_at is null
    ),
    (select max(r.built_at) from public.cluster_runs r where r.shop_id = p_shop),
    (select max(u.occurred_at) from public.llm_usage u where u.shop_id = p_shop),
    e.status,
    e.started_at,
    e.finished_at
  from (select 1) as one
  left join lateral (
    select ie.status, ie.started_at, ie.finished_at
    from public.integration_events ie
    where ie.shop_id = p_shop
      and ie.event_type = 'nightly_sync'
    order by ie.created_at desc
    limit 1
  ) e on true;
$function$;

CREATE OR REPLACE FUNCTION public.insights_fulfilment_buckets(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_channels text[] DEFAULT NULL::text[], p_not_channels text[] DEFAULT NULL::text[])
 RETURNS TABLE(bucket text, bucket_order integer, orders bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select
    case
      when t.fulfilment_hours < 12 then '<12h'
      when t.fulfilment_hours < 24 then '12-24h'
      when t.fulfilment_hours < 48 then '24-48h'
      when t.fulfilment_hours < 72 then '48-72h'
      when t.fulfilment_hours < 96 then '72-96h'
      else '>96h'
    end,
    case
      when t.fulfilment_hours < 12 then 1
      when t.fulfilment_hours < 24 then 2
      when t.fulfilment_hours < 48 then 3
      when t.fulfilment_hours < 72 then 4
      when t.fulfilment_hours < 96 then 5
      else 6
    end,
    count(*)
  from public.order_fulfilment_timing t
  where t.shop_id = p_shop
    and t.fulfilment_hours is not null
    and t.processed_at >= (p_from at time zone p_tz)
    and t.processed_at < (p_to at time zone p_tz)
    and (p_channels is null or t.channel = any(p_channels))
    and (p_not_channels is null or t.channel is null or not (t.channel = any(p_not_channels)))
  group by 1, 2

  union all

  -- THE ORDERS THAT HAVE NOT SHIPPED AT ALL, which the six duration buckets
  -- cannot hold: an order still waiting has no duration to bucket, so without
  -- this row a shop with nothing over 96h reads as "everything went out inside
  -- four days" while an order sits unshipped on day ten. Same rule as
  -- open_orders(): not cancelled, not closed, nothing dispatched yet -- so the
  -- bar and the "Orders waiting to ship" list below it agree by construction.
  select 'Not shipped yet', 7, count(*)
  from public.orders o
  join public.order_fulfilment_timing t on t.order_id = o.id
  where o.shop_id = p_shop
    and t.first_fulfilled_at is null
    and o.cancelled_at is null
    and o.closed_at is null
    and o.fulfillment_status is not null
    and o.fulfillment_status not in ('FULFILLED', 'RESTOCKED')
    and o.processed_at >= (p_from at time zone p_tz)
    and o.processed_at < (p_to at time zone p_tz)
    and (p_channels is null or o.sales_channel_handle = any(p_channels))
    and (
      p_not_channels is null
      or o.sales_channel_handle is null
      or not (o.sales_channel_handle = any(p_not_channels))
    )
  having count(*) > 0

  order by 2;
$function$;

CREATE OR REPLACE FUNCTION public.insights_fulfilment_carriers(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_channels text[] DEFAULT NULL::text[], p_not_channels text[] DEFAULT NULL::text[])
 RETURNS TABLE(carrier text, shipments bigint, p50_hours double precision, over_72h bigint, without_tracking bigint, orders_with_ticket bigint, tickets bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select
    t.carrier,
    count(*),
    percentile_cont(0.5) within group (order by t.fulfilment_hours),
    count(*) filter (where t.fulfilment_hours > 72),
    count(*) filter (where t.tracking_count = 0),
    count(*) filter (where k.tickets > 0),
    coalesce(sum(k.tickets), 0)::bigint
  from public.order_fulfilment_timing t
  left join lateral (
    select count(*) as tickets
    from public.tickets tk
    where tk.shop_id = t.shop_id
      and tk.deleted_at is null
      and tk.shopify_order_number = t.order_name
  ) k on true
  where t.shop_id = p_shop
    and t.carrier is not null
    and t.processed_at >= (p_from at time zone p_tz)
    and t.processed_at < (p_to at time zone p_tz)
    and (p_channels is null or t.channel = any(p_channels))
    and (p_not_channels is null or t.channel is null or not (t.channel = any(p_not_channels)))
  group by 1
  order by 2 desc;
$function$;

CREATE OR REPLACE FUNCTION public.insights_inventory_exceptions(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_max_cover_days numeric, p_max_stock_units integer)
 RETURNS TABLE(product_id text, title text, product_type text, stock integer, units_out bigint, window_days numeric, cover_days numeric, synced_at timestamp with time zone)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with window_span as (
    select greatest(extract(epoch from (p_to - p_from)) / 86400.0, 1)::numeric as days
  ),
  shipped as (
    select
      li.product_id as product_id,
      sum(coalesce((li.current_quantity)::int, (li.quantity)::int, 0))::bigint as units
    from public.orders o
    join public.order_lines li on li.order_id = o.id
    where o.shop_id = p_shop
      and o.deleted_at is null
      and o.cancelled_at is null
      and li.product_id is not null
      and o.processed_at >= (p_from at time zone p_tz)
      and o.processed_at < (p_to at time zone p_tz)
    group by 1
  ),
  measured as (
    select
      p.shopify_product_id,
      p.title,
      p.product_type,
      p.available_stock,
      coalesce(s.units, 0) as units,
      w.days,
      case
        when coalesce(s.units, 0) > 0 then round(greatest(p.available_stock, 0) * w.days / s.units, 1)
      end as cover,
      p.synced_at
    from public.products p
    cross join window_span w
    left join shipped s on s.product_id = p.shopify_product_id
    where p.shop_id = p_shop
      and p.deleted_at is null
      and p.status = 'active'
      and p.available_stock is not null
  )
  select m.shopify_product_id, m.title, m.product_type, m.available_stock, m.units, round(m.days, 1), m.cover, m.synced_at
  from measured m
  where m.available_stock <= 0
     or (m.cover is not null and m.cover <= p_max_cover_days)
     or m.available_stock < p_max_stock_units
  order by m.available_stock > 0, m.cover nulls last, m.available_stock, m.units desc, m.title;
$function$;

CREATE OR REPLACE FUNCTION public.insights_klaviyo_messages(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text)
 RETURNS TABLE(kind text, id text, name text, sent_at timestamp with time zone, recipients bigint, delivered bigint, opens_unique bigint, clicks_unique bigint, conversions bigint, conversion_value numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select
    'flow'::text,
    f.flow_id,
    (array_agg(f.flow_name order by f.day desc) filter (where f.flow_name is not null))[1],
    null::timestamptz,
    sum(f.recipients)::bigint,
    sum(f.delivered)::bigint,
    sum(f.opens_unique)::bigint,
    sum(f.clicks_unique)::bigint,
    sum(f.conversions)::bigint,
    sum(f.conversion_value)
  from public.klaviyo_flow_days f
  where f.shop_id = p_shop
    and f.day >= p_from::date
    and f.day::timestamp < p_to
  group by f.flow_id
  union all
  select
    'campaign'::text,
    c.campaign_id,
    c.name,
    c.send_time,
    c.recipients,
    c.delivered,
    c.opens_unique,
    c.clicks_unique,
    c.conversions,
    c.conversion_value
  from public.klaviyo_campaigns c
  where c.shop_id = p_shop
    and c.send_time >= (p_from at time zone p_tz)
    and c.send_time < (p_to at time zone p_tz);
$function$;

CREATE OR REPLACE FUNCTION public.insights_llm_series(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_grain text)
 RETURNS TABLE(bucket timestamp without time zone, model text, calls bigint, input_tokens bigint, output_tokens bigint, total_tokens bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select
    date_trunc(p_grain, u.occurred_at at time zone p_tz),
    u.model,
    coalesce(sum(u.call_count), 0)::bigint,
    coalesce(sum(u.input_tokens), 0)::bigint,
    coalesce(sum(u.output_tokens), 0)::bigint,
    coalesce(sum(u.total_tokens), 0)::bigint
  from public.llm_usage u
  where u.shop_id = p_shop
    and u.occurred_at >= (p_from at time zone p_tz)
    and u.occurred_at < (p_to at time zone p_tz)
  group by 1, 2
  order by 1, 2;
$function$;

CREATE OR REPLACE FUNCTION public.insights_llm_ticket_stats(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text)
 RETURNS TABLE(tickets_touched bigint, mean_tokens_per_ticket double precision, max_tokens_on_a_ticket bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select
    count(*),
    avg(s.ticket_tokens)::double precision,
    max(s.ticket_tokens)::bigint
  from (
    select u.ticket_id, sum(u.total_tokens) as ticket_tokens
    from public.llm_usage u
    where u.shop_id = p_shop
      and u.ticket_id is not null
      and u.occurred_at >= (p_from at time zone p_tz)
      and u.occurred_at < (p_to at time zone p_tz)
    group by 1
  ) s;
$function$;

CREATE OR REPLACE FUNCTION public.insights_llm_usage(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text)
 RETURNS TABLE(model text, pass text, calls bigint, input_tokens bigint, output_tokens bigint, total_tokens bigint, failed_calls bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select
    u.model,
    u.pass,
    coalesce(sum(u.call_count), 0)::bigint,
    coalesce(sum(u.input_tokens), 0)::bigint,
    coalesce(sum(u.output_tokens), 0)::bigint,
    coalesce(sum(u.total_tokens), 0)::bigint,
    count(*) filter (where not u.succeeded)
  from public.llm_usage u
  where u.shop_id = p_shop
    and u.occurred_at >= (p_from at time zone p_tz)
    and u.occurred_at < (p_to at time zone p_tz)
  group by 1, 2
  order by 6 desc;
$function$;

CREATE OR REPLACE FUNCTION public.insights_marketing_series(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_grain text)
 RETURNS TABLE(bucket timestamp without time zone, subscribed bigint, unsubscribed bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select
    date_trunc(p_grain, c.email_marketing_consent_updated_at at time zone p_tz),
    count(*) filter (where c.email_marketing_state = 'SUBSCRIBED'),
    count(*) filter (where c.email_marketing_state = 'UNSUBSCRIBED')
  from public.customers c
  where c.shop_id = p_shop
    and c.deleted_at is null
    and c.email_marketing_state in ('SUBSCRIBED', 'UNSUBSCRIBED')
    and c.email_marketing_consent_updated_at >= (p_from at time zone p_tz)
    and c.email_marketing_consent_updated_at < (p_to at time zone p_tz)
  group by 1
  order by 1;
$function$;

CREATE OR REPLACE FUNCTION public.insights_marketing_summary(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text)
 RETURNS TABLE(subscribed bigint, unsubscribed bigint, list_at_start bigint, subscribers_now bigint, consent_through timestamp with time zone, unsubscribes_from timestamp with time zone)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select
    count(*) filter (
      where c.email_marketing_state = 'SUBSCRIBED'
        and c.email_marketing_consent_updated_at >= (p_from at time zone p_tz)
        and c.email_marketing_consent_updated_at < (p_to at time zone p_tz)
    ),
    count(*) filter (
      where c.email_marketing_state = 'UNSUBSCRIBED'
        and c.email_marketing_consent_updated_at >= (p_from at time zone p_tz)
        and c.email_marketing_consent_updated_at < (p_to at time zone p_tz)
    ),
    count(*) filter (
      where (
        c.email_marketing_state = 'SUBSCRIBED'
        and coalesce(c.email_marketing_consent_updated_at, '-infinity'::timestamptz) < (p_from at time zone p_tz)
      ) or (
        c.email_marketing_state = 'UNSUBSCRIBED'
        and c.email_marketing_consent_updated_at >= (p_from at time zone p_tz)
      )
    ),
    count(*) filter (where c.email_marketing_state = 'SUBSCRIBED'),
    max(c.email_marketing_consent_updated_at),
    -- The earliest unsubscribe the snapshot still holds. Before it, subscribes
    -- appear and unsubscribes cannot, so a churn or net figure there is not
    -- low, it is unmeasured: the caller hatches that span and will not compare
    -- against it.
    min(c.email_marketing_consent_updated_at) filter (where c.email_marketing_state = 'UNSUBSCRIBED')
  from public.customers c
  where c.shop_id = p_shop
    and c.deleted_at is null;
$function$;

CREATE OR REPLACE FUNCTION public.insights_orders_by_channel(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text)
 RETURNS TABLE(channel text, channel_label text, orders bigint, revenue numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select
    o.sales_channel_handle,
    max(o.sales_channel),
    count(*) filter (where o.cancelled_at is null),
    coalesce(sum(o.total_price - coalesce(o.total_refunded, 0)) filter (where o.cancelled_at is null), 0)
  from public.orders o
  where o.shop_id = p_shop
    and o.deleted_at is null
    and o.processed_at >= (p_from at time zone p_tz)
    and o.processed_at < (p_to at time zone p_tz)
  group by 1
  order by 4 desc;
$function$;

CREATE OR REPLACE FUNCTION public.insights_orders_by_country(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_channels text[] DEFAULT NULL::text[], p_not_channels text[] DEFAULT NULL::text[])
 RETURNS TABLE(country_code text, orders bigint, revenue numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select
    coalesce(o.shipping_destination ->> 'country_code', '??'),
    count(*),
    coalesce(sum(o.total_price - coalesce(o.total_refunded, 0)), 0)
  from public.orders_in_range(p_shop, p_from, p_to, p_tz, p_channels, p_not_channels) o
  group by 1
  order by 3 desc;
$function$;

CREATE OR REPLACE FUNCTION public.insights_orders_per_customer(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_channels text[] DEFAULT NULL::text[], p_not_channels text[] DEFAULT NULL::text[])
 RETURNS TABLE(order_count integer, customers bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select per.n::integer, count(*)
  from (
    select o.shopify_customer_id, count(*) as n
    from public.orders_in_range(p_shop, p_from, p_to, p_tz, p_channels, p_not_channels) o
    where o.shopify_customer_id is not null
    group by 1
  ) per
  group by 1
  order by 1;
$function$;

CREATE OR REPLACE FUNCTION public.insights_orders_series(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_grain text, p_channels text[] DEFAULT NULL::text[], p_not_channels text[] DEFAULT NULL::text[])
 RETURNS TABLE(bucket timestamp without time zone, orders bigint, revenue numeric, measured bigint, over_72h bigint, p50_hours double precision)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select
    date_trunc(p_grain, t.processed_at at time zone p_tz),
    count(*),
    coalesce(sum(t.total_price - coalesce(t.total_refunded, 0)) filter (where o.cancelled_at is null), 0),
    count(*) filter (where t.fulfilment_hours is not null),
    count(*) filter (where t.fulfilment_hours > 72),
    percentile_cont(0.5) within group (order by t.fulfilment_hours)
  from public.order_fulfilment_timing t
  join public.orders o on o.id = t.order_id
  where t.shop_id = p_shop
    and t.processed_at >= (p_from at time zone p_tz)
    and t.processed_at < (p_to at time zone p_tz)
    and (p_channels is null or t.channel = any(p_channels))
    and (p_not_channels is null or t.channel is null or not (t.channel = any(p_not_channels)))
  group by 1
  order by 1;
$function$;

CREATE OR REPLACE FUNCTION public.insights_orders_summary(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_channels text[] DEFAULT NULL::text[], p_not_channels text[] DEFAULT NULL::text[])
 RETURNS TABLE(orders bigint, cancelled_orders bigint, revenue numeric, gross_revenue numeric, measured bigint, p50_hours double precision, p90_hours double precision, mean_hours double precision, over_72h bigint, shipped_without_tracking bigint, with_delivery_event bigint, refunded_orders bigint, fully_refunded_orders bigint, returns_opened bigint, refunded_amount numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select
    count(*),
    count(*) filter (where o.cancelled_at is not null),
    coalesce(sum(t.total_price - coalesce(t.total_refunded, 0)) filter (where o.cancelled_at is null), 0),
    coalesce(sum(t.total_price) filter (where o.cancelled_at is null), 0),
    count(*) filter (where t.fulfilment_hours is not null),
    percentile_cont(0.5) within group (order by t.fulfilment_hours),
    percentile_cont(0.9) within group (order by t.fulfilment_hours),
    avg(t.fulfilment_hours)::double precision,
    count(*) filter (where t.fulfilment_hours > 72),
    count(*) filter (where t.fulfilment_count > 0 and t.tracking_count = 0),
    count(*) filter (where t.delivered_at is not null),
    count(*) filter (where t.total_refunded > 0),
    count(*) filter (
      where t.total_refunded > 0 and t.total_price > 0 and t.total_refunded >= t.total_price
    ),
    count(*) filter (where t.return_status is not null and t.return_status <> 'NO_RETURN'),
    coalesce(sum(t.total_refunded), 0)
  from public.order_fulfilment_timing t
  join public.orders o on o.id = t.order_id
  where t.shop_id = p_shop
    and t.processed_at >= (p_from at time zone p_tz)
    and t.processed_at < (p_to at time zone p_tz)
    and (p_channels is null or t.channel = any(p_channels))
    and (p_not_channels is null or t.channel is null or not (t.channel = any(p_not_channels)));
$function$;

CREATE OR REPLACE FUNCTION public.insights_paid_campaigns(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_limit integer DEFAULT 200)
 RETURNS TABLE(kind text, account_id uuid, account_external_id text, account_name text, login_customer_id text, campaign_id text, name text, status text, objective text, currency text, spend numeric, impressions bigint, clicks bigint, conversions numeric, conversion_value numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select
    a.kind,
    a.id,
    a.external_id,
    a.name,
    a.login_customer_id,
    d.campaign_id,
    c.name,
    c.status,
    c.objective,
    d.currency,
    sum(d.spend),
    sum(d.impressions)::bigint,
    sum(d.clicks)::bigint,
    sum(d.conversions),
    sum(d.conversion_value)
  from public.ad_campaign_days d
  join public.social_accounts a on a.id = d.account_id and a.enabled
  left join public.ad_campaigns c on c.account_id = d.account_id and c.external_id = d.campaign_id
  where d.shop_id = p_shop
    and d.day >= p_from::date
    and d.day::timestamp < p_to
  group by a.kind, a.id, a.external_id, a.name, a.login_customer_id, d.campaign_id, c.name, c.status, c.objective, d.currency
  order by sum(d.spend) desc, sum(d.impressions) desc
  limit greatest(coalesce(p_limit, 200), 1);
$function$;

CREATE OR REPLACE FUNCTION public.insights_paid_series(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_grain text)
 RETURNS TABLE(kind text, account_id uuid, currency text, publisher text, bucket timestamp without time zone, spend numeric, impressions bigint, clicks bigint, conversions numeric, conversion_value numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select
    a.kind,
    a.id,
    d.currency,
    d.publisher,
    date_trunc(case when p_grain = 'hour' then 'day' else p_grain end, d.day::timestamp),
    sum(d.spend),
    sum(d.impressions)::bigint,
    sum(d.clicks)::bigint,
    sum(d.conversions),
    sum(d.conversion_value)
  from public.ad_days d
  join public.social_accounts a on a.id = d.account_id and a.enabled
  where d.shop_id = p_shop
    and d.day >= p_from::date
    and d.day::timestamp < p_to
  group by a.kind, a.id, d.currency, d.publisher, 5;
$function$;

CREATE OR REPLACE FUNCTION public.insights_product_customer_mix(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_product_id text, p_country text DEFAULT NULL::text, p_vip_only boolean DEFAULT false, p_min_spend numeric DEFAULT NULL::numeric, p_min_orders integer DEFAULT NULL::integer, p_window_months integer DEFAULT NULL::integer, p_vip_not_channels text[] DEFAULT NULL::text[], p_channels text[] DEFAULT NULL::text[], p_not_channels text[] DEFAULT NULL::text[])
 RETURNS TABLE(customers bigint, only_customers bigint, with_other_customers bigint, without_customers bigint, other_product_id text, other_title text, other_customers bigint, other_rank bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with vip_keys as (
    select c.shopify_customer_id as customer_key
    from public.vip_customers(p_shop, p_min_spend, p_min_orders, p_window_months, p_vip_not_channels) v
    join public.customers c
      on c.id = v.customer_id
    where coalesce(p_vip_only, false)
  ),
  ranged_orders as (
    select
      o.id as order_id,
      o.shopify_customer_id as customer_key,
      o.line_items
    from public.orders_in_range(p_shop, p_from, p_to, p_tz, p_channels, p_not_channels) o
    where o.shopify_customer_id is not null
      and (p_country is null or coalesce(o.shipping_destination ->> 'country_code', '??') = p_country)
      and (
        not coalesce(p_vip_only, false)
        or o.shopify_customer_id in (select vk.customer_key from vip_keys vk)
      )
  ),
  paid_lines as (
    select
      ro.customer_key,
      li.product_id as product_id,
      li.title as line_title
    from ranged_orders ro
    join public.order_lines li on li.order_id = ro.order_id
    where li.product_id is not null
      and coalesce((li.discounted_total)::numeric, 0) > 0
  ),
  buyers as (
    select distinct pl.customer_key
    from paid_lines pl
    where pl.product_id = p_product_id
  ),
  buyer_sets as (
    select
      b.customer_key,
      count(distinct pl.product_id) filter (where pl.product_id <> p_product_id) as other_products
    from buyers b
    join paid_lines pl on pl.customer_key = b.customer_key
    group by 1
  ),
  split as (
    select
      (select count(distinct ro.customer_key) from ranged_orders ro) as customers,
      count(*) filter (where bs.other_products = 0) as only_customers,
      count(*) filter (where bs.other_products > 0) as with_other_customers
    from buyer_sets bs
  ),
  others as (
    select
      pl.product_id as other_product_id,
      max(pl.line_title) as line_title,
      count(distinct pl.customer_key) as other_customers
    from buyers b
    join paid_lines pl
      on pl.customer_key = b.customer_key
     and pl.product_id <> p_product_id
    group by 1
  ),
  ranked as (
    select
      ot.other_product_id,
      ot.line_title,
      ot.other_customers,
      row_number() over (order by ot.other_customers desc, ot.other_product_id) as other_rank
    from others ot
  )
  select
    s.customers,
    s.only_customers,
    s.with_other_customers,
    greatest(s.customers - s.only_customers - s.with_other_customers, 0)::bigint as without_customers,
    r.other_product_id,
    coalesce(p.title, r.line_title) as other_title,
    r.other_customers,
    r.other_rank
  from split s
  left join ranked r on r.other_rank <= 7
  left join public.products p
    on p.shop_id = p_shop
   and p.shopify_product_id = r.other_product_id
  order by r.other_rank nulls last;
$function$;

CREATE OR REPLACE FUNCTION public.insights_product_orders_per_customer(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_product_id text, p_country text DEFAULT NULL::text, p_vip_only boolean DEFAULT false, p_min_spend numeric DEFAULT NULL::numeric, p_min_orders integer DEFAULT NULL::integer, p_window_months integer DEFAULT NULL::integer, p_vip_not_channels text[] DEFAULT NULL::text[], p_channels text[] DEFAULT NULL::text[], p_not_channels text[] DEFAULT NULL::text[])
 RETURNS TABLE(order_count integer, customers bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with vip_keys as (
    select c.shopify_customer_id as customer_key
    from public.vip_customers(p_shop, p_min_spend, p_min_orders, p_window_months, p_vip_not_channels) v
    join public.customers c
      on c.id = v.customer_id
    where coalesce(p_vip_only, false)
  ),
  ranged_orders as (
    select
      o.id as order_id,
      o.shopify_customer_id as customer_key,
      o.line_items
    from public.orders_in_range(p_shop, p_from, p_to, p_tz, p_channels, p_not_channels) o
    where o.shopify_customer_id is not null
      and (p_country is null or coalesce(o.shipping_destination ->> 'country_code', '??') = p_country)
      and (
        not coalesce(p_vip_only, false)
        or o.shopify_customer_id in (select vk.customer_key from vip_keys vk)
      )
  ),
  product_orders as (
    select distinct
      ro.customer_key,
      ro.order_id
    from ranged_orders ro
    join public.order_lines li on li.order_id = ro.order_id
    where li.product_id = p_product_id
      and coalesce((li.discounted_total)::numeric, 0) > 0
  ),
  per_customer as (
    select po.customer_key, count(*) as n
    from product_orders po
    group by 1
  )
  select pc.n::integer, count(*)
  from per_customer pc
  group by 1
  order by 1;
$function$;

CREATE OR REPLACE FUNCTION public.insights_product_pairs(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_limit integer, p_channels text[] DEFAULT NULL::text[], p_not_channels text[] DEFAULT NULL::text[])
 RETURNS TABLE(country_code text, product_a text, title_a text, product_b text, title_b text, orders bigint, revenue numeric, rank_by_orders bigint, rank_by_revenue bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with per_line as (
    select
      o.id as order_id,
      coalesce(o.shipping_destination ->> 'country_code', '??') as country_code,
      li.product_id as product_id,
      max(li.title) as line_title,
      sum(coalesce((li.discounted_total)::numeric, 0)) as revenue
    from public.orders_in_range(p_shop, p_from, p_to, p_tz, p_channels, p_not_channels) o
    join public.order_lines li on li.order_id = o.id
    where li.product_id is not null
      and coalesce((li.discounted_total)::numeric, 0) > 0
    group by 1, 2, 3
  ),
  pairs as (
    select
      a.country_code,
      a.product_id as product_a,
      a.line_title as line_title_a,
      b.product_id as product_b,
      b.line_title as line_title_b,
      a.revenue + b.revenue as revenue
    from per_line a
    join per_line b
      on b.order_id = a.order_id
     and a.product_id < b.product_id
  ),
  grouped as (
    select
      p.country_code,
      p.product_a,
      max(p.line_title_a) as line_title_a,
      p.product_b,
      max(p.line_title_b) as line_title_b,
      count(*) as orders,
      sum(p.revenue) as revenue
    from pairs p
    group by grouping sets ((p.product_a, p.product_b), (p.country_code, p.product_a, p.product_b))
  ),
  ranked as (
    select
      g.*,
      row_number() over (
        partition by g.country_code order by g.orders desc, g.revenue desc, g.product_a, g.product_b
      ) as rank_by_orders,
      row_number() over (
        partition by g.country_code order by g.revenue desc, g.orders desc, g.product_a, g.product_b
      ) as rank_by_revenue
    from grouped g
  )
  select
    r.country_code,
    r.product_a,
    coalesce(pa.title, r.line_title_a),
    r.product_b,
    coalesce(pb.title, r.line_title_b),
    r.orders,
    r.revenue,
    r.rank_by_orders,
    r.rank_by_revenue
  from ranked r
  left join public.products pa on pa.shop_id = p_shop and pa.shopify_product_id = r.product_a
  left join public.products pb on pb.shop_id = p_shop and pb.shopify_product_id = r.product_b
  where r.rank_by_orders <= p_limit
     or r.rank_by_revenue <= p_limit
  order by r.country_code nulls first, r.rank_by_orders;
$function$;

CREATE OR REPLACE FUNCTION public.insights_product_sales(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_vip_only boolean DEFAULT false, p_min_spend numeric DEFAULT NULL::numeric, p_min_orders integer DEFAULT NULL::integer, p_window_months integer DEFAULT NULL::integer, p_vip_not_channels text[] DEFAULT NULL::text[], p_channels text[] DEFAULT NULL::text[], p_not_channels text[] DEFAULT NULL::text[])
 RETURNS TABLE(product_id text, title text, tags text[], orders bigint, units bigint, revenue numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with vip_keys as (
    select c.shopify_customer_id as customer_key
    from public.vip_customers(p_shop, p_min_spend, p_min_orders, p_window_months, p_vip_not_channels) v
    join public.customers c
      on c.id = v.customer_id
    where coalesce(p_vip_only, false)
  )
  select
    li.product_id,
    coalesce(max(p.title), max(li.title)),
    max(p.tags),
    count(distinct o.id),
    coalesce(sum(coalesce((li.current_quantity)::int, (li.quantity)::int, 0)), 0)::bigint,
    coalesce(sum((li.discounted_total)::numeric), 0)
  from public.orders_in_range(p_shop, p_from, p_to, p_tz, p_channels, p_not_channels) o
  join public.order_lines li on li.order_id = o.id
  left join public.products p
    on p.shop_id = o.shop_id
   and p.shopify_product_id = li.product_id
  where li.product_id is not null
    and coalesce((li.discounted_total)::numeric, 0) > 0
    and (
      not coalesce(p_vip_only, false)
      or o.shopify_customer_id in (select vk.customer_key from vip_keys vk)
    )
  group by 1
  order by 6 desc;
$function$;

CREATE OR REPLACE FUNCTION public.insights_promotions(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_channels text[] DEFAULT NULL::text[], p_not_channels text[] DEFAULT NULL::text[], p_people_not_channels text[] DEFAULT NULL::text[], p_limit integer DEFAULT 12)
 RETURNS TABLE(promotion text, kind text, target text, orders bigint, revenue numeric, discount numeric, new_customer_orders bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with ranged as (
    select
      o.id,
      o.shopify_customer_id,
      o.sales_channel_handle,
      o.processed_at,
      coalesce(o.total_price, 0) - coalesce(o.total_refunded, 0) as net,
      o.discount_applications,
      o.line_items
    from public.orders_in_range(p_shop, p_from, p_to, p_tz, p_channels, p_not_channels) o
  ),
  flagged as (
    select
      r.id,
      r.net,
      r.shopify_customer_id is not null
        and (
          p_people_not_channels is null
          or r.sales_channel_handle is null
          or not (r.sales_channel_handle = any(p_people_not_channels))
        )
        and not exists (
          select 1
          from public.orders e
          where e.shop_id = p_shop
            and e.deleted_at is null
            and e.cancelled_at is null
            and e.shopify_customer_id = r.shopify_customer_id
            and e.processed_at < r.processed_at
        ) as is_new
    from ranged r
  ),
  applied as (
    select r.id, a.value ->> 'name' as promotion, max(a.value ->> 'kind') as kind, max(a.value ->> 'target_type') as target
    from ranged r
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(r.discount_applications) = 'array' then r.discount_applications else '[]'::jsonb end
    ) as a
    where nullif(a.value ->> 'name', '') is not null
    group by 1, 2
  ),
  line_discounts as (
    select r.id, d.value ->> 'name' as promotion, sum(coalesce((d.value ->> 'amount')::numeric, 0)) as amount
    from ranged r
    join public.order_lines li on li.order_id = r.id
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(li.discounts) = 'array' then li.discounts else '[]'::jsonb end
    ) as d
    group by 1, 2
  ),
  per_promotion as (
    select
      a.promotion,
      max(a.kind) as kind,
      max(a.target) as target,
      count(*) as orders,
      coalesce(sum(f.net), 0) as revenue,
      coalesce(sum(ld.amount), 0) as discount,
      count(*) filter (where f.is_new) as new_customer_orders
    from applied a
    join flagged f on f.id = a.id
    left join line_discounts ld on ld.id = a.id and ld.promotion = a.promotion
    group by a.promotion
    order by 4 desc, 1
    limit greatest(coalesce(p_limit, 12), 0)
  ),
  full_price as (
    select
      null::text as promotion,
      null::text as kind,
      null::text as target,
      count(*) as orders,
      coalesce(sum(f.net), 0) as revenue,
      0::numeric as discount,
      count(*) filter (where f.is_new) as new_customer_orders
    from flagged f
    where not exists (select 1 from applied a where a.id = f.id)
  )
  select * from per_promotion
  union all
  select * from full_price;
$function$;

CREATE OR REPLACE FUNCTION public.insights_sales_overview(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_channels text[] DEFAULT NULL::text[], p_not_channels text[] DEFAULT NULL::text[])
 RETURNS TABLE(paid_orders bigint, units bigint, discounts numeric, discounted_orders bigint, discounted_revenue numeric, full_price_revenue numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with ranged as (
    select o.id, o.total_price, o.total_refunded, o.total_discounts, o.line_items
    from public.orders_in_range(p_shop, p_from, p_to, p_tz, p_channels, p_not_channels) o
  ),
  paid_units as (
    select coalesce(sum(coalesce((li.current_quantity)::int, (li.quantity)::int, 0)), 0)::bigint as units
    from ranged r
    join public.order_lines li on li.order_id = r.id
    where li.product_id is not null
      and coalesce((li.discounted_total)::numeric, 0) > 0
  )
  select
    count(*),
    (select pu.units from paid_units pu),
    coalesce(sum(coalesce(r.total_discounts, 0)), 0),
    count(*) filter (where coalesce(r.total_discounts, 0) > 0),
    coalesce(sum(coalesce(r.total_price, 0) - coalesce(r.total_refunded, 0)) filter (where coalesce(r.total_discounts, 0) > 0), 0),
    coalesce(sum(coalesce(r.total_price, 0) - coalesce(r.total_refunded, 0)) filter (where coalesce(r.total_discounts, 0) = 0), 0)
  from ranged r;
$function$;

CREATE OR REPLACE FUNCTION public.insights_social_audience(p_shop uuid)
 RETURNS TABLE(kind text, account_id uuid, captured_on date, dimension text, key text, value bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select a.kind, a.id, s.captured_on, s.dimension, s.key, s.value
  from public.social_accounts a
  join public.social_audience s on s.account_id = a.id
  where a.shop_id = p_shop
    and a.enabled
    and s.captured_on = (select max(x.captured_on) from public.social_audience x where x.account_id = a.id);
$function$;

CREATE OR REPLACE FUNCTION public.insights_social_followers(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone)
 RETURNS TABLE(kind text, account_id uuid, followers_end bigint, end_day date, followers_start bigint, start_day date)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select
    a.kind,
    a.id,
    e.followers,
    e.day,
    s.followers,
    s.day
  from public.social_accounts a
  left join lateral (
    select d.followers, d.day
    from public.social_account_days d
    where d.account_id = a.id
      and d.followers is not null
      and d.day::timestamp < p_to
    order by d.day desc
    limit 1
  ) e on true
  left join lateral (
    select d.followers, d.day
    from public.social_account_days d
    where d.account_id = a.id
      and d.followers is not null
      and d.day < p_from::date
    order by d.day desc
    limit 1
  ) s on true
  where a.shop_id = p_shop
    and a.enabled
    and a.kind in ('instagram', 'facebook', 'tiktok');
$function$;

CREATE OR REPLACE FUNCTION public.insights_social_post_totals(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text)
 RETURNS TABLE(kind text, account_id uuid, posts bigint, views bigint, engagement bigint, rated_engagement bigint, rated_reach bigint, engaged_posts bigint, rated_views_engagement bigint, rated_views bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select
    a.kind,
    a.id,
    count(*)::bigint,
    sum(p.views)::bigint,
    sum(p.engagement)::bigint,
    sum(p.engagement) filter (where p.reach > 0 and p.engagement is not null)::bigint,
    sum(p.reach) filter (where p.reach > 0 and p.engagement is not null)::bigint,
    (count(*) filter (where p.engagement is not null))::bigint,
    sum(p.engagement) filter (where p.views > 0 and p.engagement is not null)::bigint,
    sum(p.views) filter (where p.views > 0 and p.engagement is not null)::bigint
  from public.social_posts p
  join public.social_accounts a on a.id = p.account_id and a.enabled
  where p.shop_id = p_shop
    and p.published_at >= (p_from at time zone p_tz)
    and p.published_at < (p_to at time zone p_tz)
  group by a.kind, a.id;
$function$;

CREATE OR REPLACE FUNCTION public.insights_social_posts(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_limit integer DEFAULT 500)
 RETURNS TABLE(kind text, account_id uuid, external_id text, published_at timestamp with time zone, media_type text, caption_excerpt text, permalink text, thumbnail_url text, views bigint, reach bigint, likes bigint, comments bigint, shares bigint, saves bigint, follows bigint, engagement bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select
    a.kind,
    a.id,
    p.external_id,
    p.published_at,
    p.media_type,
    p.caption_excerpt,
    p.permalink,
    p.thumbnail_url,
    p.views,
    p.reach,
    p.likes,
    p.comments,
    p.shares,
    p.saves,
    p.follows,
    p.engagement
  from public.social_posts p
  join public.social_accounts a on a.id = p.account_id and a.enabled
  where p.shop_id = p_shop
    and p.published_at >= (p_from at time zone p_tz)
    and p.published_at < (p_to at time zone p_tz)
  order by p.views desc nulls last, p.published_at desc
  limit greatest(coalesce(p_limit, 500), 1);
$function$;

CREATE OR REPLACE FUNCTION public.insights_social_series(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_grain text)
 RETURNS TABLE(kind text, account_id uuid, bucket timestamp without time zone, views bigint, engagement bigint, profile_visits bigint, link_taps bigint, follows bigint, unfollows bigint, posts bigint, days_measured bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select
    a.kind,
    a.id,
    date_trunc(case when p_grain = 'hour' then 'day' else p_grain end, d.day::timestamp),
    sum(d.views)::bigint,
    sum(d.engagement)::bigint,
    sum(d.profile_visits)::bigint,
    sum(d.link_taps)::bigint,
    sum(d.follows)::bigint,
    sum(d.unfollows)::bigint,
    sum(d.posts)::bigint,
    count(*)::bigint
  from public.social_account_days d
  join public.social_accounts a on a.id = d.account_id and a.enabled
  where d.shop_id = p_shop
    and d.day >= p_from::date
    and d.day::timestamp < p_to
  group by a.kind, a.id, 3;
$function$;

CREATE OR REPLACE FUNCTION public.insights_support_categories(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text)
 RETURNS TABLE(category text, tickets bigint, still_open bigint, unhappy bigint, level_three bigint, mean_happiness double precision, buyer_tickets bigint, no_order_tickets bigint, unknown_tickets bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select
    t.category,
    count(*),
    count(*) filter (where t.status not in ('resolved', 'closed')),
    count(*) filter (where t.happiness >= 3),
    count(*) filter (where t.level = 3),
    avg(t.happiness)::double precision,
    count(*) filter (where t.customer_id is not null and coalesce(c.number_of_orders, 0) > 0),
    count(*) filter (where t.customer_id is not null and coalesce(c.number_of_orders, 0) = 0),
    count(*) filter (where t.customer_id is null)
  from public.case_facts t
  left join public.customers c on c.id = t.customer_id
  where t.shop_id = p_shop
    and t.first_message_at >= (p_from at time zone p_tz)
    and t.first_message_at < (p_to at time zone p_tz)
  group by 1
  order by 2 desc, 1;
$function$;

CREATE OR REPLACE FUNCTION public.insights_support_series(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_grain text)
 RETURNS TABLE(bucket timestamp without time zone, tickets bigint, unhappy bigint, replies_measured bigint, p50_reply_hours double precision)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select
    date_trunc(p_grain, t.first_message_at at time zone p_tz),
    count(*),
    count(*) filter (where t.happiness >= 3),
    count(*) filter (where t.reply_hours is not null),
    percentile_cont(0.5) within group (order by t.reply_hours)
  from public.case_facts t
  where t.shop_id = p_shop
    and t.first_message_at >= (p_from at time zone p_tz)
    and t.first_message_at < (p_to at time zone p_tz)
  group by 1
  order by 1;
$function$;

CREATE OR REPLACE FUNCTION public.insights_support_summary(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text)
 RETURNS TABLE(tickets bigint, categorised bigint, still_open bigint, unhappy bigint, very_unhappy bigint, level_three bigint, replies_measured bigint, p50_reply_hours double precision, p90_reply_hours double precision, replied_within_24h bigint, buyer_tickets bigint, no_order_tickets bigint, unknown_tickets bigint, no_order_customers bigint, no_order_deliverable bigint, no_order_marketable bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select
    count(*),
    count(*) filter (where t.category is not null),
    count(*) filter (where t.status not in ('resolved', 'closed')),
    count(*) filter (where t.happiness >= 3),
    count(*) filter (where t.happiness = 4),
    count(*) filter (where t.level = 3),
    count(*) filter (where t.reply_hours is not null),
    percentile_cont(0.5) within group (order by t.reply_hours),
    percentile_cont(0.9) within group (order by t.reply_hours),
    count(*) filter (where t.reply_hours is not null and t.reply_hours <= 24),
    count(*) filter (where t.customer_id is not null and coalesce(c.number_of_orders, 0) > 0),
    count(*) filter (where t.customer_id is not null and coalesce(c.number_of_orders, 0) = 0),
    count(*) filter (where t.customer_id is null),
    count(distinct c.id) filter (where coalesce(c.number_of_orders, 0) = 0),
    count(distinct c.id) filter (
      where coalesce(c.number_of_orders, 0) = 0 and c.valid_email_address is true
    ),
    count(distinct c.id) filter (
      where coalesce(c.number_of_orders, 0) = 0 and c.on_email_marketing_list is true
    )
  from public.case_facts t
  left join public.customers c on c.id = t.customer_id
  where t.shop_id = p_shop
    and t.first_message_at >= (p_from at time zone p_tz)
    and t.first_message_at < (p_to at time zone p_tz);
$function$;

CREATE OR REPLACE FUNCTION public.insights_tiktok_post_series(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_grain text)
 RETURNS TABLE(kind text, account_id uuid, bucket timestamp without time zone, views bigint, engagement bigint, posts bigint, growth bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  with videos as (
    select
      a.kind,
      a.id as account_id,
      pg_catalog.date_trunc(case when p_grain in ('day', 'week', 'month', 'hour') then p_grain else 'day' end, p.published_at at time zone p_tz) as bucket,
      sum(p.views)::bigint as views,
      sum(p.engagement)::bigint as engagement,
      count(*)::bigint as posts
    from public.social_posts p
    join public.social_accounts a on a.id = p.account_id and a.shop_id = p.shop_id and a.enabled
    where p.shop_id = p_shop
      and a.kind = 'tiktok'
      and p.published_at >= (p_from at time zone p_tz)
      and p.published_at < (p_to at time zone p_tz)
    group by a.kind, a.id, 3
  ),
  -- Snapshots before the range are read so the first bucket's change has a
  -- predecessor. A first-ever snapshot establishes no growth (lag is null).
  snapshots as (
    select
      a.id as account_id,
      d.day,
      d.followers - lag(d.followers) over (partition by a.id order by d.day) as growth
    from public.social_account_days d
    join public.social_accounts a on a.id = d.account_id and a.shop_id = d.shop_id and a.enabled
    where d.shop_id = p_shop
      and a.kind = 'tiktok'
      and d.followers is not null
      and d.day < p_to::date
  ),
  follower_changes as (
    select
      s.account_id,
      pg_catalog.date_trunc(case when p_grain in ('day', 'week', 'month', 'hour') then p_grain else 'day' end, s.day::timestamp) as bucket,
      sum(s.growth)::bigint as growth
    from snapshots s
    where s.day >= p_from::date
    group by s.account_id, 2
  )
  select 'tiktok'::text, coalesce(v.account_id, f.account_id), coalesce(v.bucket, f.bucket), v.views, v.engagement, v.posts, f.growth
  from videos v
  full join follower_changes f on f.account_id = v.account_id and f.bucket = v.bucket;
$function$;

CREATE OR REPLACE FUNCTION public.is_valid_product_faqs(value jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case
    when jsonb_typeof(value) <> 'array' then false
    else not exists (
      select 1
      from jsonb_array_elements(value) as faq(item)
      where jsonb_typeof(faq.item) <> 'object'
        or not (faq.item ? 'faq_id')
        or not (faq.item ? 'question')
        or not (faq.item ? 'answer')
        or not (faq.item ? 'source')
        or not (faq.item ? 'content_hash')
        or not (faq.item ? 'updated_at')
        or not (faq.item ? 'published')
        or jsonb_typeof(faq.item -> 'source') <> 'object'
        or jsonb_typeof(faq.item -> 'published') <> 'boolean'
    )
  end;
$function$;

CREATE OR REPLACE FUNCTION public.klaviyo_clear_key(p_shop uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_secret uuid;
begin
  delete from public.klaviyo_connections c where c.shop_id = p_shop returning c.secret_id into v_secret;
  if v_secret is not null then
    delete from vault.secrets s where s.id = v_secret;
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.klaviyo_read_key(p_shop uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select d.decrypted_secret
  from public.klaviyo_connections c
  join vault.decrypted_secrets d on d.id = c.secret_id
  where c.shop_id = p_shop;
$function$;

CREATE OR REPLACE FUNCTION public.klaviyo_save_key(p_shop uuid, p_key text, p_hint text, p_metric_id text, p_saved_by uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_secret uuid;
begin
  select c.secret_id into v_secret from public.klaviyo_connections c where c.shop_id = p_shop;
  if v_secret is not null and exists (select 1 from vault.secrets s where s.id = v_secret) then
    perform vault.update_secret(v_secret, p_key);
  else
    v_secret := vault.create_secret(p_key, 'klaviyo_private_key:' || p_shop::text || ':' || gen_random_uuid()::text, 'Klaviyo private API key');
  end if;

  insert into public.klaviyo_connections as c (shop_id, secret_id, key_hint, conversion_metric_id, saved_at, saved_by)
  values (p_shop, v_secret, p_hint, p_metric_id, now(), p_saved_by)
  on conflict (shop_id) do update
    set secret_id = excluded.secret_id,
        key_hint = excluded.key_hint,
        conversion_metric_id = excluded.conversion_metric_id,
        saved_at = excluded.saved_at,
        saved_by = excluded.saved_by,
        last_sync_error = null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.match_knowledge_chunks(query_embedding public.vector, match_shop_id uuid, match_categories text[] DEFAULT NULL::text[], match_count integer DEFAULT 5, min_similarity double precision DEFAULT 0)
 RETURNS TABLE(chunk_id uuid, document_id uuid, document_title text, section_heading text, category text, product_ids uuid[], chunk_text text, similarity double precision)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select
    kc.id,
    kd.id,
    kd.title,
    kc.section_heading,
    kc.category,
    kc.product_ids,
    kc.chunk_text,
    1 - (kc.embedding <=> query_embedding) as similarity
  from public.knowledge_chunks kc
  join public.knowledge_documents kd on kd.id = kc.knowledge_document_id
  where kc.embedding is not null
    and kd.shop_id = match_shop_id
    and (match_categories is null or kc.category = any (match_categories))
    and 1 - (kc.embedding <=> query_embedding) >= min_similarity
  order by kc.embedding <=> query_embedding
  limit greatest(match_count, 1);
$function$;

CREATE OR REPLACE FUNCTION public.match_support_exemplars(query_embedding public.vector, match_shop_id uuid, match_categories text[] DEFAULT NULL::text[], match_count integer DEFAULT 3, min_similarity double precision DEFAULT 0)
 RETURNS TABLE(exemplar_id uuid, exemplar_key text, canonical_question text, category text, request_kind text, requirement_needs text[], matched_phrasing text, matched_phrasing_kind text, matched_phrasing_language text, similarity double precision)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with ranked as (
    -- The index lookup. Over-fetched because the limit applies to PHRASINGS
    -- while the caller counts EXEMPLARS: without headroom, one situation whose
    -- five variants all rank highly would return a single result for a request
    -- of three.
    --
    -- THE INVARIANT: the multiplier must stay above the largest number of
    -- phrasings any one exemplar has.
    --
    -- IT IS 64 BECAUSE THE LIBRARY IS TRANSLATED. It was 8 against a largest
    -- authored count of 5, and translation is what the old comment here warned
    -- would break it: D-33 has 8 authored phrasings and 32 translations, so at
    -- 8 it alone would fill all 24 slots of a three-exemplar request and the
    -- function would return one result. Silently — it reads as a retrieval
    -- quality problem rather than as arithmetic, which is why the number is
    -- derived rather than observed.
    --
    -- 64 IS THE INDEX SCHEME'S CEILING, NOT TODAY'S LARGEST ROW. Translations
    -- are addressed `100 + source * 10 + language slot`, which
    -- `exemplar-translation.mjs` caps at 10 authored phrasings and 5 languages
    -- — at most 60 rows for one exemplar, whatever anybody adds to the
    -- document. Setting it from the measured 40 instead would mean one new
    -- variant on D-33 could quietly reintroduce the same failure.
    select
      p.support_exemplar_id,
      p.phrasing_text,
      p.phrasing_kind,
      p.language,
      1 - (p.embedding <=> query_embedding) as similarity
    from public.support_exemplar_phrasings p
    join public.support_exemplars e on e.id = p.support_exemplar_id
    where p.embedding is not null
      and e.shop_id = match_shop_id
      and e.deleted_at is null
      and (match_categories is null or e.category = any (match_categories))
    order by p.embedding <=> query_embedding
    limit greatest(match_count, 1) * 64
  ),
  best as (
    select distinct on (support_exemplar_id) *
    from ranked
    order by support_exemplar_id, similarity desc
  )
  select
    e.id,
    e.exemplar_key,
    e.canonical_question,
    e.category,
    e.request_kind,
    e.requirement_needs,
    b.phrasing_text,
    b.phrasing_kind,
    b.language,
    b.similarity
  from best b
  join public.support_exemplars e on e.id = b.support_exemplar_id
  where b.similarity >= min_similarity
  order by b.similarity desc
  limit greatest(match_count, 1);
$function$;

CREATE OR REPLACE FUNCTION public.normalise_carrier(value text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select case
    when value is null or btrim(value) = '' then null
    else coalesce(
      (
        select a.canonical
        from public.carrier_aliases a
        where strpos(upper(value), upper(a.pattern)) > 0
        order by a.position, a.pattern
        limit 1
      ),
      upper(btrim(value))
    )
  end;
$function$;

CREATE OR REPLACE FUNCTION public.open_orders(p_shop uuid, p_min_spend numeric, p_min_orders integer, p_window_months integer, p_vip_not_channels text[] DEFAULT NULL::text[], p_channels text[] DEFAULT NULL::text[], p_not_channels text[] DEFAULT NULL::text[])
 RETURNS TABLE(order_id uuid, order_name text, legacy_resource_id text, processed_at timestamp with time zone, channel text, channel_label text, fulfillment_status text, total_price numeric, units bigint, customer_id uuid, customer_name text, customer_email text, is_vip boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select
    o.id,
    o.name,
    o.legacy_resource_id,
    o.processed_at,
    o.sales_channel_handle,
    o.sales_channel,
    o.fulfillment_status,
    o.total_price,
    (
      select coalesce(sum(coalesce((li.current_quantity)::int, (li.quantity)::int, 0)), 0)
      from public.order_lines li where li.order_id = o.id
    )::bigint,
    c.id,
    coalesce(c.display_name, nullif(concat_ws(' ', c.first_name, c.last_name), '')),
    c.email,
    v.customer_id is not null
  from public.orders o
  left join public.customers c
    on c.shop_id = o.shop_id
   and c.shopify_customer_id = o.shopify_customer_id
   and c.deleted_at is null
  left join public.vip_customers(p_shop, p_min_spend, p_min_orders, p_window_months, p_vip_not_channels) v
    on v.customer_id = c.id
  where o.shop_id = p_shop
    and o.deleted_at is null
    and o.cancelled_at is null
    and o.closed_at is null
    and o.fulfillment_status is not null
    and o.fulfillment_status not in ('FULFILLED', 'RESTOCKED')
    and (p_channels is null or o.sales_channel_handle = any(p_channels))
    and (
      p_not_channels is null
      or o.sales_channel_handle is null
      or not (o.sales_channel_handle = any(p_not_channels))
    )
  order by o.processed_at asc;
$function$;

CREATE OR REPLACE FUNCTION public.order_fulfilment_display(p_fulfillment_status text, p_line_items jsonb, p_cancelled_at timestamp with time zone, p_financial_status text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    when coalesce(p_fulfillment_status, 'UNKNOWN') in ('FULFILLED', 'RESTOCKED')
      then p_fulfillment_status
    when (
      select coalesce(sum(coalesce((li.value ->> 'current_quantity')::int, (li.value ->> 'quantity')::int, 0)), 0)
      from jsonb_array_elements(
        case when jsonb_typeof(p_line_items) = 'array' then p_line_items else '[]'::jsonb end
      ) as li
    ) <> 0
      then coalesce(p_fulfillment_status, 'UNKNOWN')
    when p_cancelled_at is not null then 'CANCELLED'
    when p_financial_status = 'REFUNDED' then 'REFUNDED'
    else coalesce(p_fulfillment_status, 'UNKNOWN')
  end;
$function$;

CREATE OR REPLACE FUNCTION public.order_lines_refresh()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'UPDATE' then
    delete from public.order_lines where order_id = new.id;
  end if;
  insert into public.order_lines (
    order_id, shop_id, line_index, product_id, variant_id, title, variant_title, sku,
    quantity, current_quantity, original_total, discounted_total, discounts
  )
  select
    new.id, new.shop_id, e.ordinality::integer,
    e.value ->> 'product_id', e.value ->> 'variant_id', e.value ->> 'title', e.value ->> 'variant_title', e.value ->> 'sku',
    e.value ->> 'quantity', e.value ->> 'current_quantity', e.value ->> 'original_total', e.value ->> 'discounted_total',
    e.value -> 'discounts'
  from jsonb_array_elements(
    case when jsonb_typeof(new.line_items) = 'array' then new.line_items else '[]'::jsonb end
  ) with ordinality as e(value, ordinality);
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.order_number_range(match_shop_id uuid)
 RETURNS TABLE(min_order_number integer, max_order_number integer)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select min(o.order_number), max(o.order_number)
  from public.orders o
  where o.shop_id = match_shop_id
    and o.order_number is not null
    and o.deleted_at is null;
$function$;

CREATE OR REPLACE FUNCTION public.orders_list(p_shop uuid, p_min_spend numeric, p_min_orders integer, p_window_months integer, p_vip_not_channels text[] DEFAULT NULL::text[], p_fulfillment_status text DEFAULT NULL::text, p_country text DEFAULT NULL::text, p_vip_only boolean DEFAULT false, p_search text DEFAULT NULL::text, p_order_ids uuid[] DEFAULT NULL::uuid[], p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS TABLE(order_id uuid, order_name text, order_number integer, processed_at timestamp with time zone, cancelled_at timestamp with time zone, channel text, channel_label text, financial_status text, fulfillment_status text, awaiting_fulfilment boolean, total_price numeric, currency_code text, units bigint, carrier text, country_code text, country text, city text, customer_id uuid, customer_name text, is_vip boolean, total_count bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with vip as (
    select v.customer_id
    from public.vip_customers(p_shop, p_min_spend, p_min_orders, p_window_months, p_vip_not_channels) v
  ),
  page as (
    select
      o.id,
      o.name,
      o.order_number,
      o.processed_at,
      o.cancelled_at,
      o.sales_channel_handle,
      o.sales_channel,
      o.financial_status,
      o.fulfillment_status,
      (
        o.cancelled_at is null
        and o.closed_at is null
        and o.fulfillment_status is not null
        and o.fulfillment_status not in ('FULFILLED', 'RESTOCKED')
      ) as awaiting,
      o.total_price,
      o.currency_code,
      o.line_items,
      o.fulfillments,
      o.shipping_destination,
      c.id as buyer_id,
      coalesce(c.display_name, nullif(concat_ws(' ', c.first_name, c.last_name), '')) as buyer_name,
      vip.customer_id is not null as buyer_is_vip,
      count(*) over () as matched
    from public.orders o
    left join public.customers c
      on c.shop_id = o.shop_id
     and c.shopify_customer_id = o.shopify_customer_id
     and c.deleted_at is null
    left join vip on vip.customer_id = c.id
    where o.shop_id = p_shop
      and o.deleted_at is null
      and (
        p_fulfillment_status is null
        or public.order_fulfilment_display(o.fulfillment_status, o.line_items, o.cancelled_at, o.financial_status) = p_fulfillment_status
      )
      and (p_country is null or coalesce(o.shipping_destination ->> 'country_code', '??') = p_country)
      and (not coalesce(p_vip_only, false) or vip.customer_id is not null)
      and (
        p_search is null
        or o.name ilike ('%' || p_search || '%')
        or coalesce(c.display_name, concat_ws(' ', c.first_name, c.last_name)) ilike ('%' || p_search || '%')
        or c.email ilike ('%' || p_search || '%')
        or upper(regexp_replace(p_search, '[[:space:].-]', '', 'g')) = any(o.tracking_numbers)
      )
      and (p_order_ids is null or o.id = any(p_order_ids))
    order by o.processed_at desc nulls last, o.id desc
    limit greatest(coalesce(p_limit, 50), 0)
    offset greatest(coalesce(p_offset, 0), 0)
  )
  select
    p.id,
    p.name,
    p.order_number,
    p.processed_at,
    p.cancelled_at,
    p.sales_channel_handle,
    p.sales_channel,
    p.financial_status,
    p.fulfillment_status,
    p.awaiting,
    p.total_price,
    p.currency_code,
    (
      select coalesce(sum(coalesce((li.current_quantity)::int, (li.quantity)::int, 0)), 0)
      from public.order_lines li where li.order_id = p.id
    )::bigint,
    (
      select public.normalise_carrier(min(t.value ->> 'company'))
      from jsonb_array_elements(
        case when jsonb_typeof(p.fulfillments) = 'array' then p.fulfillments else '[]'::jsonb end
      ) as e
      cross join lateral jsonb_array_elements(
        case when jsonb_typeof(e.value -> 'tracking_info') = 'array'
          then e.value -> 'tracking_info'
          else '[]'::jsonb
        end
      ) as t
    ),
    nullif(p.shipping_destination ->> 'country_code', ''),
    nullif(p.shipping_destination ->> 'country', ''),
    nullif(p.shipping_destination ->> 'city', ''),
    p.buyer_id,
    p.buyer_name,
    p.buyer_is_vip,
    p.matched
  from page p
  order by p.processed_at desc nulls last, p.id desc;
$function$;

CREATE OR REPLACE FUNCTION public.orders_list_facets(p_shop uuid)
 RETURNS TABLE(facet text, value text, label text, orders bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select 'fulfillment_status', public.order_fulfilment_display(o.fulfillment_status, o.line_items, o.cancelled_at, o.financial_status), null::text, count(*)
  from public.orders o
  where o.shop_id = p_shop
    and o.deleted_at is null
  group by 2
  union all
  select 'country', coalesce(o.shipping_destination ->> 'country_code', '??'), max(o.shipping_destination ->> 'country'), count(*)
  from public.orders o
  where o.shop_id = p_shop
    and o.deleted_at is null
  group by 2
  order by 1, 4 desc, 2;
$function$;

CREATE OR REPLACE FUNCTION public.search_knowledge_chunks_text(query_text text, match_shop_id uuid, match_categories text[] DEFAULT NULL::text[], match_count integer DEFAULT 5)
 RETURNS TABLE(chunk_id uuid, document_id uuid, document_title text, section_heading text, category text, product_ids uuid[], chunk_text text, rank double precision)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  -- THE QUERY IS OR-ED, NOT AND-ED, and that is the whole difficulty here.
  --
  -- The natural choice, websearch_to_tsquery, joins every term with AND. That
  -- is right for a search box where someone types three words, and completely
  -- wrong for a retrieval query built from a whole customer email: a 14-word
  -- question becomes `del & retourn & articl & bonjour & recu & ...`, which no
  -- chunk on earth satisfies. Measured before this fix: 4 results for the single
  -- word "rétractation", 0 for any real ticket.
  --
  -- So the query text is passed through the SAME configuration that built the
  -- index, and its lexemes are OR-ed. Recall comes from the OR; precision comes
  -- from ts_rank_cd, which rewards chunks covering more of the query with the
  -- terms closer together — and from the A/B weighting, which puts a section
  -- heading above body text.
  with q as (
    select nullif(
      (select string_agg(lexeme, ' | ') from unnest(to_tsvector('public.french_unaccent', coalesce(query_text, '')))),
      ''
    )::tsquery as tsq
  )
  select
    c.id,
    d.id,
    d.title,
    c.section_heading,
    c.category,
    c.product_ids,
    c.chunk_text,
    ts_rank_cd(c.search_vector, q.tsq)::double precision
  from public.knowledge_chunks c
  join public.knowledge_documents d on d.id = c.knowledge_document_id
  cross join q
  where q.tsq is not null
    and d.shop_id = match_shop_id
    and d.deleted_at is null
    -- Same approval gate as the dense side. A draft article must not become
    -- reachable just because it is lexically searchable.
    and d.approval_status = 'approved'
    and (match_categories is null or c.category = any (match_categories))
    and c.search_vector @@ q.tsq
  order by ts_rank_cd(c.search_vector, q.tsq) desc
  limit greatest(coalesce(match_count, 5), 1);
$function$;

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.skip_unchanged_sync_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  ignored text[] := array['synced_at', 'updated_at'] || coalesce(tg_argv::text[], '{}');
begin
  if (to_jsonb(new) - ignored) = (to_jsonb(old) - ignored) then
    return null;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.social_clear_token(p_shop uuid, p_provider text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_secret uuid;
begin
  delete from public.social_connections c where c.shop_id = p_shop and c.provider = p_provider returning c.secret_id into v_secret;
  if v_secret is not null then
    delete from vault.secrets s where s.id = v_secret;
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.social_read_token(p_shop uuid, p_provider text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select d.decrypted_secret
  from public.social_connections c
  join vault.decrypted_secrets d on d.id = c.secret_id
  where c.shop_id = p_shop and c.provider = p_provider;
$function$;

CREATE OR REPLACE FUNCTION public.social_refresh_token(p_shop uuid, p_provider text, p_token text, p_expires_at timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_secret uuid;
begin
  select c.secret_id into v_secret from public.social_connections c
    where c.shop_id = p_shop and c.provider = p_provider for update;
  if v_secret is null then raise exception 'Connection unavailable'; end if;
  perform vault.update_secret(v_secret, p_token);
  update public.social_connections set token_expires_at = p_expires_at
    where shop_id = p_shop and provider = p_provider;
end;
$function$;

CREATE OR REPLACE FUNCTION public.social_save_token(p_shop uuid, p_provider text, p_token text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_scopes text[] DEFAULT '{}'::text[], p_connected_by uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_secret uuid;
begin
  select c.secret_id into v_secret from public.social_connections c where c.shop_id = p_shop and c.provider = p_provider;
  if v_secret is not null and exists (select 1 from vault.secrets s where s.id = v_secret) then
    perform vault.update_secret(v_secret, p_token);
  else
    v_secret := vault.create_secret(p_token, 'social_token:' || p_provider || ':' || p_shop::text || ':' || gen_random_uuid()::text, p_provider || ' OAuth token');
  end if;

  insert into public.social_connections as c (shop_id, provider, secret_id, token_expires_at, scopes, connected_at, connected_by)
  values (p_shop, p_provider, v_secret, p_expires_at, coalesce(p_scopes, '{}'), now(), p_connected_by)
  on conflict (shop_id, provider) do update
    set secret_id = excluded.secret_id,
        token_expires_at = excluded.token_expires_at,
        scopes = excluded.scopes,
        connected_at = excluded.connected_at,
        connected_by = excluded.connected_by,
        last_sync_status = case when c.last_sync_status = 'needs_reconnect' then null else c.last_sync_status end,
        last_sync_error = null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.storefront_chat_purge(p_before timestamp with time zone)
 RETURNS integer
 LANGUAGE sql
 SET search_path TO ''
AS $function$
  with gone as (
    delete from public.storefront_chat_sessions s
    where s.last_activity_at < p_before
    returning 1
  )
  select count(*)::integer from gone;
$function$;

CREATE OR REPLACE FUNCTION public.storefront_chat_record_turn(p_session uuid)
 RETURNS integer
 LANGUAGE sql
 SET search_path TO ''
AS $function$
  update public.storefront_chat_sessions s
  set turn_count = s.turn_count + 1,
      last_activity_at = now()
  where s.id = p_session
  returning s.turn_count;
$function$;

CREATE OR REPLACE FUNCTION public.storefront_chat_user_messages_since(p_shop_domain text, p_since timestamp with time zone)
 RETURNS integer
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select count(*)::integer
  from public.storefront_chat_messages m
  join public.storefront_chat_sessions s on s.id = m.session_id
  where s.shop_domain = p_shop_domain
    and m.role = 'user'
    and m.created_at >= p_since;
$function$;

CREATE OR REPLACE FUNCTION public.tickets_open_case()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.case_id is null then insert into public.cases (shop_id) values (new.shop_id) returning id into new.case_id; end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.valid_manual_audience(p_dimension text, p_entries jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  item jsonb;
  label text;
  amount numeric;
  total numeric := 0;
  labels text[] := '{}';
begin
  if p_dimension not in ('gender', 'age', 'country', 'city') or jsonb_typeof(p_entries) <> 'array' then return false; end if;
  if jsonb_array_length(p_entries) not between 1 and 50 then return false; end if;
  for item in select value from jsonb_array_elements(p_entries) loop
    label := item->>'key';
    if jsonb_typeof(item->'key') <> 'string' or label is null or length(trim(label)) not between 1 and 80 or label ~ '[[:cntrl:]]' or lower(trim(label)) = any(labels)
       or (p_dimension = 'gender' and label not in ('female', 'male', 'unknown')) or jsonb_typeof(item->'value') <> 'number' then return false; end if;
    amount := (item->>'value')::numeric;
    if amount is null or amount < 0 or amount > 100 then return false; end if;
    total := total + amount;
    labels := array_append(labels, lower(trim(label)));
  end loop;
  return total <= 100;
exception when others then
  return false;
end;
$function$;

CREATE OR REPLACE FUNCTION public.vip_customers(p_shop uuid, p_min_spend numeric, p_min_orders integer, p_window_months integer, p_not_channels text[] DEFAULT NULL::text[], p_customer_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS TABLE(customer_id uuid, orders bigint, spend numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with windowed as (
    select
      o.shopify_customer_id,
      count(*) as orders,
      coalesce(sum(o.total_price - coalesce(o.total_refunded, 0)), 0) as spend
    from public.orders o
    where o.shop_id = p_shop
      and o.deleted_at is null
      and o.cancelled_at is null
      and o.shopify_customer_id is not null
      and o.processed_at >= now() - make_interval(months => p_window_months)
      and (
        p_not_channels is null
        or o.sales_channel_handle is null
        or not (o.sales_channel_handle = any(p_not_channels))
      )
    group by 1
  )
  select c.id, w.orders, w.spend
  from windowed w
  join public.customers c
    on c.shop_id = p_shop
   and c.shopify_customer_id = w.shopify_customer_id
   and c.deleted_at is null
  where w.spend > p_min_spend
    and w.orders > p_min_orders
    and (p_customer_ids is null or c.id = any(p_customer_ids));
$function$;

CREATE OR REPLACE FUNCTION public.vip_summary(p_shop uuid, p_min_spend numeric, p_min_orders integer, p_window_months integer, p_not_channels text[] DEFAULT NULL::text[])
 RETURNS TABLE(vip_customers bigint, buyers_in_window bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select
    (select count(*) from public.vip_customers(p_shop, p_min_spend, p_min_orders, p_window_months, p_not_channels)),
    (
      select count(distinct o.shopify_customer_id)
      from public.orders o
      where o.shop_id = p_shop
        and o.deleted_at is null
        and o.cancelled_at is null
        and o.shopify_customer_id is not null
        and o.processed_at >= now() - make_interval(months => p_window_months)
        and (
          p_not_channels is null
          or o.sales_channel_handle is null
          or not (o.sales_channel_handle = any(p_not_channels))
        )
    );
$function$;

CREATE OR REPLACE FUNCTION public.vip_tickets(p_shop uuid, p_min_spend numeric, p_min_orders integer, p_window_months integer, p_not_channels text[] DEFAULT NULL::text[], p_ticket_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS TABLE(ticket_id uuid, customer_id uuid)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select t.id, t.customer_id
  from public.tickets t
  join public.vip_customers(p_shop, p_min_spend, p_min_orders, p_window_months, p_not_channels) v
    on v.customer_id = t.customer_id
  where t.shop_id = p_shop
    and t.deleted_at is null
    and (p_ticket_ids is null or t.id = any(p_ticket_ids));
$function$;


