  gate_outcome text,
  category text,
  request_kind text,
  level smallint,
  language text,
  verdict text,
  draft_body_text text,
  draft_skipped_reason text,
  draft_checks_passed boolean,
  draft_disposition text,
  ideal_body_text text,
