  constraint orders_total_discounts_check CHECK (((total_discounts IS NULL) OR (total_discounts >= (0)::numeric))),
  constraint orders_total_price_check CHECK (((total_price IS NULL) OR (total_price >= (0)::numeric))),
  constraint orders_total_refunded_check CHECK (((total_refunded IS NULL) OR (total_refunded >= (0)::numeric))),
  constraint orders_total_shipping_price_check CHECK (((total_shipping_price IS NULL) OR (total_shipping_price >= (0)::numeric))),
