  constraint social_metric_bands_kind_check CHECK ((kind = ANY (ARRAY['instagram'::text, 'facebook'::text, 'tiktok'::text]))),
  constraint social_metric_bands_limits_check CHECK (((mode = 'off'::text) OR ((low IS NOT NULL) AND (high IS NOT NULL) AND (low >= (0)::numeric) AND (low <= high)))),
  constraint social_metric_bands_metric_check CHECK ((metric = ANY (ARRAY['views'::text, 'reach'::text, 'engagement'::text, 'engagementRate'::text, 'likes'::text, 'comments'::text, 'shares'::text, 'follows'::text, 'nonFollowersPct'::text]))),
  constraint social_metric_bands_mode_check CHECK ((mode = ANY (ARRAY['off'::text, 'absolute'::text, 'followers'::text, 'median'::text]))),
  constraint social_metric_bands_non_followers_check CHECK (((metric <> 'nonFollowersPct'::text) OR ((mode <> 'followers'::text) AND ((mode <> 'absolute'::text) OR (high <= (100)::numeric))))),
  constraint social_metric_bands_pkey PRIMARY KEY (shop_id, kind, metric)
);

create table public.social_post_manual_metrics (
  shop_id uuid not null,
