  constraint social_post_manual_metrics_check CHECK ((((metric = 'engagementRate'::text) AND (basis IS NOT NULL)) OR ((metric <> 'engagementRate'::text) AND (basis IS NULL)))),
  constraint social_post_manual_metrics_check1 CHECK (((metric <> 'nonFollowersPct'::text) OR (value <= (100)::numeric))),
  constraint social_post_manual_metrics_check2 CHECK (((metric = ANY (ARRAY['engagementRate'::text, 'nonFollowersPct'::text])) OR (value = trunc(value)))),
  constraint social_post_manual_metrics_metric_check CHECK ((metric = ANY (ARRAY['views'::text, 'reach'::text, 'engagementRate'::text, 'likes'::text, 'comments'::text, 'shares'::text, 'follows'::text, 'engagement'::text, 'nonFollowersPct'::text]))),
  constraint social_post_manual_metrics_value_check CHECK (((value >= (0)::numeric) AND (value <= ('9007199254740991'::bigint)::numeric))),
  constraint social_post_manual_metrics_pkey PRIMARY KEY (shop_id, account_id, post_id, metric)
);

