  when_conditions jsonb default '{}'::jsonb not null,
  answer_skeleton text,
  route text,
  ask text[] default '{}'::text[] not null,
  priority integer default 0 not null,
  is_fallback boolean default false not null,
  approval_status text default 'draft'::text not null,
  deleted_at timestamp with time zone,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  offer_code text,
  knowledge_document_id uuid,
  tones text[] default '{}'::text[] not null,
  link_url text,
  link_label text,
  checks jsonb default '[]'::jsonb not null,
  notify_on text,
  constraint support_answers_approval_status_check CHECK ((approval_status = ANY (ARRAY['draft'::text, 'in_review'::text, 'approved'::text, 'needs_optimization'::text]))),
  constraint support_answers_ask_check CHECK ((ask <@ ARRAY['shopify_order_number'::text, 'purchase_email'::text, 'product_name'::text, 'purchase_channel'::text, 'photo'::text, 'promotion_code'::text, 'order_date_or_amount'::text, 'reaction_product_name'::text, 'lot_number'::text, 'account_email'::text, 'postal_address'::text, 'preferred_remedy'::text, 'receipt_confirmation'::text, 'skin_type'::text, 'skin_concern'::text])),
  constraint support_answers_ask_needs_route_check CHECK (((cardinality(ask) = 0) OR (NOT (route IS DISTINCT FROM 'needs_customer_input'::text)))),
  constraint support_answers_checks_array_check CHECK ((jsonb_typeof(checks) = 'array'::text)),
  constraint support_answers_fallback_has_no_conditions_check CHECK (((NOT is_fallback) OR (when_conditions = '{}'::jsonb))),
  constraint support_answers_link_pair_check CHECK ((((link_url IS NULL) = (link_label IS NULL)) AND ((link_label IS NULL) OR ((length(btrim(link_label)) >= 1) AND (length(btrim(link_label)) <= 120))))),
  constraint support_answers_link_url_check CHECK (((link_url IS NULL) OR (link_url ~ '^https://[^[:space:]]+$'::text))),
  constraint support_answers_notify_on_check CHECK (((notify_on IS NULL) OR (notify_on = 'refund_recorded'::text))),
  constraint support_answers_offer_code_not_blank_check CHECK (((offer_code IS NULL) OR (length(btrim(offer_code)) > 0))),
  constraint support_answers_route_check CHECK (((route IS NULL) OR (route = ANY (ARRAY['needs_human'::text, 'needs_customer_input'::text])))),
  constraint support_answers_tones_check CHECK ((tones <@ ARRAY['reassuring'::text, 'empathetic'::text, 'factual'::text, 'firm'::text, 'apologetic'::text, 'understanding'::text])),
  constraint support_answers_when_conditions_object_check CHECK ((jsonb_typeof(when_conditions) = 'object'::text)),
  constraint support_answers_pkey PRIMARY KEY (id)
);

