  constraint ticket_drafts_checks_array_check CHECK ((jsonb_typeof(checks) = 'array'::text)),
  constraint ticket_drafts_disposition_check CHECK ((disposition = ANY (ARRAY['terminal'::text, 'intermediary'::text]))),
  constraint ticket_drafts_edited_has_body_check CHECK (((status <> 'edited'::text) OR (btrim(COALESCE(approved_body_text, ''::text)) <> ''::text))),
  constraint ticket_drafts_human_is_intermediary_check CHECK (((source_verdict <> 'needs_human'::text) OR (disposition = 'intermediary'::text))),
  constraint ticket_drafts_language_check CHECK (((language IS NULL) OR (language = ANY (ARRAY['fr'::text, 'en'::text, 'es'::text, 'de'::text, 'it'::text, 'nl'::text, 'pt'::text, 'other'::text])))),
  constraint ticket_drafts_level_check CHECK (((level IS NULL) OR ((level >= 1) AND (level <= 3)))),
  constraint ticket_drafts_prompt_inputs_object_check CHECK ((jsonb_typeof(prompt_inputs) = 'object'::text)),
  constraint ticket_drafts_purpose_check CHECK ((purpose = ANY (ARRAY['reply'::text, 'refund_notice'::text]))),
  constraint ticket_drafts_question_is_intermediary_check CHECK (((source_verdict <> 'needs_customer_input'::text) OR (disposition = 'intermediary'::text))),
  constraint ticket_drafts_reply_link_object_check CHECK (((reply_link IS NULL) OR (jsonb_typeof(reply_link) = 'object'::text))),
  constraint ticket_drafts_source_verdict_check CHECK ((source_verdict = ANY (ARRAY['answerable'::text, 'needs_customer_input'::text, 'needs_human'::text]))),
  constraint ticket_drafts_stale_has_reason_check CHECK (((status = 'stale'::text) = (stale_reason IS NOT NULL))),
  constraint ticket_drafts_stale_reason_check CHECK (((stale_reason IS NULL) OR (stale_reason = ANY (ARRAY['case_changed'::text, 'superseded_by_outbound'::text])))),
  constraint ticket_drafts_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'edited'::text, 'rejected'::text, 'sent'::text, 'stale'::text]))),
  constraint ticket_drafts_pkey PRIMARY KEY (id),
