  field text not null,
  action text not null,
  value text,
  ai_value text,
  source text,
  set_by text,
  set_at timestamp with time zone default now() not null,
  constraint ticket_overrides_action_check CHECK ((action = ANY (ARRAY['set'::text, 'cleared'::text]))),
  constraint ticket_overrides_field_check CHECK ((field = ANY (ARRAY['situation'::text, 'category'::text, 'level'::text, 'status'::text, 'responsible_team'::text, 'priority'::text]))),
  constraint ticket_overrides_value_check CHECK (((action = 'set'::text) = (value IS NOT NULL))),
  constraint ticket_overrides_pkey PRIMARY KEY (id)
);

create table public.ticket_routing (
  id uuid default gen_random_uuid() not null,
  shop_id uuid not null,
  ticket_id uuid not null,
  category text not null,
  request_kind text,
  outcome text not null,
  method text not null,
  destination_id uuid,
  destination_label text,
  reason text,
  model text,
  decided_at timestamp with time zone default now() not null,
  ack_state text,
  ack_at timestamp with time zone,
  ack_error text,
  ack_attempts integer default 0 not null,
  constraint ticket_routing_ack_state_check CHECK (((ack_state IS NULL) OR (ack_state = ANY (ARRAY['requested'::text, 'sent'::text, 'failed'::text, 'skipped'::text])))),
  constraint ticket_routing_destination_check CHECK (((outcome = 'keep'::text) OR (destination_label IS NOT NULL))),
  constraint ticket_routing_method_check CHECK ((method = ANY (ARRAY['fixed'::text, 'model'::text]))),
  constraint ticket_routing_outcome_check CHECK ((outcome = ANY (ARRAY['forward'::text, 'keep'::text]))),
  constraint ticket_routing_pkey PRIMARY KEY (id),
  constraint ticket_routing_ticket_id_key UNIQUE (ticket_id)
);

create table public.ticket_snoozes (
  id uuid default gen_random_uuid() not null,
  shop_id uuid not null,
  ticket_id uuid not null,
  source text not null,
  waiting_for text not null,
  reason text,
  wake_at timestamp with time zone not null,
  trigger_message_id uuid,
  case_version integer,
  snoozed_by text,
  snoozed_at timestamp with time zone default now() not null,
  woke_at timestamp with time zone,
  wake_reason text,
  woken_by text,
  constraint ticket_snoozes_source_check CHECK ((source = ANY (ARRAY['auto'::text, 'manual'::text]))),
  constraint ticket_snoozes_waiting_for_check CHECK ((waiting_for = ANY (ARRAY['customer'::text, 'colleague'::text, 'partner'::text, 'date'::text]))),
  constraint ticket_snoozes_wake_reason_check CHECK (((wake_reason IS NULL) OR (wake_reason = ANY (ARRAY['customer_message'::text, 'colleague_message'::text, 'partner_message'::text, 'deadline'::text, 'manual'::text, 'case_changed'::text, 'resolved'::text, 'order_update'::text])))),
  constraint ticket_snoozes_woke_check CHECK (((woke_at IS NULL) = (wake_reason IS NULL))),
  constraint ticket_snoozes_pkey PRIMARY KEY (id)
);

create table public.tickets (
  id uuid default gen_random_uuid() not null,
  shop_id uuid not null,
  graph_conversation_id text not null,
  subject text,
  status text default 'open'::text not null,
  category text,
  secondary_category text,
  request_kind text,
  secondary_request_kind text,
  level smallint,
  responsible_team text,
  shopify_order_number text,
  customer_id uuid,
  requester_email_hash text,
  requester_name text,
  needs_categorisation boolean default true not null,
  categorised_at timestamp with time zone,
  categorisation_confidence text,
  language text,
  happiness smallint,
  needs_investigation boolean default false not null,
  investigated_at timestamp with time zone,
  priority smallint default 3 not null,
  resolved_context jsonb default '{}'::jsonb not null,
  context_resolved_at timestamp with time zone,
  first_message_at timestamp with time zone,
  last_message_at timestamp with time zone,
  metadata jsonb default '{}'::jsonb not null,
  resolved_at timestamp with time zone,
  closed_at timestamp with time zone,
  archived_at timestamp with time zone,
  retention_delete_after timestamp with time zone,
  deleted_at timestamp with time zone,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  duplicate_of_ticket_id uuid,
  duplicate_reason text,
  duplicate_detected_at timestamp with time zone,
  related_ticket_id uuid,
  related_score real,
  related_detected_at timestamp with time zone,
  sender_label text,
  overrides jsonb default '{}'::jsonb not null,
  case_id uuid not null,
  case_link_state text default 'pending'::text not null,
  fact_drift jsonb,
  constraint tickets_case_link_state_check CHECK ((case_link_state = ANY (ARRAY['pending'::text, 'decided'::text]))),
  constraint tickets_categorisation_confidence_check CHECK (((categorisation_confidence IS NULL) OR (categorisation_confidence = ANY (ARRAY['high'::text, 'medium'::text, 'low'::text])))),
  constraint tickets_category_check CHECK (((category IS NULL) OR (category = ANY (ARRAY['order'::text, 'delivery'::text, 'return_exchange'::text, 'product'::text, 'product_stock'::text, 'payment'::text, 'account'::text, 'promotions'::text, 'cosmetovigilance'::text, 'legal_privacy'::text, 'b2b'::text, 'partner_collaboration'::text, 'careers'::text, 'other'::text])))),
  constraint tickets_duplicate_complete_check CHECK ((((duplicate_of_ticket_id IS NULL) AND (duplicate_reason IS NULL) AND (duplicate_detected_at IS NULL)) OR ((duplicate_of_ticket_id IS NOT NULL) AND (duplicate_reason IS NOT NULL) AND (duplicate_detected_at IS NOT NULL)))),
  constraint tickets_duplicate_not_self_check CHECK (((duplicate_of_ticket_id IS NULL) OR (duplicate_of_ticket_id <> id))),
  constraint tickets_duplicate_reason_check CHECK (((duplicate_reason IS NULL) OR (duplicate_reason = ANY (ARRAY['identical_body'::text, 'reply_chain'::text])))),
  constraint tickets_fact_drift_object_check CHECK (((fact_drift IS NULL) OR (jsonb_typeof(fact_drift) = 'object'::text))),
  constraint tickets_happiness_check CHECK (((happiness IS NULL) OR ((happiness >= 1) AND (happiness <= 4)))),
  constraint tickets_language_check CHECK (((language IS NULL) OR (language = ANY (ARRAY['fr'::text, 'en'::text, 'es'::text, 'de'::text, 'it'::text, 'nl'::text, 'pt'::text, 'other'::text])))),
  constraint tickets_level_check CHECK (((level IS NULL) OR ((level >= 1) AND (level <= 4)))),
  constraint tickets_metadata_object_check CHECK ((jsonb_typeof(metadata) = 'object'::text)),
  constraint tickets_overrides_object_check CHECK ((jsonb_typeof(overrides) = 'object'::text)),
  constraint tickets_priority_check CHECK (((priority >= 1) AND (priority <= 5))),
  constraint tickets_related_complete_check CHECK ((((related_ticket_id IS NULL) AND (related_score IS NULL) AND (related_detected_at IS NULL)) OR ((related_ticket_id IS NOT NULL) AND (related_score IS NOT NULL) AND (related_detected_at IS NOT NULL)))),
  constraint tickets_related_not_self_check CHECK (((related_ticket_id IS NULL) OR (related_ticket_id <> id))),
  constraint tickets_related_score_range_check CHECK (((related_score IS NULL) OR ((related_score >= ('-1'::integer)::double precision) AND (related_score <= (1)::double precision)))),
  constraint tickets_request_kind_check CHECK (((request_kind IS NULL) OR (request_kind = ANY (ARRAY['question'::text, 'problem'::text, 'complaint'::text, 'contact'::text])))),
  constraint tickets_resolved_context_object_check CHECK ((jsonb_typeof(resolved_context) = 'object'::text)),
  constraint tickets_responsible_team_check CHECK (((responsible_team IS NULL) OR (responsible_team = ANY (ARRAY['finance'::text, 'marketing'::text, 'sales'::text, 'logistics'::text, 'contact'::text])))),
  constraint tickets_secondary_category_check CHECK (((secondary_category IS NULL) OR (secondary_category = ANY (ARRAY['order'::text, 'delivery'::text, 'return_exchange'::text, 'product'::text, 'product_stock'::text, 'payment'::text, 'account'::text, 'promotions'::text, 'cosmetovigilance'::text, 'legal_privacy'::text, 'b2b'::text, 'partner_collaboration'::text, 'careers'::text, 'other'::text])))),
  constraint tickets_secondary_pair_check CHECK (((secondary_request_kind IS NULL) OR (secondary_category IS NOT NULL))),
  constraint tickets_secondary_request_kind_check CHECK (((secondary_request_kind IS NULL) OR (secondary_request_kind = ANY (ARRAY['question'::text, 'problem'::text, 'complaint'::text, 'contact'::text])))),
  constraint tickets_sender_label_check CHECK (((sender_label IS NULL) OR (sender_label = ANY (ARRAY['internal'::text, 'contractor'::text, 'logistics'::text, 'courier'::text, 'retailer'::text, 'distributor'::text, 'supplier'::text, 'partner'::text])))),
  constraint tickets_status_check CHECK ((status = ANY (ARRAY['open'::text, 'awaiting_customer'::text, 'awaiting_human'::text, 'forwarded'::text, 'resolved'::text, 'closed'::text, 'spam'::text]))),
  constraint tickets_pkey PRIMARY KEY (id),
  constraint tickets_shop_conversation_unique UNIQUE (shop_id, graph_conversation_id)
);


-- ============================================================================
-- VIEWS (each after the views it reads)
-- ============================================================================

create view chat.customers as
SELECT id AS customer_id,
    shopify_created_at AS created_at,
    state AS account_state,
    locale,
    default_address_country_code AS country_code,
    number_of_orders,
    amount_spent,
    amount_spent_currency AS currency_code,
    last_order_at,
    rfm_group,
    email_marketing_state,
    on_email_marketing_list
   FROM public.customers c
  WHERE deleted_at IS NULL;

create view chat.fulfilment_timing as
SELECT o.id AS order_id,
    o.processed_at,
    f.first_fulfilled_at,
    EXTRACT(epoch FROM f.first_fulfilled_at - o.processed_at) / 3600.0 AS fulfilment_hours,
    public.normalise_carrier(f.carrier_raw) AS carrier,
    COALESCE(f.fulfilment_count, 0::bigint) AS fulfilment_count,
    o.shipping_destination ->> 'country_code'::text AS destination_country_code,
    o.sales_channel_handle AS channel,
    o.return_status,
    o.total_refunded
   FROM public.orders o
     LEFT JOIN LATERAL ( SELECT min(NULLIF(e.value ->> 'created_at'::text, ''::text)::timestamp with time zone) AS first_fulfilled_at,
            count(*) AS fulfilment_count,
            min(t.value ->> 'company'::text) AS carrier_raw
           FROM jsonb_array_elements(o.fulfillments) e(value)
             LEFT JOIN LATERAL jsonb_array_elements(
                CASE
                    WHEN jsonb_typeof(e.value -> 'tracking_info'::text) = 'array'::text THEN e.value -> 'tracking_info'::text
                    ELSE '[]'::jsonb
                END) t(value) ON true) f ON true
  WHERE o.deleted_at IS NULL;

create view chat.llm_usage as
SELECT ticket_id,
    pass,
    model,
    input_tokens,
    cached_input_tokens,
    output_tokens,
    total_tokens,
    call_count,
    succeeded,
    error_kind,
    occurred_at
   FROM public.llm_usage u;

create view chat.order_lines as
SELECT o.id AS order_id,
    l.line_index,
    o.processed_at,
    o.sales_channel_handle AS channel,
    o.cancelled_at,
    l.title AS product_title,
    l.variant_title,
    l.sku,
    l.product_id AS shopify_product_id,
    l.quantity::integer AS quantity,
    l.current_quantity::integer AS current_quantity,
    l.original_total::numeric AS original_total,
    l.discounted_total::numeric AS discounted_total
   FROM public.orders o
     JOIN public.order_lines l ON l.order_id = o.id
  WHERE o.deleted_at IS NULL;

create view chat.orders as
SELECT id AS order_id,
    name AS order_name,
    order_number,
    customer_id,
    processed_at,
    sales_channel_handle AS channel,
    sales_channel AS channel_label,
    financial_status,
    fulfillment_status,
    return_status,
    order_status,
    cancelled_at,
    cancel_reason,
    closed_at,
    currency_code,
    subtotal_price,
    total_discounts,
    total_shipping_price,
    total_tax,
    total_price,
    COALESCE(total_refunded, 0::numeric) AS total_refunded,
    shipping_destination ->> 'country_code'::text AS destination_country_code,
    shipping_destination ->> 'country'::text AS destination_country,
    jsonb_array_length(line_items) AS line_count,
    COALESCE(( SELECT sum((e.value ->> 'quantity'::text)::integer) AS sum
           FROM jsonb_array_elements(o.line_items) e(value)), 0::bigint) AS units,
    tags
   FROM public.orders o
  WHERE deleted_at IS NULL;

create view chat.products as
SELECT id AS product_id,
    shopify_product_id,
    title,
    status,
    vendor,
    product_type,
    tags,
    available_stock,
    jsonb_array_length(variants) AS variant_count,
    published_at,
    shopify_created_at AS created_at
   FROM public.products p
  WHERE deleted_at IS NULL;

create view chat.promotions as
SELECT id AS promotion_id,
    title,
    method,
    discount_type,
    status,
    summary,
    starts_at,
    ends_at,
    usage_limit,
    discount_usage_count,
    applies_once_per_customer,
    jsonb_array_length(codes) AS code_count,
    offerable_in_replies
   FROM public.promotions p
  WHERE deleted_at IS NULL;

create view chat.shop as
SELECT shop_name,
    iana_timezone,
    vip_min_spend,
    vip_min_orders,
    vip_window_months
   FROM public.shops s;

create view chat.ticket_drafts as
SELECT id AS draft_id,
    ticket_id,
    source_verdict,
    disposition,
    level,
    language,
    status,
    checks_passed,
    auto_send_eligible,
    approved_body_text IS NOT NULL AS was_rewritten,
    model,
    drafted_at
   FROM public.ticket_drafts d;

create view chat.ticket_investigations as
SELECT id AS investigation_id,
    ticket_id,
    verdict,
    proposed_level,
    jsonb_array_length(established) AS established_count,
    jsonb_array_length(missing) AS missing_count,
    model,
    investigated_at
   FROM public.ticket_investigations i;

create view chat.ticket_message_counts as
SELECT ticket_id,
    count(*) AS message_count,
    count(*) FILTER (WHERE direction = 'inbound'::text) AS inbound_count,
    max(received_at) FILTER (WHERE direction = 'inbound'::text) AS latest_inbound_at,
    max(sent_at) FILTER (WHERE direction = 'outbound'::text) AS latest_outbound_at
   FROM public.ticket_messages m
  WHERE deleted_at IS NULL
  GROUP BY ticket_id;

create view chat.ticket_reply_times as
SELECT t.id AS ticket_id,
    fi.received_at AS first_inbound_at,
    o.first_outbound_at,
    EXTRACT(epoch FROM o.first_outbound_at - fi.received_at) / 3600.0 AS reply_hours,
    date_trunc('month'::text, fi.received_at)::date AS inbound_month
   FROM public.tickets t
     JOIN LATERAL ( SELECT m.received_at
           FROM public.ticket_messages m
          WHERE m.ticket_id = t.id AND m.direction = 'inbound'::text AND m.deleted_at IS NULL
          ORDER BY m.received_at
         LIMIT 1) fi ON true
     LEFT JOIN LATERAL ( SELECT min(COALESCE(m.sent_at, m.received_at)) AS first_outbound_at
           FROM public.ticket_messages m
          WHERE m.ticket_id = t.id AND m.direction = 'outbound'::text AND m.deleted_at IS NULL AND COALESCE(m.sent_at, m.received_at) > fi.received_at) o ON true
  WHERE t.deleted_at IS NULL;

create view chat.tickets as
SELECT id AS ticket_id,
    status,
    category,
    secondary_category,
    request_kind,
    level,
    responsible_team,
    language,
    happiness,
    sender_label,
    customer_id,
    shopify_order_number,
    duplicate_of_ticket_id IS NOT NULL AS is_duplicate,
    related_ticket_id,
    first_message_at,
    last_message_at,
    categorised_at,
    investigated_at,
    resolved_at,
    closed_at,
    case_id
   FROM public.tickets t
  WHERE deleted_at IS NULL;

create view chat.vip_customers as
SELECT customer_id,
    orders_in_window,
    net_spend_in_window
   FROM chat.vip_customer_rows() v(customer_id, orders_in_window, net_spend_in_window);

create view public.case_facts with (security_invoker=true) as
SELECT k.id AS case_id,
    k.shop_id,
        CASE
            WHEN a.has_reply_thread THEN k.reply_thread_id
            ELSE a.fallback_lead_id
        END AS lead_ticket_id,
    a.thread_count,
    a.category,
    a.secondary_category,
    a.request_kind,
    a.level,
    a.happiness,
        CASE
            WHEN a.any_awaiting_human THEN 'awaiting_human'::text
            WHEN a.all_finished THEN
            CASE
                WHEN a.any_resolved THEN 'resolved'::text
                ELSE 'closed'::text
            END
            ELSE COALESCE(a.open_status, 'open'::text)
        END AS status,
    a.customer_id,
    a.shopify_order_number,
    a.first_message_at,
    a.last_message_at,
    fi.first_inbound_at,
    o.first_outbound_at,
    EXTRACT(epoch FROM o.first_outbound_at - fi.first_inbound_at) / 3600.0 AS reply_hours
   FROM public.cases k
     JOIN LATERAL ( SELECT count(*) AS thread_count,
            COALESCE(bool_or(t.id = k.reply_thread_id), false) AS has_reply_thread,
            (array_agg(t.id ORDER BY (t.status <> ALL (ARRAY['resolved'::text, 'closed'::text])) DESC, t.last_message_at DESC NULLS LAST))[1] AS fallback_lead_id,
            (array_agg(t.category ORDER BY t.first_message_at))[1] AS category,
            (array_agg(t.secondary_category ORDER BY t.first_message_at))[1] AS secondary_category,
            (array_agg(t.request_kind ORDER BY t.first_message_at))[1] AS request_kind,
            max(t.level) AS level,
            max(t.happiness) AS happiness,
            bool_or(t.status = 'awaiting_human'::text) AS any_awaiting_human,
            bool_and(t.status = ANY (ARRAY['resolved'::text, 'closed'::text])) AS all_finished,
            bool_or(t.status = 'resolved'::text) AS any_resolved,
            (array_agg(t.status ORDER BY t.last_message_at DESC NULLS LAST) FILTER (WHERE t.status <> ALL (ARRAY['resolved'::text, 'closed'::text])))[1] AS open_status,
            (array_agg(t.customer_id ORDER BY (t.id = k.reply_thread_id) DESC NULLS LAST, t.last_message_at DESC NULLS LAST) FILTER (WHERE t.customer_id IS NOT NULL))[1] AS customer_id,
            (array_agg(t.shopify_order_number ORDER BY (t.id = k.reply_thread_id) DESC NULLS LAST, t.last_message_at DESC NULLS LAST) FILTER (WHERE t.shopify_order_number IS NOT NULL))[1] AS shopify_order_number,
            min(t.first_message_at) AS first_message_at,
            max(t.last_message_at) AS last_message_at
           FROM public.tickets t
          WHERE t.case_id = k.id AND t.deleted_at IS NULL) a ON a.thread_count > 0
     LEFT JOIN LATERAL ( SELECT min(m.received_at) AS first_inbound_at
           FROM public.ticket_messages m
             JOIN public.tickets t ON t.id = m.ticket_id
          WHERE t.case_id = k.id AND t.deleted_at IS NULL AND m.direction = 'inbound'::text AND m.deleted_at IS NULL) fi ON true
     LEFT JOIN LATERAL ( SELECT min(COALESCE(m.sent_at, m.received_at)) AS first_outbound_at
           FROM public.ticket_messages m
             JOIN public.tickets t ON t.id = m.ticket_id
          WHERE t.case_id = k.id AND t.deleted_at IS NULL AND m.direction = 'outbound'::text AND m.deleted_at IS NULL AND COALESCE(m.sent_at, m.received_at) > fi.first_inbound_at) o ON true;

create view public.case_message_counts with (security_invoker=true) as
SELECT t.shop_id,
    t.case_id,
    count(DISTINCT t.id) AS thread_count,
    count(m.id) AS message_count,
    count(m.id) FILTER (WHERE m.direction = 'inbound'::text) AS inbound_count,
    max(m.received_at) FILTER (WHERE m.direction = 'inbound'::text) AS latest_inbound_at,
    max(m.sent_at) FILTER (WHERE m.direction = 'outbound'::text) AS latest_outbound_at,
    max(t.last_message_at) AS last_activity_at
   FROM public.tickets t
     LEFT JOIN public.ticket_messages m ON m.ticket_id = t.id AND m.deleted_at IS NULL
  WHERE t.deleted_at IS NULL
  GROUP BY t.shop_id, t.case_id;

create view public.customer_segment_totals with (security_invoker=true) as
SELECT shop_id,
    rfm_group,
    count(*) AS customers,
    count(*) FILTER (WHERE number_of_orders > 0) AS buyers,
    count(*) FILTER (WHERE number_of_orders > 1) AS repeat_buyers,
    count(*) FILTER (WHERE on_email_marketing_list) AS marketing_opted_in,
    sum(amount_spent) AS total_spent
   FROM public.customers c
  WHERE deleted_at IS NULL
  GROUP BY shop_id, rfm_group;

create view public.customer_ticket_facts with (security_invoker=true) as
SELECT t.lead_ticket_id AS ticket_id,
    t.shop_id,
    t.category,
    t.level,
    t.happiness,
    t.status,
    t.first_message_at,
    c.id AS customer_id,
    c.display_name AS customer_display_name,
    c.rfm_group,
    c.number_of_orders,
    c.amount_spent,
    c.last_order_at,
    c.on_email_marketing_list,
    c.default_address_country_code AS country_code
   FROM public.case_facts t
     JOIN public.customers c ON c.id = t.customer_id
  WHERE c.deleted_at IS NULL;

create view public.dropped_mail_list with (security_invoker=true) as
SELECT id,
    shop_id,
    graph_message_id,
    label,
    decided_by,
    reason,
    from_email,
    subject,
    body_captured_at,
    body_expires_at,
    failed_open,
    decided_at,
    body_text IS NOT NULL AS has_body
   FROM public.spam_audit a
  WHERE outcome = 'blocked'::text AND NOT (EXISTS ( SELECT 1
           FROM public.dropped_mail_clears c
          WHERE c.shop_id = a.shop_id AND c.spam_audit_id = a.id)) AND NOT (EXISTS ( SELECT 1
           FROM public.ticket_messages m
          WHERE m.shop_id = a.shop_id AND m.graph_message_id = a.graph_message_id));

create view public.order_fulfilment_timing with (security_invoker=true) as
SELECT o.id AS order_id,
    o.shop_id,
    o.order_number,
    o.name AS order_name,
    o.processed_at,
    f.first_fulfilled_at,
    EXTRACT(epoch FROM f.first_fulfilled_at - o.processed_at) / 3600.0 AS fulfilment_hours,
    public.normalise_carrier(f.carrier_raw) AS carrier,
    COALESCE(array_length(o.tracking_numbers, 1), 0) AS tracking_count,
    COALESCE(f.fulfilment_count, 0::bigint) AS fulfilment_count,
    o.shipping_destination ->> 'countryCode'::text AS destination_country,
    o.total_price,
    o.delivered_at,
    o.total_refunded,
    o.return_status,
    o.sales_channel_handle AS channel,
    o.sales_channel AS channel_label,
    date_trunc('month'::text, o.processed_at)::date AS processed_month
   FROM public.orders o
     LEFT JOIN LATERAL ( SELECT min(NULLIF(e.value ->> 'created_at'::text, ''::text)::timestamp with time zone) AS first_fulfilled_at,
            count(*) AS fulfilment_count,
            min(t.value ->> 'company'::text) AS carrier_raw
           FROM jsonb_array_elements(o.fulfillments) e(value)
             LEFT JOIN LATERAL jsonb_array_elements(
                CASE
                    WHEN jsonb_typeof(e.value -> 'tracking_info'::text) = 'array'::text THEN e.value -> 'tracking_info'::text
                    ELSE '[]'::jsonb
                END) t(value) ON true) f ON true
  WHERE o.deleted_at IS NULL;

create view public.ticket_first_inbound with (security_invoker=true) as
SELECT DISTINCT ON (ticket_id) ticket_id,
    shop_id,
    id AS message_id,
    subject,
    body_text,
    from_email,
    received_at
   FROM public.ticket_messages m
  WHERE direction = 'inbound'::text AND deleted_at IS NULL
  ORDER BY ticket_id, received_at;

create view public.ticket_reply_times with (security_invoker=true) as
SELECT t.id AS ticket_id,
    t.shop_id,
    fi.received_at AS first_inbound_at,
    o.first_outbound_at,
    EXTRACT(epoch FROM o.first_outbound_at - fi.received_at) / 3600.0 AS reply_hours,
    date_trunc('month'::text, fi.received_at)::date AS inbound_month
   FROM public.tickets t
     JOIN public.ticket_first_inbound fi ON fi.ticket_id = t.id
     LEFT JOIN LATERAL ( SELECT min(COALESCE(m.sent_at, m.received_at)) AS first_outbound_at
           FROM public.ticket_messages m
          WHERE m.ticket_id = t.id AND m.direction = 'outbound'::text AND m.deleted_at IS NULL AND COALESCE(m.sent_at, m.received_at) > fi.received_at) o ON true
  WHERE t.deleted_at IS NULL;

create view public.support_by_month with (security_invoker=true) as
SELECT t.shop_id,
    date_trunc('month'::text, t.first_message_at)::date AS month,
    count(*) AS tickets,
    count(*) FILTER (WHERE t.happiness >= 3) AS unhappy,
    count(*) FILTER (WHERE t.happiness = 4) AS very_unhappy,
    count(*) FILTER (WHERE t.level = 3) AS level_three,
    count(*) FILTER (WHERE t.status <> ALL (ARRAY['resolved'::text, 'closed'::text])) AS still_open,
    avg(t.happiness) AS mean_happiness,
    percentile_cont(0.5::double precision) WITHIN GROUP (ORDER BY (r.reply_hours::double precision)) AS p50_reply_hours,
    count(*) FILTER (WHERE r.reply_hours IS NOT NULL AND r.reply_hours <= 24::numeric) AS replied_within_24h,
    count(*) FILTER (WHERE r.reply_hours IS NOT NULL) AS replies_measured
   FROM public.tickets t
     LEFT JOIN public.ticket_reply_times r ON r.ticket_id = t.id
  WHERE t.deleted_at IS NULL AND t.first_message_at IS NOT NULL
  GROUP BY t.shop_id, (date_trunc('month'::text, t.first_message_at)::date);

create view public.ticket_message_counts with (security_invoker=true) as
SELECT shop_id,
    ticket_id,
    count(*) AS message_count,
    count(*) FILTER (WHERE direction = 'inbound'::text) AS inbound_count,
    max(received_at) FILTER (WHERE direction = 'inbound'::text) AS latest_inbound_at,
    max(sent_at) FILTER (WHERE direction = 'outbound'::text) AS latest_outbound_at
   FROM public.ticket_messages m
  WHERE deleted_at IS NULL
  GROUP BY shop_id, ticket_id;

create view public.ticket_queue with (security_invoker=true) as
SELECT t.id,
    t.shop_id,
    t.subject,
    t.status,
    t.category,
    t.secondary_category,
    t.level,
    t.happiness,
    t.responsible_team,
    t.requester_name,
    t.shopify_order_number,
    t.first_message_at,
    t.last_message_at,
    t.archived_at,
    t.duplicate_of_ticket_id,
    t.duplicate_reason,
    c.display_name AS customer_display_name,
    c.first_name AS customer_first_name,
    c.last_name AS customer_last_name,
    c.rfm_group AS customer_rfm_group,
    f.from_email AS requester_email,
    COALESCE(n.message_count, 0::bigint) AS message_count,
    COALESCE(n.inbound_count, 0::bigint) AS inbound_count,
        CASE
            WHEN n.latest_inbound_at IS NOT NULL AND (n.latest_outbound_at IS NULL OR n.latest_inbound_at > n.latest_outbound_at) THEN n.latest_inbound_at
            ELSE NULL::timestamp with time zone
        END AS waiting_since,
    t.sender_label,
    t.overrides,
    t.case_id,
    COALESCE(cf.lead_ticket_id = t.id, true) AS is_case_lead,
    COALESCE(cn.thread_count, 1::bigint) AS case_thread_count,
    COALESCE(cn.message_count, 0::bigint) AS case_message_count,
    COALESCE(cn.inbound_count, 0::bigint) AS case_inbound_count,
        CASE
            WHEN cn.latest_inbound_at IS NOT NULL AND (cn.latest_outbound_at IS NULL OR cn.latest_inbound_at > cn.latest_outbound_at) THEN cn.latest_inbound_at
            ELSE NULL::timestamp with time zone
        END AS case_waiting_since,
    cf.level AS case_level,
    cf.status AS case_status,
    t.resolved_at,
    t.closed_at
   FROM public.tickets t
     LEFT JOIN public.customers c ON c.id = t.customer_id
     LEFT JOIN public.ticket_message_counts n ON n.ticket_id = t.id
     LEFT JOIN public.ticket_first_inbound f ON f.ticket_id = t.id
     LEFT JOIN public.case_message_counts cn ON cn.case_id = t.case_id
     LEFT JOIN public.case_facts cf ON cf.case_id = t.case_id
  WHERE t.deleted_at IS NULL;


-- ============================================================================
-- FUNCTIONS THAT TAKE OR RETURN A TABLE OR VIEW ROW (after both exist)
-- ============================================================================

CREATE OR REPLACE FUNCTION public.claim_mail_jobs(p_shop_id uuid, p_kinds text[], p_limit integer, p_lease_seconds integer)
 RETURNS SETOF public.mail_jobs
 LANGUAGE sql
 SET search_path TO 'public'
AS $function$
  with claimed as (update public.mail_jobs j
    set state = 'running',
        locked_until = now() + make_interval(secs => greatest(p_lease_seconds, 1)),
        last_attempt_at = now(),
        retry_count = j.retry_count + case when j.state = 'running' then 1 else 0 end
    where j.id in (
      select c.id
      from public.mail_jobs c
      where c.shop_id = p_shop_id
        and c.kind = any (p_kinds)
        and (
          (c.state = 'queued' and c.next_attempt_at <= now())
          or (c.state = 'running' and c.locked_until < now())
        )
      order by c.next_attempt_at, c.created_at
      limit greatest(p_limit, 0)
      for update skip locked
    )
    returning j.*
  )
  select * from claimed;
$function$;

CREATE OR REPLACE FUNCTION public.customer_vip_call_list(p_shop uuid, p_min_spend numeric, p_min_orders integer, p_window_months integer, p_not_channels text[] DEFAULT NULL::text[], p_closed_statuses text[] DEFAULT '{}'::text[], p_min_level integer DEFAULT 3)
 RETURNS SETOF public.customer_ticket_facts
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select f.*
  from public.customer_ticket_facts f
  join public.vip_customers(p_shop, p_min_spend, p_min_orders, p_window_months, p_not_channels) v
    on v.customer_id = f.customer_id
  where f.shop_id = p_shop
    and not (f.status = any(p_closed_statuses))
    and f.level >= p_min_level
  order by f.amount_spent desc, f.ticket_id;
$function$;

CREATE OR REPLACE FUNCTION public.enqueue_mail_job(p_shop_id uuid, p_kind text, p_dedupe_key text, p_payload jsonb DEFAULT '{}'::jsonb, p_run_at timestamp with time zone DEFAULT now())
 RETURNS SETOF public.mail_jobs
 LANGUAGE sql
 SET search_path TO 'public'
AS $function$
  with queued as (insert into public.mail_jobs (shop_id, kind, dedupe_key, payload, next_attempt_at)
    values (p_shop_id, p_kind, p_dedupe_key, coalesce(p_payload, '{}'::jsonb), coalesce(p_run_at, now()))
    on conflict (shop_id, dedupe_key) where state = 'queued'
    do update set next_attempt_at = least(public.mail_jobs.next_attempt_at, excluded.next_attempt_at)
    returning *
  )
  select * from queued;
$function$;

CREATE OR REPLACE FUNCTION public.orders_in_range(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_channels text[] DEFAULT NULL::text[], p_not_channels text[] DEFAULT NULL::text[])
 RETURNS SETOF public.orders
 LANGUAGE sql
 STABLE
AS $function$
  select o.*
  from public.orders o
  where o.shop_id = p_shop
    and o.deleted_at is null
    and o.cancelled_at is null
    and o.processed_at >= (p_from at time zone p_tz)
    and o.processed_at < (p_to at time zone p_tz)
    and (p_channels is null or o.sales_channel_handle = any(p_channels))
    and (
      p_not_channels is null
      or o.sales_channel_handle is null
      or not (o.sales_channel_handle = any(p_not_channels))
    )
$function$;


