-- ============================================================================
-- COMMENTS
-- ============================================================================

comment on column chat.customers.account_state is 'ENABLED (has an account), INVITED, DISABLED. DISABLED is the default for guest checkouts, not a closed account.';
comment on column chat.customers.amount_spent is 'Lifetime spend as Shopify reports it (EUR).';
comment on column chat.customers.email_marketing_state is 'SUBSCRIBED, NOT_SUBSCRIBED, UNSUBSCRIBED, INVALID. Current state only: unsubscribes over time are undercounted.';
comment on column chat.customers.number_of_orders is 'Lifetime order count as Shopify reports it.';
comment on column chat.customers.rfm_group is 'Shopify RFM segment: CHAMPIONS, LOYAL, ACTIVE, NEW, PROMISING, NEEDS_ATTENTION, AT_RISK, ALMOST_LOST, DORMANT, PREVIOUSLY_LOYAL, PROSPECTS (never ordered).';
comment on column chat.fulfilment_timing.carrier is 'Carrier of the first shipment: one canonical upper-case name per carrier, however the fulfilment feed spelled it.';
comment on column chat.fulfilment_timing.fulfilment_hours is 'Hours from processed_at to first_fulfilled_at; null while the order has not shipped.';
comment on column chat.order_lines.current_quantity is 'Units still on the order after removals and refunds.';
comment on column chat.order_lines.discounted_total is 'Line revenue after line-level discounts (EUR), excluding shipping and order-level adjustments.';
comment on column chat.order_lines.quantity is 'Units ordered on this line.';
comment on column chat.orders.cancelled_at is 'Set when the order was cancelled. Exclude cancelled orders from sales figures.';
comment on column chat.orders.channel is 'Stable sales channel handle: web = Online Store, shopify-draft-orders = Draft Orders, shop-72 = Shop app; the marketplace handles are listed in your instructions.';
comment on column chat.orders.financial_status is 'Shopify payment state: PAID, PARTIALLY_REFUNDED, REFUNDED, VOIDED, ...';
comment on column chat.orders.fulfillment_status is 'Shopify fulfilment state: FULFILLED, UNFULFILLED, PARTIALLY_FULFILLED, ...';
comment on column chat.orders.order_status is 'Derived lifecycle: fulfilled, delivered, cancelled, return_refund_completed, ... "delivered" is only set on the few orders where a delivery was recorded; do not use it to measure delivery.';
comment on column chat.orders.tags is 'Merchant tags. Marketplace orders may carry the marketplace''s own tag.';
comment on column chat.orders.total_price is 'Order total including tax and shipping, after discounts, before refunds.';
comment on column chat.orders.total_refunded is 'Amount refunded so far; 0 when nothing was refunded.';
comment on column chat.orders.units is 'Total quantity across the order''s line items.';
comment on column chat.products.available_stock is 'Units in stock across variants at the last sync; null when not tracked.';
comment on column chat.tickets.case_id is 'The customer case this thread belongs to. Several threads can share one case (a customer who wrote again on a new thread about the same problem): count support volume as count(distinct case_id), not count(*).';
comment on column chat.tickets.category is 'Subject: order, delivery, product, product_stock, return_exchange, promotions, payment, account, b2b, careers, partner_collaboration, legal_privacy, cosmetovigilance, other. Null when not yet categorised.';
comment on column chat.tickets.happiness is 'Customer mood read from the mail: 1 happy to 4 very unhappy.';
comment on column chat.tickets.is_duplicate is 'True when the thread is a duplicate of another ticket; exclude from volume counts.';
comment on column chat.tickets.level is '1 (simple) to 4 (serious, e.g. a skin reaction). Severity, not subject.';
comment on column chat.tickets.sender_label is 'internal or contractor when one of our own addresses opened the thread; null for customer threads.';
comment on column chat.tickets.status is 'open, awaiting_customer, awaiting_human, resolved, closed.';
comment on column chat.vip_customers.net_spend_in_window is 'Sum of total_price minus refunds on those orders (EUR).';
comment on column chat.vip_customers.orders_in_window is 'Uncancelled, non-marketplace orders inside the rule''s window.';
comment on column public.advice_collections.axis is 'Local: concern (rides, taches, cernes), category (serums, cremes de nuit) or range (a product line: Temps Sublime, Source d''Eau). Concern and category are intersected and relaxed by the support agent; range is read only by the storefront advisor, for « la gamme X ».';
comment on column public.advice_collections.is_active is 'Local, never written by the sync: whether support may answer advice from this collection. False for every collection until somebody switches it on — 175 exist and most are seasonal merchandising or diagnostic-quiz output.';
comment on column public.advice_collections.note is 'Local: why the team switched this collection on, for whoever reads the list next.';
comment on column public.advice_collections.product_ids is 'Shopify product GIDs in this collection, refreshed only while is_active. Joins to products.shopify_product_id; liveness is decided against products.status at read time, never frozen here.';
comment on column public.advice_collections.products_synced_at is 'When product_ids was last refreshed. Null on a collection nobody has activated, which is the ordinary case.';
comment on column public.agent_test_runs.article_verdict is 'How far the tested article got: used, retrieved_withheld, outranked, not_retrieved, not_searched. Five states because the four failures point at four different fixes -- the wording, a competing article, the category or the embedding, and the ticket''s subject not permitting the knowledge tool at all. Derived by agent/src/testing/article-check.mjs.';
comment on column public.agent_test_runs.expect_document_id is 'The knowledge article this run was testing. Null on a free test. ON DELETE SET NULL: deleting an article must not delete the evidence of how it behaved.';
comment on column public.agent_test_runs.ideal_body_text is 'What the operator would have sent instead. The memory this table exists for: the same (model text, human text) capture ticket_draft_edits makes for real mail, except the situation can be invented, so an ideal answer can be written for a case no customer has hit yet. Nothing reads it.';
comment on column public.agent_test_runs.order_number is 'An order number the operator supplied as part of the invented situation, held apart from the body. On a real email it would be inside the text and the parser would have to find it; the run records which of the two happened.';
comment on column public.agent_test_runs.requester_email_masked is 'j***l@orange.fr -- which address this run was made with, and nothing more. Same treatment as orders.customer_email_masked. Neither the plaintext nor a hash is kept: the run matched a customer from the address in memory, and a stored hash would be a bare identifier nothing here reads.';
comment on column public.agent_test_runs.status is 'complete, gated (the spam gate would have dropped the message -- a real outcome, not a failure) or failed.';
comment on column public.agent_test_runs.total_tokens is 'What the run cost, in tokens. Deliberately NOT in llm_usage: that table answers what handling the real mailbox costs, and rehearsal spend folded into it would move the Agent panel''s per-ticket figures with nothing saying why.';
comment on column public.agent_test_runs.trace is 'Every step the run emitted, in order: the gate decision, the tool ledger with the exact text each tool returned, every model call with its system prompt and messages, and the composed drafting prompt. The flat columns beside it are an index into this, so a list of runs renders without parsing one. Shape in agent/src/testing/trace.mjs.';
comment on column public.carrier_aliases.pattern is 'Matched as a case-insensitive substring of the raw carrier name (strpos, so % and _ are literal).';
comment on column public.carrier_aliases.position is 'Order of evaluation, lowest first. Matters where one raw name contains two patterns.';
comment on column public.case_current.next_actor is 'Who owes the next step: customer | support | colleague | partner | nobody. Derived by the fold; nothing reads it to change a ticket''s status yet (stage 5).';
comment on column public.case_current.obligations is 'Checks owed by support, a colleague or an operations partner. Empty until stage 5 creates them.';
comment on column public.case_current.version is 'Raised only when material_hash changes, so a thank-you that changes nothing does not make a draft stale (codex_plans/Case_State_Plan.md, stage 6).';
comment on column public.case_links.method is 'first_contact (no other case for this customer) · reply_chain / identical_body (the duplicate rules) · tracking / order_family / unique_match (deterministic identifiers) · model (the Case Linker chose) · model_off (ambiguous, model switched off, so a new case) · no_candidates · excluded_sender (a listed sender or one of our own threads) · backfill (61_cases.sql).';
comment on column public.cases.latest_actionable_inbound_message_id is 'The newest customer message in the case that no later message of ours answers, on any of its threads. Null when everything is answered. Not a foreign key (tickets references this table); a pointer to nothing reads as no target.';
comment on column public.cases.reply_thread_id is 'The ticket holding latest_actionable_inbound_message_id: the only thread of the case that is drafted and replied on.';
comment on column public.categorisation_review.agent_category is 'Written by the comparison run, AFTER labelling. Left empty at sampling time on purpose: an agent answer visible beside an empty box anchors the reviewer and inflates agreement.';
comment on column public.categorisation_review.blocklist_would_drop is 'True when email_blocklist would have dropped this message before the categoriser ever saw it. Recorded, not filtered, so the sample stays honest about what the inbox actually contains.';
comment on column public.categorisation_review.from_domain is 'Sender domain only, never the address. Enough to tell a B2B enquiry from a consumer one without identifying the person.';
comment on column public.categorisation_review.human_category is 'THE COLUMN TO FILL IN: the correct subject, from the same 14 values tickets.category allows. Constrained, so a typo is rejected rather than counted as a disagreement.';
comment on column public.categorisation_review.human_level is 'THE COLUMN TO FILL IN (optional): 1 answerable from knowledge, 2 needs a data lookup or a simple advice reply, 3 needs a state-changing action, 4 severity only -- explicit threat of legal action or public exposure, hospitalisation, or grave injury/danger. Leave null to accept the level derived from (category, kind).';
comment on column public.categorisation_review.human_request_kind is 'THE COLUMN TO FILL IN: question | problem | complaint | contact. `contact` is only for b2b, partner_collaboration and careers.';
comment on column public.categorisation_review.retention_delete_after is 'Default 3 months -- shorter than tickets, since a review set has no operational value once scored. Deleted by the retention cleanup job (not yet built).';
comment on column public.category_forwarding.category is 'Ticket subject from the shared taxonomy in scripts/lib/support-taxonomy.mjs. Only the 14 ticket subjects -- faq and brand_story are knowledge-only and cannot be a ticket category.';
comment on column public.category_forwarding.forward_email is 'Internal recipient. Null or absent means this category is never forwarded, which is the default for every category on a fresh install.';
comment on column public.cluster_runs.internal_excluded is 'Messages skipped because the sender directory says they are ours. Recorded so a shrinking map can be told apart from a growing blocklist.';
comment on column public.cluster_runs.threshold is 'The cosine similarity threshold this run used. Corpus-specific and hand-tuned; exposed in the resync dialog because it is the one knob that changes the answer.';
comment on column public.company_policies.content is 'The policy text. May carry {parameter} placeholders (support_parameters keys), filled when the agent reads it, so a number lives in one place.';
comment on column public.company_policies.version is 'Raised on every change of content; each version''s text is kept in company_policy_versions, and a case file records the version it read.';
comment on column public.customers.amount_spent is 'Lifetime Shopify amount spent from Customer.amountSpent.';
comment on column public.customers.default_address_formatted_area is 'Coarse customer location from the default address. Street address and postcode are intentionally not stored here.';
comment on column public.customers.email is 'Customer email for support lookup. Do not include this field in AI prompts unless strictly required.';
comment on column public.customers.number_of_orders is 'Lifetime Shopify order count from Customer.numberOfOrders.';
comment on column public.customers.on_email_marketing_list is 'Generated from Shopify defaultEmailAddress.marketingState = SUBSCRIBED.';
comment on column public.customers.phone is 'Customer phone for support lookup. Do not include this field in AI prompts unless strictly required.';
comment on column public.customers.raw_shopify_payload is 'Not written since 2026-10-06 (always {}): nothing read it, and its fields are typed columns. Kept as a column so a reader that names it does not break.';
comment on column public.customers.rfm_group is 'Shopify-computed Customer.statistics.rfmGroup category used by Shopify customer segmentation as rfm_group.';
comment on column public.data_access_events.resource_id_hash is 'Stable hash of the accessed resource identifier. Avoid storing direct customer email, phone, or address values.';
comment on column public.email_blocklist.hit_count is 'Number of inbound messages this rule has blocked. Bumped by the ingestion worker; last_hit_at records the most recent block.';
comment on column public.email_blocklist.pattern is 'The normalised sender email or domain to block. Matched case-insensitively against the inbound sender at ingestion.';
comment on column public.email_blocklist.pattern_type is 'email (exact sender address) or domain (sender domain, e.g. spammer.example). Patterns are stored normalised (trimmed, lowercased; domain without a leading @).';
comment on column public.forwarding_destinations.active_since is 'The destination''s switch. Null is off. Otherwise the moment it was switched on: only mail received from then on is forwarded to it, so switching it back on never delivers what arrived while it was off. Needs an address to be on.';
comment on column public.forwarding_destinations.public_name_fr is 'The phrase that follows « Nous l''avons transmis » in the acknowledgement, preposition included: « au service comptabilité ». Null reads « au service concerné ».';
comment on column public.forwarding_destinations.timing is 'immediate: forwarded as soon as routed, with the acknowledgement. after_first_reply: forwarded once the contact team''s first reply has gone out (cosmetovigilance and defects ask for information first).';
comment on column public.forwarding_settings.forward_since is 'The master switch. Null forwards nothing. Otherwise only inbound mail received at or after this instant is forwarded, so turning forwarding on never sends the backlog.';
comment on column public.knowledge_chunks.category is 'Denormalised copy of the parent knowledge_documents.category, kept in step with it. Included in embedded_input_hash, so a category change invalidates the chunk vector and the next embed run refreshes it.';
comment on column public.knowledge_chunks.embedded_at is 'Timestamp the embedding was last computed.';
comment on column public.knowledge_chunks.embedded_input_hash is 'Hash of the exact composed input text sent to the embedding model (title + category + section heading + chunk text). Distinct from content_hash, which ignores title/category/heading; a category rename changes this hash and invalidates the vector.';
comment on column public.knowledge_chunks.embedding is 'pgvector embedding (text-embedding-3-small, 1536 dims) for cosine retrieval. Present only while the parent document is approved and the vector matches the current composed input; cleared when the document leaves approved.';
comment on column public.knowledge_chunks.embedding_dimensions is 'Dimension count requested for the embedding (1536). Used alongside embedding_model to detect vectors that must be recomputed.';
comment on column public.knowledge_chunks.embedding_model is 'OpenAI model the embedding was produced with, e.g. text-embedding-3-small. Used to detect stale vectors after a model change.';
comment on column public.knowledge_chunks.product_ids is 'Denormalised from knowledge_documents.product_ids, the same way category is, so retrieval can resolve a product without a second query per hit.';
comment on column public.knowledge_chunks.token_count is 'Approximate token count used to tune chunking and prompt budgets.';
comment on column public.knowledge_documents.approval_status is 'Team review state for agent usage: draft, in_review, approved, or needs_optimization. Independent of status, which holds the Shopify publish state for Shopify-sourced articles.';
comment on column public.knowledge_documents.category is 'Article subject, from the shared support taxonomy in scripts/lib/support-taxonomy.mjs. Every article but a brand story is an FAQ, shown as « <subject> FAQ »: the ticket subjects except the catch-all other, plus the knowledge-only shapes faq (General FAQ) and brand_story. Tickets additionally carry a request_kind; an article is reference material and has no kind.';
comment on column public.knowledge_documents.content_html is 'Rich-text HTML as edited in the Agent Setup dashboard. Source of truth for the editor; content_text and sections are regenerated from this on every save, import, or resync.';
comment on column public.knowledge_documents.content_text is 'Cleaned canonical plain text used for AI context.';
comment on column public.knowledge_documents.core_topic is 'The fixed slot this article fills: brand (the Brand voice) or null. At most one active article per shop per slot. Distinct from the category column. The other five slots were removed 2026-10-01 (56_policy_search_retired.sql).';
comment on column public.knowledge_documents.navigation_area is 'Where the page is exposed in the storefront navigation: header, footer, or manual.';
comment on column public.knowledge_documents.product_ids is 'Products this article is about, set by an operator in the knowledge editor. Lets a retrieved chunk resolve the product a question was about when the title matcher could not -- the words customers use about a device (batterie, telecommande, s''allume) are in no product title. Denormalised onto knowledge_chunks. Never overrides a product the customer named, and never sets reaction_product: a cosmetovigilance attribution must come from the customer, not from which article was retrieved.';
comment on column public.knowledge_documents.sections is 'Ordered section objects parsed from the page content, usually containing heading, text, order, and anchor.';
comment on column public.knowledge_documents.source_metadata is 'Small sanitized source metadata snapshot. Do not store full page HTML or unnecessary raw payloads here.';
comment on column public.knowledge_documents.source_type is 'shopify_page, shopify_policy, or manual. Editing an imported article in the dashboard converts this to manual (shopify_source_id/handle are kept for provenance), which is what stops it from being resynced from Shopify going forward.';
comment on column public.knowledge_documents.voice_profile is 'Structured brand-voice fields for the singleton Brand Voice article (core_topic = ''brand''): { roleDescription: string, toneAndVoice: string }. Empty ({}) on every other article. Always-included drafting-agent context, distinct from content_html (used on this row for freeform general-context guidance) and from ordinary knowledge_documents rows, which are selectively retrieved via knowledge_chunks.';
comment on column public.llm_usage.pass is 'Which agent pass spent this: spam | categorise | decompose | situation | investigate | draft | embed | case_link | casework | closure | other. Matches the passes in the worker poll order, and the USAGE_PASSES list in agent/src/llm/usage-sink.mjs.';
comment on column public.llm_usage.succeeded is 'False for a call that errored or was abandoned. Those cost money too, so they are recorded rather than filtered out at the write.';
comment on column public.llm_usage.ticket_id is 'The ticket this call was spent on, where there is one. Null for embedding reconciliation and for spam-gate decisions, which are taken before any ticket exists.';
comment on column public.mail_jobs.dedupe_key is 'sync:<folder> or send:<outbound action id>. Unique among QUEUED rows only, so a burst of notifications collapses into one job while a job already running never swallows a newer request.';
comment on column public.mail_jobs.next_attempt_at is 'Not claimable before this. Pushed out with exponential backoff on each failure (scripts/lib/mail-job-record.mjs backoffMs).';
comment on column public.mail_jobs.retry_count is 'Failed attempts so far, including a lease that ran out. Compared against MAIL_JOB_MAX_ATTEMPTS by the worker.';
comment on column public.mail_jobs.state is 'queued -> running -> done, or dead once retry_count reaches the cap. A running row whose locked_until has passed is claimable again (the worker died holding it).';
comment on column public.mail_subscriptions.client_state_hash is 'sha256 of the clientState secret given to the provider at creation. The webhook hashes the clientState a notification carries and compares; the secret itself is never stored.';
comment on column public.mail_subscriptions.last_error is 'The last create or renew failure, one line. Paired with an error-level log (mail.subscription_renew_failed): the alert, until the project has an alert channel.';
comment on column public.order_lines.line_index is 'The element''s 1-based position in orders.line_items (WITH ORDINALITY).';
comment on column public.order_lines.quantity is 'Text as in the JSON; cast ::int where read. current_quantity, original_total and discounted_total likewise (::int / ::numeric).';
comment on column public.orders.customer_email_hash is 'Hash of the order contact email for support lookup without duplicating raw email on the order row.';
comment on column public.orders.customer_email_masked is 'The order contact address reduced to a recognisable form (j***l@orange.fr), derived beside customer_email_hash from the same input so the two can never describe different addresses. NOT a raw address: the local part is destroyed at map time. It answers the question a hash cannot -- which address is this? -- for a human reviewing an ownership mismatch. Never sent to a model: the tool layer withholds it, and only the dashboard renders it.';
comment on column public.orders.customer_id is 'Optional link to the local customer snapshot. Guest orders or unsynced customers may only have shopify_customer_id or hashed contact fields.';
comment on column public.orders.customer_phone_hash is 'Hash of the order contact phone for support lookup without duplicating raw phone on the order row.';
comment on column public.orders.delivered_at is 'Timestamp when the order was confirmed delivered from Shopify fulfillment/tracking data. Used as the retention anchor for completed delivered orders.';
comment on column public.orders.discount_applications is 'One entry per promotion applied to this order, from Shopify discountApplications: kind (code/automatic/manual/script), name (the typed code, or the promotion title), percentage or amount, and what it targeted. Empty where none applied. Read by the agent to answer "was my promotion or gift applied?" by name rather than by amount.';
comment on column public.orders.discount_codes is 'Discount codes typed on this order. Empty on automatic promotions, which is what this shop runs — the name then lives in discount_applications.';
comment on column public.orders.fulfillments is 'Sanitized fulfillment and tracking summaries needed for order tracking support.';
comment on column public.orders.line_items is 'Sanitized Shopify line item snapshots for support workflows, excluding customer personal data.';
comment on column public.orders.order_status is 'Dashboard-facing order lifecycle stage derived from cancellation, return/refund, delivery, and fulfillment state.';
comment on column public.orders.raw_shopify_payload is 'Not written since 2026-10-06 (always {}): nothing read it, and its fields are typed columns. Kept as a column so a reader that names it does not break.';
comment on column public.orders.refunds is 'Sanitized refund summaries needed for support workflows.';
comment on column public.orders.retention_delete_after is 'Timestamp after which the local operational order snapshot can be deleted: the anchor named by retention_rule plus the shop retention period. NULL MEANS KEPT INDEFINITELY -- not a missing value. The purge selects rows whose date is at or before now, so a null is simply never matched and needs no special case in the delete path.';
comment on column public.orders.retention_rule is 'WHY the retention clock started, not how long it runs: delivered, undelivered, return_refund_completed, or return_refund_open. The period is the shop setting (shops.order_retention_mode/_months) and arrives here already applied as retention_delete_after.';
comment on column public.orders.return_refund_completed_at is 'Timestamp when a return or refund process was completed. Used as the retention anchor before deleting completed return/refund cases.';
comment on column public.orders.return_refund_opened_at is 'Timestamp when a return or refund process was first detected. Used as the retention anchor for unresolved return/refund cases.';
comment on column public.orders.returns is 'Sanitized return summaries needed for support workflows and order retention decisions.';
comment on column public.orders.sales_channel is 'Merchant-facing sales channel label shown in Shopify Admin order lists, such as Online Store, POS, Amazon, or another marketplace.';
comment on column public.orders.sales_channel_handle is 'Stable Shopify sales channel or order attribution handle when available, useful for filtering and matching channel-specific workflows.';
comment on column public.orders.shipping_destination is 'Coarse shipping destination only, such as city, province, country, and country code. Do not store street address or postcode here.';
comment on column public.orders.source_name is 'Raw Shopify order source name, such as web, pos, mobile_app, or a third-party source identifier. This is not always the merchant-facing sales channel label.';
comment on column public.orders.tracking_numbers is 'Every carrier tracking number on the order, lifted out of fulfillments and normalised (uppercase, no spaces/dots/hyphens) so it can be matched against what a customer types. Denormalised for lookup only -- fulfillments remains the record. Populated by the order sync; a parcel-chasing ticket that quotes a tracking number instead of an order number is resolved through this column.';
comment on column public.outbound_actions.body_html is 'What is sent: the reply as HTML, sanitised by scripts/lib/reply-html.mjs (paragraphs, bold, italics, underline, lists, https/mailto links; no attributes but href). body_text is its plain text. Null only on rows written before the column, which are sent from body_text.';
comment on column public.outbound_actions.cancel_reason is 'Which pre-send check refused: case_moved, customer_wrote_again, already_answered, draft_withdrawn, auto_send_off, facts_pending (the order moved materially and the pipeline has not read it yet; 69_fact_drift.sql). Present exactly when state is cancelled.';
comment on column public.outbound_actions.client_key is 'A manual reply''s idempotency key, minted by the dashboard composer once per reply, so a double click or a retried request is one email. Present exactly on manual rows, which the case-version index leaves out.';
comment on column public.outbound_actions.mode is 'human_approved (a person approved or edited a draft) | auto_send (the level gate, only with DRAFT_ONLY off) | manual (a person wrote the reply on the ticket page; no draft, action_type manual_reply, keyed on client_key).';
comment on column public.outbound_actions.provider_draft_id is 'The provider''s id for the reply draft. With immutable ids it survives the move to Sent Items, so ingestion''s stored graph_message_id matches it exactly.';
comment on column public.outbound_actions.reply_to_message_id is 'The customer message this reply answers. The recipient is its from_email, read at send time; no address is stored here.';
comment on column public.outbound_actions.state is 'approved | draft_created | send_requested | sent_confirmed | cancelled | failed. send_requested is written BEFORE the send call and means "maybe sent": the worker asks the mailbox before any retry. sent_confirmed only once ingestion has stored the sent mail.';
comment on column public.products.active_ingredients is 'Shopify product metafield: Actifs & ingredients.';
comment on column public.products.available_stock is 'Product-level available stock summary, currently synced as the sum of Shopify variant inventory quantities when available.';
comment on column public.products.ingredients_popup is 'Shopify product metafield: ingredients popup.';
comment on column public.products.product_faq_metaobject_ids is 'Shopify metaobject IDs linked from the product FAQ list metafield. Canonical FAQ content lives in shopify_metaobjects.';
comment on column public.products.product_faqs is 'Optional denormalized product FAQ snapshot for AI/search. Canonical linked FAQ metaobjects are referenced by product_faq_metaobject_ids.';
comment on column public.products.product_ingredient_metaobject_ids is 'Shopify metaobject IDs linked from the Product Ingredients metafield. Canonical ingredient content lives in shopify_metaobjects.';
comment on column public.products.product_ingredients is 'Optional denormalized product ingredient snapshot for AI/search. Canonical linked ingredient metaobjects are referenced by product_ingredient_metaobject_ids.';
comment on column public.products.raw_shopify_payload is 'Sanitized raw Shopify product payload for traceability. Do not include image binaries or unnecessary personal data.';
comment on column public.products.recommended_for_concerns is 'LOCAL, not from Shopify: which skin concerns support may recommend this product for. Survives the sync because mapProductRow does not write it. NOT the tags -- those say what a product is compatible with (peaux sensibles is on 52 of 90 sellable products, tous les types de peaux on 52 more), which is right for a product page and useless for a recommendation. This is what support should actually put forward. Empty means not curated, and the lookup returns nothing rather than falling back to a shortlist of 64.';
comment on column public.products.short_description is 'Shopify product metafield: Short description.';
comment on column public.products.structured_facts is 'AI-safe structured product facts extracted from Shopify fields, metafields, or metaobjects.';
comment on column public.products.usage_advice is 'Shopify product metafield: Conseils d''utilisation.';
comment on column public.products.usage_instructions is 'Shopify product metafield: Usage Instructions.';
comment on column public.products.variants is 'Structured Shopify variant snapshots as JSONB. Keep query-critical fields duplicated here before adding more tables.';
comment on column public.promotions.applies_once_per_customer is 'Shopify appliesOncePerCustomer flag for manual filtering of customer-specific or one-use promotions.';
comment on column public.promotions.codes is 'Redeem codes for this discount: [{ code, usage_count, redeem_code_id }]. Empty for automatic discounts. One row per discount rather than per code — a bulk-generated discount carries up to 600 codes, and duplicating the whole snapshot per code cost 7,512 rows and 22 MB where 324 rows do. usage_count is per CODE and is load-bearing: most codes here are single-use, so "this code has already been used" is the answer to the commonest promotions question, and a bare list of codes could not carry it.';
comment on column public.promotions.describable_in_replies is 'LOCAL, not from Shopify: may support describe this AUTOMATIC offer (free shipping, gift with purchase, multi-buy) to a customer? Survives the sync like offerable_in_replies -- mapPromotionRow never writes it. Defaults to true because an automatic offer is advertised on the site and applies itself, so explaining it hands out nothing; an operator turns one off to keep it out of replies. Ignored on code promotions, which offerable_in_replies governs.';
comment on column public.promotions.offerable_in_replies is 'LOCAL, not from Shopify: may support offer this code to a customer? Survives the sync because mapPromotionRow does not write it and the upsert merges duplicates -- nothing may ever add this key to the mapper. Defaults to false because "all active codes" includes a 100%-off product code and two partner rates on this shop, and a picker offering those is one mis-click from a free order.';
comment on column public.promotions.promotion_key is 'Stable local unique key. One row per DISCOUNT, so this is the discount node ID.';
comment on column public.promotions.raw_shopify_payload is 'Sanitized raw Shopify discount payload for traceability. Exclude customer targeting details and personal data.';
comment on column public.promotions.rule_snapshot is 'Sanitized promotion rule metadata such as discount classes, combines-with flags, context type, and requirement types. Do not store customer targeting details.';
comment on column public.promotions.source_metadata is 'Small source metadata snapshot such as code count and creator app name. Do not store customer IDs, emails, phone numbers, or customer selection payloads.';
comment on column public.sender_directory.label is 'What this sender is to us. internal and contractor are us; logistics and courier are operational counterparties; retailer, distributor, supplier and partner are commercial ones whose mail is real demand, just not consumer demand.';
comment on column public.sender_directory.note is 'Optional free text carried verbatim into the case file, for the context a colleague would give out loud. Nothing branches on it.';
comment on column public.sender_directory.pattern_type is 'email (exact sender address) or domain (sender domain). Matched exactly like email_blocklist, subdomains included: a domain rule for deret.fr also matches mail.deret.fr.';
comment on column public.shopify_content_sources.source_type is 'shopify_page or shopify_policy. Distinguishes which Shopify resource this row indexes, since pages and policies are fetched and resolved through different Shopify Admin API calls.';
comment on column public.shopify_content_sources.status is 'Shopify publish state: published or unpublished. Policies are always published (Shopify has no draft state for a filled-in policy); pages derive this from publishedAt presence.';
comment on column public.shopify_metaobjects.definition_fields is 'Shopify metaobject definition field schema snapshot for interpreting fields JSONB.';
comment on column public.shopify_metaobjects.definition_name is 'Human-readable Shopify metaobject definition name, for example Product FAQ or Ingredients List.';
comment on column public.shopify_metaobjects.fields is 'Structured metaobject field values synced from Shopify.';
comment on column public.shopify_metaobjects.metaobject_type is 'Shopify metaobject type, for example product FAQ or ingredient.';
comment on column public.shopify_metaobjects.raw_shopify_payload is 'Sanitized raw Shopify metaobject payload for traceability. Do not store image binaries or unnecessary personal data.';
comment on column public.shopify_metaobjects.shopify_metaobject_id is 'Stable Shopify metaobject ID/GID used by products to reference this shared content.';
comment on column public.shops.customer_accounts_version is 'CLASSIC or NEW_CUSTOMER_ACCOUNTS. Decides whether a password exists at all: under the new accounts sign-in is a one-time emailed code, and every reply about resetting a password would be wrong.';
comment on column public.shops.iana_timezone is 'The shop''s IANA timezone from Shopify''s ianaTimezone (Europe/Paris). Where a day starts on the Insights charts. Null until the next shop sync; the reader falls back to UTC and says so.';
comment on column public.shops.order_retention_mode is 'How long orders are kept: months (with order_retention_months) or indefinite (with none). Read by scripts/lib/order-retention.mjs. Deliberately not a support_parameters row -- there a null value means "nobody has decided yet", and indefinite retention of personal data must never be reachable by leaving a field blank.';
comment on column public.shops.order_retention_months is 'The retention period in months when order_retention_mode is months. Must be null when the mode is indefinite, so the setting has exactly one reading.';
comment on column public.shops.order_retention_reason is 'Why the retention period was last changed. Retention is a compliance control and the live constraint has already drifted from this repo once; a change with no recorded reason is how that happened.';
comment on column public.shops.storefront_url is 'Shopify primaryDomain.url -- where customers actually go, unlike shop_domain which is the *.myshopify.com identity webhooks key on. The only address a reply may contain, and the base for /account/login.';
comment on column public.shops.sync_cursors is 'Per-resource sync cursors for Shopify imports, webhooks, and reconciliation jobs.';
comment on column public.shops.vip_min_spend is 'VIP rule, set on the Customers panel: net spend inside the window must be MORE THAN this (EUR), AND orders more than vip_min_orders. Null with the other two = no rule, nobody is VIP.';
comment on column public.social_accounts.engagement_basis is 'What interactions are divided by for this account''s engagement rate: followers, reach (default) or views. One per platform, chosen by the team.';
comment on column public.social_posts.insights_at is 'When Meta last answered this post''s insights; null = never read. The sync reads never-read posts once, whatever their age.';
comment on column public.social_posts.non_followers_pct is 'Percent (0-100) of the people the post reached who do not follow the account, typed in by the team from the platform''s own app: the API does not give it per post. Never written by a sync.';
comment on column public.spam_audit.body_captured_at is 'When the body was written -- by ingestion at the moment of the decision, or later by the Graph backfill for rows that predate 08. Null on any row whose body was never captured.';
comment on column public.spam_audit.body_expires_at is 'When body_text becomes purgeable. Set from body_captured_at plus the worker''s retention window (SPAM_AUDIT_BODY_RETENTION_DAYS, default 90). Deliberately separate from the row''s own life: the decision is audit metadata and is kept, the message text is personal data and is not.';
comment on column public.spam_audit.body_text is 'Cleaned plain-text body of the dropped email, capped in code. THE REASON THE TABLE IS REVIEWABLE: a subject line cannot distinguish a newsletter from a customer whose parcel is lost, so without this a reviewer cannot judge the gate''s decision at all. Retained personal data with a bounded life -- nulled by the worker''s purge once body_expires_at passes, leaving the decision row intact. Null means never captured, or captured and since expired.';
comment on column public.spam_audit.decided_by is 'blocklist (deterministic email/domain rule, first pass) or llm (cheap-tier classifier, second pass, new conversations only).';
comment on column public.spam_audit.failed_open is 'True when the email was kept only because the classifier errored or was unavailable. The gate fails open by design; this column makes those keeps distinguishable from judged-legitimate ones.';
comment on column public.spam_audit.from_email is 'Sender address of the audited email. Kept so a decision can be reviewed and a repeat spammer turned into an email_blocklist rule; this is the deliberate narrow exception to not storing blocked mail.';
comment on column public.spam_audit.label is 'The LLM classifier label (keep | spam | irrelevant). Null for blocklist decisions, which have no label.';
comment on column public.spam_audit.outcome is 'kept (the email was written to tickets/ticket_messages) or blocked (dropped before any write).';
comment on column public.spam_audit.reason is 'One short line explaining the decision. For an LLM keep the model was not confident about, this is literally "unsure" -- the fail-safe "when in doubt, keep" path is recorded as such rather than as a positive judgement.';
comment on column public.support_answers.answer_set is 'The family this answer belongs to (promo, commande, retour, produit). support_exemplars.answer_set names which family a situation draws from; without that scoping a promotions answer could be selected for a product question whose need sets happen to overlap.';
comment on column public.support_answers.ask is 'MISSING_FIELDS keys when the rule''s answer is to ask for something. Keys, never sentences: case-file.mjs owns the wording. A LIST because one reply can need two facts -- a reaction with no product named wants the product AND the batch number, and one slot would have made that two round trips. Empty rather than null for "asks nothing". A non-empty list requires route = needs_customer_input, or drafting would hold a question it is not permitted to ask.';
comment on column public.support_answers.checks is 'The checks this rule opens on a case, in order: [{owner, need}], owner support / colleague / partner, need a NEED_KEYS key. The fold (agent/src/casework/case-fold.mjs) opens the first when a case file selects this rule and each next one when the one before it is done; a step marked no longer needed ends the sequence. Copied onto the case file (exemplar_match.policy.check_sequences), so editing the rule never changes a case already opened.';
comment on column public.support_answers.is_fallback is 'The catch-all for this set, whose conditions are ignored. At most one per set. Absent one, an unmatched evidence position yields no answer and the ticket routes to a person.';
comment on column public.support_answers.knowledge_document_id is 'The approved article that answers this rule''s position, or null. The second value a rule carries rather than a condition, alongside offer_code, and for the same reason: some situations have a canonical answer in one article and rediscovering it by semantic search per ticket makes the reply depend on retrieval. PER RULE, NOT PER SITUATION -- pinned to the situation it would also attach to the branch that fires when NO article answered, which is the branch that exists for exactly that case. A real FK, unlike offer_code, because these rows are ours and no sync rewrites them; set null on delete so removing an article never removes a rule. Approval is re-checked at drafting time and the article dropped if it is no longer approved, the same treatment offer_code gets.';
comment on column public.support_answers.link_label is 'What link_url opens, in the words the reply uses (« le guide d''utilisation »). Present exactly when link_url is.';
comment on column public.support_answers.link_url is 'An https page this rule''s reply offers the customer, or null. Never shown to the drafting model: it is given link_label and writes a [[marker]], and code puts this address on the marked word wherever the draft is shown, so no_web_link still holds. Copied onto ticket_drafts.reply_link at drafting time, so editing the rule never re-points a draft already written.';
comment on column public.support_answers.notify_on is 'The event this rule is the template for when we write to the customer unasked: refund_recorded (a refund created in Shopify that no message of ours has reported, on a ticket in this rule''s answer set). Null on every other rule. The change router (agent/src/casework/change-router.mjs) detects the event; the drafting pass writes the notice with this rule''s skeleton, for a person to approve.';
comment on column public.support_answers.offer_code is 'A live discount code this rule hands to the customer, chosen by an operator from the promotions marked offerable_in_replies. The one place a rule carries a VALUE rather than a condition: which code to give somebody is a commercial decision that changes with the season and cannot be derived from the ticket. No foreign key -- promotions is Shopify-synced, so a constraint would block the sync or delete rules when a code expires. Re-checked at drafting time and dropped if it has stopped being offerable.';
comment on column public.support_answers.route is 'Where a matched rule sends the ticket, or null to leave the verdict as the investigation set it. Tighten only -- "answerable" is absent from the check constraint by design, so a rule can hand a ticket to a person but never declare one safe.';
comment on column public.support_answers.situation_key is 'Which situation this rule is for (support_exemplars.exemplar_key), or null for any situation in the set. The second axis: when_conditions says what is true about the order, this says what the customer wants. A rule naming only conditions still fires when no exemplar matched.';
comment on column public.support_answers.tones is 'The tones this rule''s reply should take, as keys of scripts/lib/reply-tones.mjs, which owns their wording. Empty means the Brand voice alone. PER RULE, NOT PER SITUATION: D-01 late wants an apology and D-01 within the window forbids one, and only the branch knows which. When an email carries two requests their rules'' tones are unioned. A tone adjusts the Brand voice in the drafting prompt and never overrides its structural rules.';
comment on column public.support_answers.when_conditions is 'A conjunction across needs, a disjunction within one: { "promotion_validity": ["expired","not_found"] } matches when validity took either value. Keys are needs and values are findings, both from agent/src/investigation/evidence-rules.mjs; the condition builder validates against findingValues() so a typo cannot become a permanently dead branch.';
comment on column public.support_exemplar_phrasings.embedded_input_hash is 'Hash of the exact text sent to the embedding model. Unlike a knowledge chunk, a phrasing is embedded ALONE -- no title or heading prefix -- because it is already a complete question and the query it is compared against is a bare customer email.';
comment on column public.support_exemplar_phrasings.embedding is 'pgvector embedding (text-embedding-3-small, 1536 dims). Present only while the parent exemplar is approved and the vector matches the current composed input; cleared when it leaves approved.';
comment on column public.support_exemplar_phrasings.language is 'The language this phrasing is written in, from the same vocabulary as tickets.language. Defaults to fr because the authored corpus is French. Retrieval does NOT filter on it -- an English email is free to match a French phrasing, just poorly, which is the problem this column exists to let us measure.';
comment on column public.support_exemplar_phrasings.phrasing_kind is 'canonical for the tidy question, variant for a real customer phrasing, translated for machine output derived from one of the other two. All three are embedded and searched identically; the distinction is for the editor and for reporting which register actually matches.';
comment on column public.support_exemplar_phrasings.search_vector is 'Lexical index over the phrasing, accent-insensitive French. Defined ahead of use: exemplar retrieval ships dense-plus-metadata, and turning on the lexical half should be a code change rather than a schema one.';
comment on column public.support_exemplar_phrasings.translated_from_index is 'The phrasing_index this was translated from, within the same exemplar. Null unless phrasing_kind is translated. Translations occupy phrasing_index 100 and above so that import-exemplars.mjs, which prunes anything past the end of the authored list, cannot delete them.';
comment on column public.support_exemplars.approval_status is 'Team review state. Only approved exemplars hold phrasing vectors, so this is also the retrieval gate -- the same rule as knowledge_documents.';
comment on column public.support_exemplars.category is 'Situation subject, from the shared support taxonomy. Used to filter retrieval; an exemplar must never re-route a ticket''s own category.';
comment on column public.support_exemplars.choose_rule is 'When to choose this situation over its neighbours, and when not to: one line, shown to the situation chooser beside the candidate''s question and phrasings when the matcher could not separate them (near miss or tie). Authored on the **choose_rule** line of Email-Example-Queries.md. Never embedded and never read by the matcher''s score.';
comment on column public.support_exemplars.demand_message_count is 'How many real customer messages clustered behind this situation. Authoring priority, and the denominator for coverage reporting.';
comment on column public.support_exemplars.exemplar_key is 'Stable human handle from the source analysis (P-16, D-01). Unique per shop, so a re-import updates the existing row rather than creating a second one.';
comment on column public.support_exemplars.never_auto_send is 'Set by a person on the Rules page: a draft answering this situation is written but never sends itself, whatever the ticket''s level or category. The drafting pass records it as an auto_send_blockers entry (reason situation).';
comment on column public.support_exemplars.requirement_needs is 'The facts a correct reply must rest on, from the closed vocabulary in agent/src/investigation/evidence-rules.mjs. Declared here as a second source alongside the per-ticket needs the decomposition model emits; which one wins is deliberately not settled in the schema.';
comment on column public.support_parameters.kind is 'How to parse `value`: days (whole number), amount (decimal), text. Checked by constraint, so a days parameter can always be compared against a date.';
comment on column public.support_parameters.parameter_key is 'The handle code reads, e.g. returns_window_days. Constrained to lower snake case: a key is compared literally, and a stray capital would produce a parameter nothing reads.';
comment on column public.support_parameters.value is 'The value as text, parsed according to `kind`. NULL means the parameter exists and nobody has decided it yet -- a real state, and the one every parameter starts in, because seeding a guess would put a third answer into circulation wearing the authority of a setting.';
comment on column public.ticket_case_state.case_relationship is 'continuation | new_information | new_issue | unclear. Drives whether the categoriser re-runs and whether the situation is carried forward; a closed vocabulary the model selects from and this codebase defines.';
comment on column public.ticket_case_state.effect is 'What the message did, from agent/src/casework/effects.mjs (inbound or outbound list by actor). Null on a reading from before stage 5.';
comment on column public.ticket_case_state.evidence_reuse is 'Per need a prior run touched: { tool, argsHash, outcome, run_at, status }. Outcome buckets only, never tool data -- the same personal-data boundary tool_calls and context_ref already hold.';
comment on column public.ticket_case_state.obligations_opened is 'Checks this message opened: { owner: support | colleague | partner, need (NEED_KEYS), quote }. Only owners this brand has (obligationOwners).';
comment on column public.ticket_case_state.resolved_inputs is 'MISSING_FIELDS keys this message answered. Recorded when the question is answered rather than recovered from prose later, which is what makes it a fact rather than a guess.';
comment on column public.ticket_case_state.situation_key is 'The situation carried forward from the previous reading, so a follow-up is not re-matched on the opening message every run. Null when none was ever matched.';
comment on column public.ticket_clusters.member_message_ids is 'The ticket_messages in this cluster. An array rather than a join table because a cluster is written and read whole; the GIN index still answers "which cluster holds this message?".';
comment on column public.ticket_draft_edits.edited_by is 'Who made the edit. Null on every row until the dashboard has authentication -- there is no user identity to attribute an action to yet.';
comment on column public.ticket_draft_edits.model_body_text is 'What the agent had written when this edit was made, COPIED rather than referenced -- the column it came from is rewritten by the next drafting run.';
comment on column public.ticket_draft_edits.source is 'Where the edit was made: dashboard (the only writer today) or mailbox (editing a review copy in Outlook, the intended second source). Declared now so adding it is not a constraint change on a populated table.';
comment on column public.ticket_drafts.approved_body_html is 'The reviewer''s rewrite as the reply HTML the editor produced (bold, italics, underline, lists, links), sanitised by scripts/lib/reply-html.mjs. approved_body_text holds its plain text, which is what the edit log and every reader compare. Null when the rewrite was plain text or there is none.';
comment on column public.ticket_drafts.approved_body_text is 'What a human decided to send instead. Null while a draft is untouched or was approved as written; required when status is edited.';
comment on column public.ticket_drafts.auto_send_blockers is 'Why this draft may not send itself, as [{ reason, detail }]: health_topic (the customer names a health condition; detail lists the words), situation (a never_auto_send situation; detail lists the keys), cosmetovigilance, needs_human, level, unhappy, checks_failed. Empty exactly when auto_send_eligible is true.';
comment on column public.ticket_drafts.auto_send_eligible is 'Whether the level gate would have auto-sent this had DRAFT_ONLY been off. Recorded from the start while nothing auto-sends, because how often L1/L2 would have been right is the question graduating auto-send turns on, and it cannot be answered retrospectively.';
comment on column public.ticket_drafts.body_text is 'What the MODEL wrote, never edited in place. A human''s rewrite goes to approved_body_text, so the distance between the two stays readable as the drafting quality measure.';
comment on column public.ticket_drafts.case_version is 'The case_current.version this reply was written against; with the ticket, the key. Null only on rows written before stage 6. A fold that raises the version marks every pending, approved or edited draft of an older one stale.';
comment on column public.ticket_drafts.checks is 'One entry per mechanical post-check run against the body: the prohibitions in the case file''s do_not_claim, identifiers the tool layer withheld, the reply language, the signature. Recorded rather than trusted, because a prohibition that lives only in a prompt is the weakest guardrail in this codebase.';
comment on column public.ticket_drafts.disposition is 'Whether sending this ends the thread. terminal = nothing expected back and nothing left to do, so the send is what closes the ticket; intermediary = the customer owes us an answer or a colleague owes them one, so sending moves the ticket to whoever is waited on and closes nothing. Derived in code from the verdict and the case file handoff -- never chosen by the model.';
comment on column public.ticket_drafts.investigation_id is 'The case file this was written from. Not nullable: the verdict decides what kind of reply this is, and the established claims are the only facts the model may use.';
comment on column public.ticket_drafts.prompt_inputs is 'What went into the prompt: the knowledge chunks that cleared the answerable band, the matched exemplar, whether an order bundle was rendered. Makes "why did it say that" answerable without re-running the pass.';
comment on column public.ticket_drafts.purpose is 'reply: an answer to the customer''s latest message. refund_notice: a message of our own telling them a refund was recorded (support_answers.notify_on). A notice is never auto-sent, and only a message of ours written after it counts as already answered.';
comment on column public.ticket_drafts.review_sent_at is 'When a review copy was mailed to the reviewer''s own inbox. The review channel never addresses the customer and is disjoint from the support mailbox; this column is what stops one draft being mailed twice.';
comment on column public.ticket_drafts.source_verdict is 'The case file''s verdict as it stood when this was drafted: answerable (a reply) or needs_customer_input (the question). needs_human is excluded by check constraint -- that verdict produces no customer-facing text at all.';
comment on column public.ticket_drafts.stale_reason is 'Why the draft went stale: case_changed (the case moved on) or superseded_by_outbound (we replied ourselves; no guess about whether it was this text). Present exactly when status is stale. A stale draft is never approved; the next version gets its own row.';
comment on column public.ticket_drafts.status is 'The human decision: pending | approved | edited | rejected | sent, plus stale (set by the fold when the case moved on; see stale_reason). Independent of checks_passed, which is a machine outcome. `sent` is written only once the outbound worker has read the reply back from Sent Items (outbound_actions.sent_confirmed); this table still cannot address a customer.';
comment on column public.ticket_drafts.trigger_event_id is 'The event that produced case_version: the newest message when the case was folded. The trigger message itself, or a partner''s answer or our Outlook reply when the case moved without the customer.';
comment on column public.ticket_drafts.trigger_message_id is 'The customer message this draft answers. No longer the key since stage 6: two case versions can answer the same message (Deret answered, nothing new from the customer).';
comment on column public.ticket_forwards.attempts is 'How many times this message has been attempted. Retry stops at the cap in agent/src/routing/forwarding-store.mjs, so a permanently undeliverable address fails a bounded number of times and then stays visible instead of being re-sent on every poll.';
comment on column public.ticket_forwards.category is 'The category as it was when the forward was sent. Snapshot: editing the address book later must not rewrite history.';
comment on column public.ticket_forwards.destination_label is 'The destination this forward went to, as named when it was sent. Null on rows written before destinations existed.';
comment on column public.ticket_forwards.status is 'sent | failed. `sent` is final and excludes the message from future passes; `failed` is retried until attempts hits the cap. Recording upserts on ticket_message_id, so a retry updates this row rather than colliding with its unique constraint.';
comment on column public.ticket_forwards.ticket_message_id is 'THE IDEMPOTENCY KEY. Per message rather than per ticket, so a follow-up on an already-forwarded thread still reaches the recipient exactly once.';
comment on column public.ticket_investigations.company_policies is 'The company policies this case read: [{ key, version, source }], source situation (linked to the matched situation), rule (linked to the selected rule) or agent (fetched by the model with getPolicy). Drafting reads each policy''s current text by key; the version says which text the investigation saw.';
comment on column public.ticket_investigations.context_ref is 'Pointer to tickets.resolved_context (order name, customer id, whether a bundle exists) rather than a copy of it -- so personal data is not duplicated per investigation, and a rebuilt bundle is not shadowed by a stale copy.';
comment on column public.ticket_investigations.customer_id is 'Denormalised link to the customer, and the seam for future per-customer memory: prior case files for this customer are a query on this column.';
comment on column public.ticket_investigations.do_not_claim is 'Derived prohibitions for the drafting stage, generated in code from the caveats the tools raised and from the missing fields. Never model-authored.';
comment on column public.ticket_investigations.established is 'Facts, each with the tool-call ids it rests on. A claim citing a call absent from tool_calls never reaches this column -- it is moved to dropped_claims.';
comment on column public.ticket_investigations.evidence_gaps is 'One entry per fact answering this ticket required, each satisfied / attempted / unavailable / not_attempted. DIAGNOSTIC: it does not move the verdict. The requirements are declared per ticket from a closed vocabulary (agent evidence-rules.mjs) and scored in code against tool_calls, so "there was nothing to find" can be told from "the agent never looked" -- not_attempted is the latter. other_fact is the escape hatch for a requirement the vocabulary cannot name and can never be satisfied.';
comment on column public.ticket_investigations.exemplar_match is 'Which support_exemplars situation this ticket matched: { verdict, exemplar_key, closest, similarity, margin, runner_up, requirement_needs }. REPORTED, NEVER ACTED ON -- nothing in the investigation reads it and the model is never told, so requirement_needs can be compared against the run''s own evidence_gaps as an independent measure. exemplar_key is the committed match and is null unless the verdict is matched; closest is the nearest situation whatever the verdict, which on a near miss is the diagnostic worth having. verdict is matched / near / weak / none / ambiguous, where ambiguous means two situations were closer together than the margin can separate. Empty when retrieval found nothing or failed -- it is best-effort and never fails a run.';
comment on column public.ticket_investigations.findings_trace is 'The derived findings after each tool call, in call order: one entry per tool_calls entry, each { call, tool, findings }. THE REPLAY TAPE. tool_calls drops every tool''s data on purpose, and 8 of the finding derivations read it -- buyer_type, product_identity, promotion_validity, promotion_eligibility, customer_account_state, product_availability, photo_evidence, checkout_state -- so a replay over tool_calls alone would score those as absent, fire fewer rules and stop earlier, flattering rule-guided collection exactly where it is most likely to under-collect. Findings are a closed enum carrying no personal data, which is why they are safe to keep where data was correctly dropped. NULL means the row predates this column and can never be filled, since the data it derives from is gone; [] means the run made no tool calls.';
comment on column public.ticket_investigations.handoff is 'Internal instruction for a human when the verdict is needs_human. Excluded from every customer-facing rendering of this row.';
comment on column public.ticket_investigations.reaction_report is 'COSMETOVIGILANCE ONLY, and null everywhere else including on a reaction ticket where the tool never ran. What the customer BLAMES and the symptoms they describe: product is the catalogue title their words resolved to, claimed is the words themselves, outcome is identified / ambiguous / not_in_catalogue / not_attributed. Attribution, never causation -- the case file carries reaction_cause_unestablished for exactly that reason. Held here rather than in tool_calls because that column drops every tool''s data, which would lose the product and the symptoms at the end of the run.';
comment on column public.ticket_investigations.recommendations is 'What recommendProducts put forward, as it rendered it: one entry per type of care, with the product lines a reply quotes. Written by code from the tool ledger, never by the model — see agent/src/investigation/investigate.mjs run.recommendations().';
comment on column public.ticket_investigations.trigger_message_id is 'THE IDEMPOTENCY KEY. The inbound message that put the ticket into the investigation queue. Per message rather than per ticket, so a reply produces a new reading instead of overwriting the previous one.';
comment on column public.ticket_investigations.unverified is 'What the customer asserted, or what no available tool could settle. Kept apart from established because a doubt merged into a list of facts is read as a fact.';
comment on column public.ticket_messages.attachments is 'Attachment METADATA only, one object per part: name, contentType, size, isInline. Never the bytes. NULL means never fetched; [] means fetched and empty.';
comment on column public.ticket_messages.body_text is 'Cleaned plain-text email body used for triage, categorisation, and drafting. Minimise personal data and keep it out of AI prompts unless strictly required for the task.';
comment on column public.ticket_messages.direction is 'inbound (from the customer/third party) or outbound (agent reply or team forward sent from the support mailbox).';
comment on column public.ticket_messages.embedded_input_hash is 'Hash of the embedded input (body text + relevant metadata) so a reconciler can detect stale vectors and re-embed on model or content changes, mirroring knowledge_chunks determinism metadata.';
comment on column public.ticket_messages.embedding is 'pgvector(1536) embedding of the email body (text-embedding-3-small) for similar-ticket retrieval and clustering, populated primarily for inbound messages. Matches the knowledge_chunks embedding pipeline; a row holds a vector iff embedded_input_hash/model/dimensions match the current input and model.';
comment on column public.ticket_messages.from_email is 'Raw sender email. Required to reply to the requester; do not include in AI prompts unless strictly required.';
comment on column public.ticket_messages.graph_message_id is 'Microsoft Graph message id. The idempotency key: re-ingesting the same email is a no-op via the shop_id + graph_message_id unique constraint.';
comment on column public.ticket_messages.internet_message_id is 'RFC 5322 Message-ID header, stable across mail systems. Useful for threading and correlating replies independently of Graph ids.';
comment on column public.ticket_messages.raw_graph_payload is 'Sanitised raw Microsoft Graph message payload for traceability. Exclude attachment binaries and unnecessary personal data.';
comment on column public.ticket_routing.ack_state is 'requested (written before sending; never retried) | sent | failed (retried up to the cap) | skipped (automated or internal sender, or acknowledgements off). Null until the first forward.';
comment on column public.ticket_snoozes.waiting_for is 'customer | colleague | partner (an operations partner: 3PL or carrier) | date (a person chose a time).';
comment on column public.ticket_snoozes.wake_at is 'The fallback deadline. The worker wakes the ticket then (wake_reason deadline) without calling a model.';
comment on column public.ticket_snoozes.wake_reason is 'Why it came back: a new message by actor, the deadline, a person, the case moving to us (case_changed) or to nobody (resolved), or an order update.';
comment on column public.tickets.archived_at is 'When the ticket was archived out of the active queue while still retained. Set by the archival job for old tickets; distinct from deleted_at.';
comment on column public.tickets.case_id is 'The case this thread belongs to. A new conversation opens its own case; the case linker (agent/src/cases/) may move the thread into an older case of the same customer, recorded in case_links. Threads are never merged: several tickets share a case_id.';
comment on column public.tickets.case_link_state is 'pending until the case linker has decided, once, whether this thread continues an older case; decided after. Tickets that predate cases were marked decided by 61_cases.sql.';
comment on column public.tickets.categorisation_confidence is 'Marker that this ticket''s labels are known to be untrustworthy. NOT a model self-assessment: the categoriser was originally asked how sure it was and answered "high" on 171 of 171 real tickets and 40 of 40 review cases, because Structured Outputs emits fields in order, so it was rating an answer it had already committed to in the same forward pass. A constant field carries no information, so the question was dropped. Today only "low" is written, and only by the categoriser''s failure paths: a categorisation that exhausted its retries, or stale labels on a ticket whose re-categorisation errored. A successfully categorised ticket is NULL. "high" and "medium" remain permitted by the constraint but nothing writes them -- they are kept so a future calibrated signal (sampling for agreement, or token logprobs) can land here without a migration.';
comment on column public.tickets.categorised_at is 'When the current labels were written. Distinct from updated_at, which any other write also moves, so this is what tells you how stale a label is relative to last_message_at.';
comment on column public.tickets.category is 'Primary subject, from the shared support taxonomy in scripts/lib/support-taxonomy.mjs -- the same 14 subjects knowledge articles use, so a ticket subject filters straight into the matching knowledge chunks. No subject implies a handling level on its own; cosmetovigilance floors at level 2 for a reported reaction (see the level comment).';
comment on column public.tickets.closed_at is 'When the ticket was closed. Retention anchor for archival and eventual deletion.';
comment on column public.tickets.context_resolved_at is 'When resolved_context was last assembled. Lets the worker re-resolve stale context rather than trusting the snapshot as source of truth.';
comment on column public.tickets.customer_id is 'Optional link to the local customer snapshot once the requester is matched. Null for unresolved or guest requesters.';
comment on column public.tickets.deleted_at is 'Soft-delete / compliance-redaction flag. Distinct from archived_at (archival keeps the ticket; deletion removes it, e.g. on a customer redact request).';
comment on column public.tickets.fact_drift is 'The change router''s record of order states that moved since the latest case file: { changed: { state: { from, to } }, outcome (redraft | reinvestigate), reason, case_file_at, checked_at }. Null until something moves. The fold hashes it, so a drift raises the case version once.';
comment on column public.tickets.graph_conversation_id is 'Microsoft Graph conversationId. The threading key: all emails in one thread share this value and roll up to a single ticket, so tickets behave as conversations rather than individual emails.';
comment on column public.tickets.happiness is 'How the customer feels: 1 happy, 2 neutral, 3 discontent expressed, 4 really unhappy (threatening to stop buying, calling the situation unacceptable, or chasing an unanswered thread). Same direction as level, but NOT derived from it and it does not feed it: level is what WORK the ticket needs, happiness is how the customer feels about it. An angry customer with a simple tracking question is happiness 4, level 2 -- both true. Deriving one from the other would make a mood imply a severity and fill the manager queue with routine mail. Consumed by the drafting agent to set tone.';
comment on column public.tickets.investigated_at is 'When the last case file was written. Not a queue predicate -- needs_investigation is; this is for reporting and for spotting a ticket whose case file predates its latest reply.';
comment on column public.tickets.language is 'Language the reply should be written in (fr, en, es, de, it, nl, pt, other), read from the customer''s own message by the categoriser. The mailbox is mostly French but not exclusively, and the drafting agent needs this before it writes a word. ''other'' means the desk cannot answer natively -- route to a human rather than guessing.';
comment on column public.tickets.level is 'Handling level 1-4, derived from (category, request_kind) by defaultLevel() in scripts/lib/support-taxonomy.mjs: 1 answerable from general knowledge, 2 needs the customer''s own record consulted and answered (no change), 3 needs something changed (refund, resend, cancellation, address change, commercial gesture). Subjects whose answers live in the database (order, delivery, payment, account, product_stock, promotions) floor at 2 for BOTH questions and problems, because most problems there are resolved by looking something up; the categoriser escalates to 3 itself when the fix requires a change. Level 4 is a SEVERITY judgement and is NOT derived from any subject -- reserved for an explicit threat of legal action or public exposure, hospitalisation, or grave injury/danger, so it can only arrive as a categoriser escalation and should be rare. The categoriser may escalate above the derived floor but never below it, and a re-categorisation may raise a stored level but never lower it (ratchetLevel).';
comment on column public.tickets.needs_categorisation is 'True when the ticket is waiting for the categoriser. Set on insert (default) and set again by ingestion whenever a new INBOUND message joins the thread, because a reply can change the subject, the kind and above all the level; cleared when the worker writes fresh labels. A flag rather than a categorised_at < last_message_at comparison: PostgREST cannot compare two columns, and last_message_at also advances on our own outbound replies, which must not trigger a re-run.';
comment on column public.tickets.needs_investigation is 'Pending flag for the investigation pass. Raised by the categoriser when it finishes labelling a ticket (and again on each re-categorisation), cleared by the investigation pass. Default false because an uncategorised ticket has no subject from which to choose tools.';
comment on column public.tickets.overrides is 'A person''s corrections, per field: { value, ai_value, set_by, set_at, source }. The column of an overridden field holds the person''s value; ai_value keeps the pipeline''s, and the categoriser keeps it current. Empty object when nothing is overridden.';
comment on column public.tickets.priority is 'Queue priority 1 (highest) to 5 (lowest), set by the prioritiser from RFM group, level, and age. Defaults to 3 (normal) so the queue sorts before prioritisation runs.';
comment on column public.tickets.related_detected_at is 'When the related link was written. Separate from the ticket clock because a link can be made long after both tickets were created.';
comment on column public.tickets.related_score is 'The cosine that produced related_ticket_id, kept so a link made under one threshold stays interpretable after the threshold moves.';
comment on column public.tickets.related_ticket_id is 'An earlier ticket from the SAME consumer sender that this one continues -- a chase, or a thread split across conversation ids. Set from a message-embedding cosine at or above 0.90 within 30 days, and never for a sender listed in sender_directory (a retailer''s repeated purchase-order template outscores every genuine consumer match). UNLIKE duplicate_of_ticket_id THIS NEVER SUPPRESSES A DRAFT: it adds thread context for the reviewer and tells the drafting agent the customer was left waiting, so the reply opens with an apology.';
comment on column public.tickets.request_kind is 'What the sender wants about the primary subject: question (answerable from knowledge), problem (needs an action), complaint (dissatisfaction, never auto-handled), contact (inbound B2B/partnership/careers, forwarded to a team). Kept separate from category so knowledge retrieval can filter on subject alone.';
comment on column public.tickets.requester_email_hash is 'Hash of the requester email, for matching against orders.customer_email_hash and deduping by sender without storing the raw address on the ticket. The raw reply address lives on the latest inbound ticket_messages row.';
comment on column public.tickets.requester_name is 'Display name of the requester for the dashboard queue. Do not include in AI prompts unless strictly required.';
comment on column public.tickets.resolved_at is 'When the ticket moved to resolved. Retention anchor for how long resolved tickets are kept.';
comment on column public.tickets.resolved_context is 'Order/customer context bundle the order-context resolver assembles from the synced orders/customers rows once shopify_order_number is set (tracking, order name, order-customer name, RFM group, etc.), handed to the drafting agent so it does not query fields individually. A re-resolvable snapshot, not a source of truth and not a duplicate of first-class order columns; may be edited for human-in-the-loop review. Holds personal data, so it must be scoped, kept out of prompts unless strictly required, and redacted on compliance requests. Excludes billing/street address (never synced; gated live Shopify lookup only).';
comment on column public.tickets.responsible_team is 'Team a forwarded ticket belongs to: finance, marketing, sales, logistics, or contact. The worker forwards B2B/invoice/marketing-type mail to the implicated person and tags the ticket here.';
comment on column public.tickets.retention_delete_after is 'Timestamp after which the ticket may be hard-deleted by the retention cleanup job. Durations are policy-driven and set later; the column is the mechanism, not a fixed rule.';
comment on column public.tickets.secondary_category is 'Optional second subject when one email spans two topics (an order problem plus a stock question). Same vocabulary as category.';
comment on column public.tickets.secondary_request_kind is 'Kind for secondary_category, since a second subject can be a different kind (an order problem plus a stock question). Null unless secondary_category is set.';
comment on column public.tickets.sender_label is 'The sender_directory label of the address that OPENED this thread, when that address is one of ours -- internal (qiriness.com, lap-groupe.com) or contractor. Null means a consumer, the ordinary case. Set deterministically at ticket creation from the address, never by a model: who wrote to us is a fact we hold before any pass runs. The drafting queue skips a labelled ticket, because a customer-voice reply addressed to a colleague is never the right output; investigation still runs, because a colleague chasing a real order still needs the order facts gathered for whoever picks it up.';
comment on column public.tickets.shopify_order_number is 'Shopify order number resolved for this ticket (the workflow''s source-of-truth lookup key). Stored as text to preserve the customer-facing #XXXX form; matched against orders.name / orders.order_number by the order-lookup tool.';
comment on column public.tickets.status is 'Ticket lifecycle: open, awaiting_customer, awaiting_human, forwarded, resolved, closed, or spam. In draft-only mode nothing is auto-sent, so agent-drafted replies sit at awaiting_human until approved.';
comment on function chat.vip_customer_rows() is 'The shop''s VIP customers, through public.vip_customers() with the shop''s own thresholds and marketplaces excluded. Security definer, no arguments. Read it through chat.vip_customers.';
comment on function public.claim_mail_jobs(p_shop_id uuid, p_kinds text[], p_limit integer, p_lease_seconds integer) is 'Take up to p_limit due jobs of the given kinds: queued and due, or running with an expired lease (counted as a failed attempt). Marks them running with a lease of p_lease_seconds.';
comment on function public.customer_segment_find(p_shop uuid, p_window_months integer, p_groups jsonb, p_not_channels text[], p_limit integer) is 'Segment Finder: customers matching OR-of-AND groups of {metric: orders | spend | lifetime_spend, op: gt | lt, value} conditions, with orders and spend counted over the last p_window_months and lifetime over all uncancelled Shopify orders (net of refunds). Every customer on file except marketplace-synthetic ones. Always one totals row; up to p_limit members by lifetime spend.';
comment on function public.customer_vip_call_list(p_shop uuid, p_min_spend numeric, p_min_orders integer, p_window_months integer, p_not_channels text[], p_closed_statuses text[], p_min_level integer) is 'Cases of VIP customers that are open and at or above p_min_level: the panel''s call list. Filtered in SQL, so it is bounded by what needs a call, not by all cases.';
comment on function public.customer_vip_ticket_categories(p_shop uuid, p_min_spend numeric, p_min_orders integer, p_window_months integer, p_not_channels text[]) is 'VIP cases by subject (null category = uncategorised). Ordering is left to the caller.';
comment on function public.customer_vip_ticket_stats(p_shop uuid, p_min_spend numeric, p_min_orders integer, p_window_months integer, p_not_channels text[], p_closed_statuses text[], p_unhappy_from integer) is 'The Customers panel''s ticket figures, aggregated: cases linked to a customer, cases of VIPs (vip_customers()), distinct VIPs who wrote in, and lifetime spend behind open unhappy cases (once per customer).';
comment on function public.enqueue_mail_job(p_shop_id uuid, p_kind text, p_dedupe_key text, p_payload jsonb, p_run_at timestamp with time zone) is 'Queue one mail job, or bring an already-queued job with the same dedupe_key forward. Returns the queued row.';
comment on function public.insights_agent_blockers(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text) is 'investigation_evidence_gaps over the runs made in a date range. Satisfied needs are included, as in the view; the caller filters them.';
comment on function public.insights_agent_funnel(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text) is 'agent_pipeline_funnel over the tickets first written in a date range. Always one row.';
comment on function public.insights_agent_situations(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text) is 'How each ticket investigated in a date range got its situation (latest run per ticket): matched, tie settled by rules, near miss chosen by the model, chooser said none, not settled, no match, not recorded. Always one row.';
comment on function public.insights_agent_verdicts(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text) is 'Investigations by verdict for the runs made in a date range.';
comment on function public.insights_capture_series(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_grain text, p_checkout_minutes integer, p_channels text[], p_not_channels text[]) is 'First-time buyers per wall-clock bucket, with how many were on the newsletter before that first order and how many joined at checkout (within p_checkout_minutes). Current consent state, so a floor. Callers exclude marketplace channels.';
comment on function public.insights_collection_sales(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_channels text[], p_not_channels text[], p_limit integer, p_handles text[]) is 'Per collection for a date range: distinct orders, units and net line revenue, on insights_product_sales line rules, plus one null-id row for paid lines in no reported collection. p_handles limits it to the ranges the business reads by. Collections overlap — a product counts in each of its collections — so the rows never sum to the range.';
comment on function public.insights_country_product_sales(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_metric text, p_limit integer, p_vip_only boolean, p_min_spend numeric, p_min_orders integer, p_window_months integer, p_vip_not_channels text[], p_channels text[], p_not_channels text[]) is 'Top p_limit products per destination country for a date range, ranked by revenue or orders, with each country''s own order count and net revenue. Zero-value lines excluded, as in insights_product_sales, and so is p_vip_only.';
comment on function public.insights_customer_mix(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_channels text[], p_not_channels text[]) is 'Customers who ordered in a range, split by whether their earliest synced order is inside it (new) or before it (returning), with their order counts. Never call it over marketplace channels: those mint one customer per order.';
comment on function public.insights_freshness(p_shop uuid) is 'One row: when each source feeding the dashboard last moved -- orders, customers, mail, the topic map, the agent -- and the latest nightly sync run. orders/customers_synced_at are the later of the newest row change and the last completed nightly (92: unchanged rows are no longer rewritten). The panels read it to say how old their figures are.';
comment on function public.insights_fulfilment_buckets(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_channels text[], p_not_channels text[]) is 'The dispatch-time histogram for a date range: the six duration buckets of fulfilment_by_bucket, plus "Not shipped yet" (bucket_order 7) for orders placed in the range that are still waiting, counted exactly as open_orders() counts them. Empty buckets are absent; the caller draws all seven.';
comment on function public.insights_fulfilment_carriers(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_channels text[], p_not_channels text[]) is 'Shipments, dispatch timing and support contact per normalised carrier for a date range. orders_with_ticket counts orders, not threads -- see fulfilment_by_carrier.';
comment on function public.insights_inventory_exceptions(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_max_cover_days numeric, p_max_stock_units integer) is 'Active products out of stock, with at most p_max_cover_days of cover at the rate units (free lines included, all channels) left over [p_from, p_to), or with fewer than p_max_stock_units in stock. Stock is products.available_stock as of the last product sync.';
comment on function public.insights_klaviyo_messages(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text) is 'Klaviyo flows (summed over their days) and campaigns (by send time) in a range: counts only, rates are computed by the reader.';
comment on function public.insights_llm_series(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_grain text) is 'Token counts per wall-clock bucket and model -- per model because each is priced at its own rate. Non-empty buckets only.';
comment on function public.insights_llm_ticket_stats(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text) is 'How many tickets the agent spent tokens on in a date range, and the mean and worst per-ticket token totals.';
comment on function public.insights_llm_usage(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text) is 'Token counts per model and pass for a date range. Tokens only -- money is applied at read time from llm-rates.mjs.';
comment on function public.insights_marketing_series(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_grain text) is 'Newsletter subscribes and unsubscribes per wall-clock bucket, read off the current consent state and its last-change time. Floors: one timestamp per customer, so an earlier change is overwritten by a later one.';
comment on function public.insights_marketing_summary(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text) is 'Newsletter subscribes and unsubscribes in a date range, the list size at its start reconstructed from the consent snapshot (an estimate), the list size now, and both edges of what the snapshot covers: the newest consent change and the earliest recorded unsubscribe.';
comment on function public.insights_orders_by_channel(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text) is 'Orders and net revenue per sales channel handle for a date range, cancelled orders excluded. Handles are folded into platforms (Shopify / Amazon / Yves Rocher) in TypeScript.';
comment on function public.insights_orders_by_country(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_channels text[], p_not_channels text[]) is 'Orders and net revenue per destination country for a date range, cancelled orders excluded.';
comment on function public.insights_orders_per_customer(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_channels text[], p_not_channels text[]) is 'How many customers placed 1, 2, 3… orders inside a date range. One row per order count. Callers exclude marketplace channels: those mint a customer per order.';
comment on function public.insights_orders_series(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_grain text, p_channels text[], p_not_channels text[]) is 'Orders, net revenue and dispatch timing per wall-clock bucket (hour/day/week/month in the shop timezone). Non-empty buckets only; the caller fills the rest and decides which empty ones are zero.';
comment on function public.insights_orders_summary(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_channels text[], p_not_channels text[]) is 'One row for a date range: orders, net revenue (cancelled excluded, refunds subtracted), dispatch timing and what came back. The ranged twin of fulfilment_summary. Always one row -- an empty range is counts of 0 and null percentiles, never no row.';
comment on function public.insights_paid_campaigns(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_limit integer) is 'Campaigns of enabled ad accounts with delivery in a range, summed per campaign and currency, biggest spend first, capped at p_limit.';
comment on function public.insights_paid_series(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_grain text) is 'Paid media per enabled ad account, currency, publisher and bucket over a range. Never summed across currencies here.';
comment on function public.insights_product_customer_mix(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_product_id text, p_country text, p_vip_only boolean, p_min_spend numeric, p_min_orders integer, p_window_months integer, p_vip_not_channels text[], p_channels text[], p_not_channels text[]) is 'For one product over a date range: distinct Shopify customers who bought only that paid product, bought it with other paid products, or did not buy it (the three sum to customers), plus the top 7 other paid products its buyers bought, by distinct customer. Optional filters narrow the whole population: delivery country, and VIP only under vip_customers(). Zero-value lines are ignored; the caller excludes marketplace channels.';
comment on function public.insights_product_orders_per_customer(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_product_id text, p_country text, p_vip_only boolean, p_min_spend numeric, p_min_orders integer, p_window_months integer, p_vip_not_channels text[], p_channels text[], p_not_channels text[]) is 'For one product over a date range: how many distinct Shopify customers placed 1, 2, 3... orders carrying a PAID line of it. One row per order count, buyers only (never-bought is the customer mix''s third bucket). Takes the same country and VIP-only filters as insights_product_customer_mix, so both describe the same group; the caller excludes marketplace channels.';
comment on function public.insights_product_pairs(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_limit integer, p_channels text[], p_not_channels text[]) is 'The product pairs most often bought in the same order for a date range, globally (null country) and per destination country, each ranked by orders and by revenue and cut to p_limit. Free lines excluded.';
comment on function public.insights_product_sales(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_vip_only boolean, p_min_spend numeric, p_min_orders integer, p_window_months integer, p_vip_not_channels text[], p_channels text[], p_not_channels text[]) is 'Per product for a date range: distinct orders, units and net line revenue, with catalogue tags. Zero-value lines (samples, gifts) are excluded. One row per product, so bounded by the catalogue. p_vip_only limits it to customers vip_customers() admits.';
comment on function public.insights_promotions(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_channels text[], p_not_channels text[], p_people_not_channels text[], p_limit integer) is 'Per promotion applied in a date range (by the name on orders.discount_applications): orders, their net revenue, what it took off the lines, and orders that were a first purchase. Plus one null-named row for orders with no promotion. An order with two promotions is in both rows.';
comment on function public.insights_sales_overview(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_channels text[], p_not_channels text[]) is 'One row for a date range: paid (uncancelled) orders, paid units, total_discounts (gifts and free shipping included), and net revenue split between orders that carried a discount and orders that did not. Same filters and revenue rule as insights_orders_summary.';
comment on function public.insights_social_audience(p_shop uuid) is 'The newest follower-demographics snapshot of each enabled account.';
comment on function public.insights_social_followers(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone) is 'Each organic account''s follower count on the last measured day inside the range and the last measured day before it.';
comment on function public.insights_social_post_totals(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text) is 'Per account, every post published in a range: count, views, engagement, and the numerator and denominator of each engagement rate (by reach, by views; by followers needs only engaged_posts).';
comment on function public.insights_social_posts(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_limit integer) is 'Posts published in a range with their lifetime counts, most viewed first, capped at p_limit.';
comment on function public.insights_social_series(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_grain text) is 'Organic counts per enabled account and bucket over a range. Null sums are not measured, never zero.';
comment on function public.insights_support_categories(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text) is 'Case volume, mood and purchase state per subject (the case''s earliest thread) for a date range, on first_message_at. Fourteen rows at most.';
comment on function public.insights_support_series(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_grain text) is 'Cases (case_facts; the column keeps the name tickets), unhappy cases and median first reply per wall-clock bucket, on the case''s first_message_at. Non-empty buckets only.';
comment on function public.insights_support_summary(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text) is 'One row for a date range, on first_message_at: CASE volume and mood (case_facts: several threads of one customer problem count once; the output columns keep the name tickets), first-reply timing over the cases that can be timed, and who wrote in by whether an online purchase is visible (tickets, then distinct people and their reachability).';
comment on function public.insights_tiktok_post_series(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_grain text) is 'TikTok lifetime views / interactions of the videos published in each bucket, plus follower-snapshot differences. Not daily account activity: TikTok supplies none.';
comment on function public.klaviyo_clear_key(p_shop uuid) is 'Deletes the shop''s Klaviyo key from Vault and the connection row. Synced figures are kept.';
comment on function public.klaviyo_read_key(p_shop uuid) is 'The shop''s decrypted Klaviyo private key, for the sync. Service role only; never returned to a browser.';
comment on function public.klaviyo_save_key(p_shop uuid, p_key text, p_hint text, p_metric_id text, p_saved_by uuid) is 'Stores (or replaces) the shop''s Klaviyo private key in Vault and records the connection. Service role only.';
comment on function public.match_support_exemplars(query_embedding public.vector, match_shop_id uuid, match_categories text[], match_count integer, min_similarity double precision) is 'Vector search over approved exemplar phrasings, returning one row per EXEMPLAR scored by its best-matching phrasing. Returns cosine SIMILARITY (higher is better), not the raw <=> distance. `match_categories` is a caller-supplied list because which subjects are worth searching is policy -- see agent/src/retrieval/exemplar-rules.mjs. Bands are NOT the knowledge bands: a short canonical question scores differently against a long email than a prose chunk does, and they are calibrated separately.';
comment on function public.normalise_carrier(value text) is 'Free-text carrier name from a fulfilment record -> one canonical name, by the rows of public.carrier_aliases (first match by position; otherwise upper-cased). Without it one carrier stored three ways reports as three.';
comment on function public.open_orders(p_shop uuid, p_min_spend numeric, p_min_orders integer, p_window_months integer, p_vip_not_channels text[], p_channels text[], p_not_channels text[]) is 'Orders not yet fulfilled (not cancelled, not closed), oldest first, with the buyer''s name and email and whether they are a VIP under vip_customers(). Current state as of the last order sync, not ranged.';
comment on function public.order_fulfilment_display(p_fulfillment_status text, p_line_items jsonb, p_cancelled_at timestamp with time zone, p_financial_status text) is 'The Orders page fulfilment status: Shopify''s, or CANCELLED / REFUNDED for an order not fulfilled or restocked with 0 items left. UNKNOWN when Shopify gave none. The rule fulfillmentDisplay() in scripts/lib/order-list-query.mjs labels the pill with.';
comment on function public.order_lines_refresh() is 'AFTER trigger on orders: rewrites the order''s rows in order_lines from line_items. On update it fires only when line_items changed.';
comment on function public.order_number_range(match_shop_id uuid) is 'Lowest and highest order_number this shop has issued, as one row. Replaces a pair of asc/desc limit-1 reads from agent/src/resolution/order-resolution-runner.mjs. Both values are null on a shop with no synced orders, which the caller reads as "we cannot judge whether a quoted number is ours" rather than as a range of zero.';
comment on function public.orders_in_range(p_shop uuid, p_from timestamp without time zone, p_to timestamp without time zone, p_tz text, p_channels text[], p_not_channels text[]) is 'The live, uncancelled orders of one shop placed in [p_from, p_to) as wall-clock time in p_tz, on p_channels and not on p_not_channels (a null channel is never excluded). The range condition the insights_* functions share; inlined into each caller.';
comment on function public.orders_list(p_shop uuid, p_min_spend numeric, p_min_orders integer, p_window_months integer, p_vip_not_channels text[], p_fulfillment_status text, p_country text, p_vip_only boolean, p_search text, p_order_ids uuid[], p_limit integer, p_offset integer) is 'The Orders page: every live order, newest first, one page at a time, with the buyer''s name, VIP under vip_customers(), units, normalised carrier and destination. total_count is the filtered set before the page is cut. awaiting_fulfilment is open_orders()''s waiting rule. Filters: fulfilment status as order_fulfilment_display() derives it, destination country, VIP only, order ids, and a search over order name, buyer name, buyer email and tracking number.';
comment on function public.orders_list_facets(p_shop uuid) is 'Filter options for the Orders page: each fulfilment status (as order_fulfilment_display() derives it) and destination country among live orders, with its order count. Grouped on the same expressions orders_list() filters on.';
comment on function public.skip_unchanged_sync_write() is 'BEFORE UPDATE trigger: skips an update that would change nothing but synced_at, updated_at and the columns named as trigger arguments, so a full re-sync rewrites only rows that changed and updated_at keeps meaning "changed".';
comment on function public.social_clear_token(p_shop uuid, p_provider text) is 'Deletes a provider''s token from Vault and its connection row. Accounts and synced figures are kept.';
comment on function public.social_read_token(p_shop uuid, p_provider text) is 'The shop''s decrypted token for one provider, for the sync. Service role only; never returned to a browser.';
comment on function public.social_refresh_token(p_shop uuid, p_provider text, p_token text, p_expires_at timestamp with time zone) is 'Rotates a shop OAuth bundle in Vault without changing the connecting user or connection date. Service role only.';
comment on function public.social_save_token(p_shop uuid, p_provider text, p_token text, p_expires_at timestamp with time zone, p_scopes text[], p_connected_by uuid) is 'Stores (or replaces) a provider''s OAuth token for the shop in Vault and records the connection. Service role only.';
comment on function public.vip_customers(p_shop uuid, p_min_spend numeric, p_min_orders integer, p_window_months integer, p_not_channels text[], p_customer_ids uuid[]) is 'THE VIP RULE: customers whose net spend AND order count inside the last p_window_months are both strictly greater than the minimums, uncancelled orders only, marketplace channels excluded. With their windowed orders and spend. Pass p_customer_ids to ask about specific customers.';
comment on function public.vip_summary(p_shop uuid, p_min_spend numeric, p_min_orders integer, p_window_months integer, p_not_channels text[]) is 'How many customers vip_customers() admits, and how many ordered at all in the same window.';
comment on function public.vip_tickets(p_shop uuid, p_min_spend numeric, p_min_orders integer, p_window_months integer, p_not_channels text[], p_ticket_ids uuid[]) is 'Live tickets whose linked customer is a VIP under vip_customers(). One call marks a whole queue.';
comment on schema chat is 'Read-only views for the management chat (/home). Readable by mgmt_chat_ro only. No personal data.';
comment on view chat.customers is 'One row per Shopify customer, as they are NOW (a snapshot, not a history: past states cannot be reconstructed). Marketplace orders (the handles listed in your instructions) create one synthetic customer per order, so exclude customers whose orders are all on those channels from any per-person metric.';
comment on view chat.fulfilment_timing is 'Per order: how long from placing the order to its first shipment. This is FULFILMENT time. Delivery time is not measurable: no carrier delivery data exists.';
comment on view chat.llm_usage is 'One row per AI model call by the support agent (spam, categorise, decompose, investigate, draft, embed). Tokens only: no prices are stored, so cost cannot be computed here. cached_input_tokens is part of input_tokens, never add them.';
comment on view chat.order_lines is 'One row per line item of an order: what was sold. product_title is the title at the time of sale. Join products on shopify_product_id.';
comment on view chat.orders is 'One row per Shopify order (all sales channels). Money is in currency_code (EUR). processed_at is when the order was placed (UTC). Join customers on customer_id, order_lines and fulfilment_timing on order_id, tickets on order_number (tickets.shopify_order_number is text).';
comment on view chat.products is 'The Shopify catalogue as it is now. status: active, draft, archived, unlisted. For what sold, use order_lines.';
comment on view chat.promotions is 'Shopify discounts, one row per discount. method: code or automatic. discount_usage_count is how many times it has been used. The codes themselves are not exposed.';
comment on view chat.shop is 'One row: the shop. iana_timezone is where a day starts for reporting. The VIP rule is net spend above vip_min_spend AND more than vip_min_orders orders inside the last vip_window_months (all null = no VIP rule set). The customers it admits are listed in chat.vip_customers.';
comment on view chat.ticket_drafts is 'Replies the AI agent drafted. Nothing is sent automatically. status is the human review decision (pending, approved, edited, rejected); was_rewritten is true when a reviewer changed the text; auto_send_eligible is whether it WOULD have qualified for auto-send.';
comment on view chat.ticket_investigations is 'The AI agent''s investigation of a ticket, one per inbound message investigated. verdict: answerable (the agent could answer), needs_customer_input, needs_human.';
comment on view chat.ticket_message_counts is 'Messages per ticket: total, and how many came from the customer (inbound).';
comment on view chat.ticket_reply_times is 'First-response time per ticket: first customer message to the first reply after it. reply_hours is null when the desk has not replied from the synced mailbox.';
comment on view chat.tickets is 'One row per customer-support email thread. Coverage starts when the mailbox sync began: use min(first_message_at) as the start of the data and never report a period before it. Join orders on shopify_order_number = orders.order_name or the order number as text.';
comment on view chat.vip_customers is 'One row per customer who is a VIP RIGHT NOW under the shop''s VIP rule (see chat.shop: net spend strictly above vip_min_spend AND strictly more than vip_min_orders orders, both inside the last vip_window_months; uncancelled orders; marketplace orders do not count). Empty when no rule is set. Join chat.customers on customer_id for country, lifetime spend or RFM group, and chat.orders / chat.tickets on customer_id. Current status only: who was a VIP in the past cannot be reconstructed.';
comment on table public.ad_campaign_days is 'Paid media per ad account, campaign and day, in the account''s currency. Conversions are the platform''s own attribution. The last 28 days are rewritten each sync, like ad_days.';
comment on table public.ad_campaigns is 'One row per ad account and campaign (Meta Ads, Google Ads): name, status, objective or channel type, as last read by the sync.';
comment on table public.ad_days is 'Paid media per ad account, day (the ad account''s clock) and publisher, in the account''s currency. Conversions and their value are the platform''s own attribution. The last 28 days are rewritten each sync, because attribution settles late.';
comment on table public.advice_collections is 'Shopify collections as a curation surface for product advice: every collection the shop has, plus whether support may answer from it, which axis it is, and the products it holds. Membership is refreshed for active collections only.';
comment on table public.advisor_knowledge is 'The storefront advisor''s product knowledge and assembled routines, one version per npm run advisor:load; one active per shop. Products by handle. Read by the storefront advisor only.';
comment on table public.advisor_mappings is 'How playbooks resolve against the catalogue without product ids: families, slots, concerns, skin types, textures, areas -> collections, tags, care types, name words; plus chip labels. One row per entry; key _ for a whole section.';
comment on table public.advisor_merchandising is 'The brand''s priority products for advice, by product handle, collection or family, optionally per concern/slot and dates. Applied after suitability, within a tie window: reorders suitable products, never makes an unsuitable one recommended.';
comment on table public.advisor_playbooks is 'The brand''s advisory routine playbooks, as authored (data/advisor/<brand>.json via npm run advisor:load). Read by the storefront advisor only. Products are never named by id here.';
comment on table public.advisory_events is 'Advisory analytics events, channel-aware (storefront_chat now, email reserved). Codes, counts and ids only; never the customer''s words. Purged with advisory_events_purge.';
comment on table public.agent_models is 'The model each agent runs on, when chosen in Settings. Overrides the worker''s AGENT_*_MODEL and the dashboard''s CHAT_MODEL; no row means the env var decides.';
comment on table public.agent_test_runs is 'One rehearsal of the agent pipeline against a message an operator typed, from the Agent Setup test chat. References no ticket, message, investigation or draft because a rehearsal writes none of them -- the passes run against in-memory stores, so the queue and every Insights view are untouched by a test. Nothing downstream reads these rows: they are an operator''s notebook, plus the ideal-answer capture that is the invented-situation half of ticket_draft_edits.';
comment on table public.carrier_aliases is 'How free-text carrier names from fulfilment records fold into one canonical name: the first alias (by position) whose pattern the raw name contains, case-insensitively, wins; no match keeps the name, upper-cased. Configuration per deployment: edit rows, not SQL. Read by normalise_carrier().';
comment on table public.case_current is 'The current state of each case, one row per ticket, overwritten in place like resolved_context: folded in code (agent/src/casework/case-fold.mjs) from the ticket''s messages, its Case Manager readings and its latest case file. No model writes it. ticket_case_state stays the per-message trajectory.';
comment on view public.case_facts is 'One row per case with at least one live thread: the earliest thread''s subject, the highest level and worst mood of any thread, a status folded across threads, the lead thread (the reply thread, else the most recently active thread still live, else the most recently active), and the case''s first-reply time across threads. Read by the queue and by the Insights support figures, which count cases.';
comment on table public.case_links is 'Append-only: every case-linking decision, a new case included, with the rule (method) and the candidates considered. Written only by scripts/lib/case-record.mjs.';
comment on view public.case_message_counts is 'Message counts and inbound/outbound activity per case, over every live thread in it, soft-deleted messages excluded. The case-level twin of ticket_message_counts, read by the queue''s priority.';
comment on table public.cases is 'The customer''s problem, above the email threads it arrived on: several tickets may share a case_id, nothing is merged. Created with its first ticket; linked only by agent/src/cases/ and recorded in case_links. Holds the reply target, chosen by code (case-reply-target.mjs). Written only by scripts/lib/case-record.mjs.';
comment on table public.categorisation_review is 'Human-labelled review set for the categorising agent: a random sample of real support mail, labelled by a person in the Supabase table editor, then scored against the agent. Testing artefact only -- the worker never reads it. Holds real email subjects and bodies (the minimum needed to judge a category) with the sender reduced to a domain, and a 3-month default retention.';
comment on table public.category_forwarding is 'Per-category forwarding address book: which colleague receives mail of a given subject that asks nothing of customer support. Read by the agent forwarding step, written by the Agent Setup UI. A category with no row or a null address is never forwarded.';
comment on table public.chat_conversations is 'A management chat thread (/home). Owned by one dashboard user; the title is the first question.';
comment on table public.chat_queries is 'Every SQL query the management chat ran or tried to run: the text, whether it was refused or failed and why, rows returned, whether it hit the 1,000-row cap, and time taken.';
comment on table public.chat_turns is 'One question and its answer in a management chat, with the model, step count, token usage and duration. Tokens are kept here and NOT in llm_usage, which answers what the support mailbox costs.';
comment on table public.cluster_runs is 'One row per manual rebuild of the topic map: when it was built, the threshold and minimum size used, and how much mail it saw. The panel reads the newest row to show the map''s age and to warn when the live corpus has drifted away from it.';
comment on table public.company_policies is 'The company''s policies, each written once: linked to situations and rules through company_policy_links, and fetchable by the agent through the getPolicy tool. Deterministic company truth, never a verdict. Written only by scripts/lib/company-policies.mjs.';
comment on table public.company_policy_links is 'Which policies a situation or a rule makes available to the agent: a reference, never a copy, so editing the policy changes every place it is linked. A situation''s links reach all its rules; a rule''s are added to them.';
comment on table public.company_policy_versions is 'Every version of every policy''s text, append-only, so what the agent read for a case stays answerable after the policy is edited.';
comment on view public.customer_segment_totals is 'The customer base by RFM segment, with the buyer count beside the customer count. Both denominators are here on purpose: 53,942 of 58,201 customers have never ordered, so a percentage quoted against the wrong one is meaningless.';
comment on view public.customer_ticket_facts is 'One row per CASE linked to a customer (ticket_id is its lead thread), with that customer''s segment, lifetime spend and marketing state joined on. Bounded by ticket count, so the service reads it whole and applies the VIP rule in JavaScript rather than the view asserting one.';
comment on table public.customers is 'Lean Shopify customer snapshots for support dashboards and segmentation. Access through service-role sync paths only until dashboard roles and policies are implemented.';
comment on table public.data_access_events is 'Audit trail for service-level personal-data access. Future dashboard human views must write here as user events.';
comment on table public.dropped_mail_clears is 'Blocked emails a person cleared out of the dashboard''s Irrelevant list, shop-wide. The spam_audit row is untouched; « restore » deletes these rows.';
comment on view public.dropped_mail_list is 'The Irrelevant list: blocked spam_audit rows not cleared (dropped_mail_clears) and not promoted (a ticket_messages row with the same graph_message_id), with has_body instead of the text.';
comment on table public.email_blocklist is 'Deterministic sender blocklist for the agent email workflow. Matched senders are dropped at ingestion before any ticket/message is stored, so blocked spam never consumes storage. Service-role worker only until dashboard roles and policies exist.';
comment on table public.forwarding_destinations is 'Who receives mail the contact team does not own: a name, an address (null = off), the categories and request kinds it may take, and a description in the business''s words that the router reads when a category has several destinations. Written by Agent Setup > Forwarding.';
comment on table public.forwarding_settings is 'Shop-wide acknowledgement for forwarded mail: whether it is sent, and the FR/EN templates ({service}, {note}, {shop}). Null templates use the defaults in code.';
comment on table public.integration_events is 'Metadata-only log of Shopify sync, webhook, and reconciliation events. Do not store raw payloads or personal data here.';
comment on table public.issue_family_members is 'Per shop: the issue family each ticket subject and each situation belongs to (DELIVERY, ORDER_CHANGE, REFUND_RETURN...). Case linking reads it; a subject or situation with no row has no family and is never linked on family grounds.';
comment on table public.issue_family_transitions is 'Per shop: a case about from_family may continue as to_family (a late delivery becoming a refund). Directed; a family is always compatible with itself and needs no row.';
comment on table public.klaviyo_campaigns is 'Klaviyo campaign performance, one row per campaign, as Klaviyo reports it for the campaign as a whole. Campaigns sent in the last year are rewritten nightly.';
comment on table public.klaviyo_connections is 'One row per shop connected to Klaviyo. The private key itself is in vault.secrets (secret_id); key_hint is its last four characters, the only part ever shown again.';
comment on table public.klaviyo_flow_days is 'Klaviyo flow performance per day (Klaviyo account clock), summed over the flow''s messages and channels. The last 60 days are rewritten nightly, because conversions keep arriving after a send.';
comment on table public.knowledge_chunks is 'AI retrieval chunks generated from knowledge_documents sections.';
comment on table public.knowledge_documents is 'Cleaned Shopify header/footer page and policy content used as source material for AI support context.';
comment on table public.llm_usage is 'One row per LLM or embedding call: pass, model, token counts, and the ticket it was spent on. Append-only and written by the agent worker through a single sink in the OpenAI transport. Tokens are stored and money is computed at read time from a configured rate, so a price change does not invalidate history.';
comment on table public.mail_jobs is 'Durable queue for mail work: sync_mailbox (a change notification asking for a folder to be read now) and send_outbound (carry out one outbound_actions row). Retries with backoff, dead after a cap, every attempt recorded. Case processing is deliberately not a kind: it runs off the needs_* flags ingestion raises only for new mail. Written only by scripts/lib/mail-job-record.mjs.';
comment on table public.mail_subscriptions is 'Provider change-notification subscriptions, one per shop, provider and folder. Created and renewed by agent/src/mail/subscription-manager.mjs only when MAIL_WEBHOOK_URL is set. A trigger, never the truth: a lost subscription costs latency, not mail.';
comment on view public.order_fulfilment_timing is 'One row per live order with its fulfilment duration in hours, normalised carrier, tracking count, destination and sales channel. The base every fulfilment panel aggregate reads. Delivery duration is deliberately absent -- Shopify holds no delivery events for this store.';
comment on table public.order_lines is 'One row per element of orders.line_items, derived and kept current by trigger (orders_order_lines_insert / _update); orders.line_items stays the snapshot. Scalar columns hold exactly what line_items ->> key returns (text, cast where read), so a reader gets the same values the JSON gave; discounts is the element''s discounts array.';
comment on table public.orders is 'Lean Shopify order snapshots for support workflows. Shopify remains the source of truth.';
comment on table public.outbound_actions is 'A reply we decided to send and how far it got: approved -> draft_created -> send_requested -> sent_confirmed, or cancelled / failed. The unique index on (shop_id, ticket_id, case_version, action_type) over rows not cancelled or failed is what stops a second email for one case version. Carried out only by agent/src/outbound/outbound-runner.mjs; written only by scripts/lib/outbound-record.mjs. Holds no recipient.';
comment on table public.privacy_requests is 'Lifecycle records for Shopify compliance webhooks. Customer contact values are hashed, not stored verbatim.';
comment on table public.products is 'Operational Shopify product snapshots for dashboard and AI context. Product images are intentionally not imported.';
comment on table public.promotions is 'Shopify discount and promotion snapshots for support workflows. Shopify remains the source of truth.';
comment on table public.sales_channels is 'The marketplaces this shop sells on: a name and the Shopify sales channel handles behind it. Every handle not listed is the shop''s own store. Marketplaces mint one customer per order, so their buyers are left out of every per-person figure. Edited in Setup -> Sales channels.';
comment on table public.sender_directory is 'Who a sender is to us, by email address or domain. Read as context (into the investigation case file) and by the clustering report to tell customer demand from our own mail. Replaces the INTERNAL_EMAIL_DOMAINS env var, which did not survive a project move. Rows are exceptions -- an unlisted sender is an ordinary consumer.';
comment on table public.shopify_content_sources is 'Lightweight index of live Shopify Online Store pages and shop policies (refund, privacy, shipping, terms of service, etc.), used to populate the Agent Setup source dropdown. Holds identity only; content is resolved on demand at import/resync time and is not stored here.';
comment on table public.shopify_metaobjects is 'Shopify metaobject snapshots shared across products, such as predefined product FAQs and ingredients.';
comment on table public.shops is 'Shopify shop records and app-level sync state. Shopify remains the source of truth.';
comment on table public.social_account_days is 'Organic account figures per day (the platform''s clock). Only counts that add up across days; null is not measured. followers is that day''s total. The trailing days are rewritten each sync.';
comment on table public.social_accounts is 'The accounts a social connection can see, found when it connects: instagram, facebook (a Page), meta_ads, google_ads. enabled is the team''s choice of what to track; every read skips a disabled account.';
comment on table public.social_audience is 'Aggregated follower demographics as the platform reports them (a count per bucket), one snapshot per account and day read. Never about an individual.';
comment on table public.social_audience_manual is 'The latest dated, person-entered percentage distribution per shop / platform / dimension. Provider audience snapshots remain separate and take precedence for a whole dimension.';
comment on table public.social_connections is 'One row per shop and provider (meta | google) connected through OAuth. The token is in vault.secrets (secret_id), never in a column. last_sync_status needs_reconnect means the provider refused the token.';
comment on table public.social_metric_bands is 'The team''s low / medium / high limits for a post metric, per platform: below low is low, high and above is high. mode says what the limits are relative to: nothing (off), the number itself, the account''s followers, or the median post.';
comment on table public.social_post_manual_metrics is 'Values a person typed for post metrics the platform did not give. Provider counters and sync stay separate in social_posts; a rate is specific to the denominator it was entered against.';
comment on table public.social_post_tag_links is 'Which social post carries which of the shop''s tags. Deleting a tag or a post deletes its links.';
comment on table public.social_post_tags is 'A shop''s own labels for social posts, created by a person in Insights → Social media → Posts. Names are unique per shop, ignoring case.';
comment on table public.social_posts is 'One row per published post with its lifetime counts. Posts of the last 90 days are re-read each sync, because their counts still grow. Counts only: no comment text and no commenter is ever fetched.';
comment on table public.spam_audit is 'Audit trail for the agent ingestion spam gate: one row per decision, recording kept/blocked and a one-line reason. Exists because both passes drop mail before any ticket is written, so a blocked email would otherwise leave no trace. Stores sender address, subject AND the cleaned body (see 08) as the evidence a human needs to judge whether a drop was right. The body expires on its own clock (body_expires_at) and is nulled by the worker; the decision row is kept indefinitely. Service-role worker only until dashboard roles and policies exist.';
comment on table public.storefront_chat_messages is 'Each customer message and advisor reply in a storefront_chat_sessions conversation, with the page context the widget sent.';
comment on table public.storefront_chat_sessions is 'An anonymous storefront advisor conversation (Theme App Extension via app proxy). The token is minted server-side; purged after the retention window.';
comment on table public.storefront_session_months is 'Closed months of Shopify Analytics human sessions and funnel counts, on the shop clock. Rewritten nightly; the last two months are always read live.';
comment on table public.support_answers is 'Answer skeletons keyed by evidence position, shared across exemplars. Guidance for the drafting agent, never text sent to a customer. Selection is by matching when_conditions against the findings resolved in evidence-rules.mjs -- most-specific wins, priority breaks ties.';
comment on view public.support_by_month is 'Monthly support intake with the mood and reply-time facts already folded in. Months with no ingested mail are absent rather than zero -- the panel draws that distinction, because an honest zero and missing data look identical on a chart.';
comment on table public.support_exemplar_phrasings is 'Retrieval rows for support_exemplars: the canonical question plus every real phrasing of it. One vector each; the exemplar is scored by its best-matching phrasing.';
comment on table public.support_exemplars is 'Recurring customer situations: a canonical question plus what answering it requires. Authored in the dashboard or imported from the clustered corpus; never auto-synced from Shopify.';
comment on table public.support_parameters is 'The numbers the support desk runs on -- returns window, dispatch delays, free-shipping threshold -- held once so a rule, an article and an answer skeleton cannot disagree about them. Read by code through scripts/lib/parameters.mjs; never retrieved as prose.';
comment on table public.ticket_case_actions is 'What a person did to a case from the dashboard: an open check marked done or cancelled. The fold (agent/src/casework/case-fold.mjs) applies these after the readings, so a check that was settled by phone or in Shopify stops being owed. Append-only.';
comment on table public.ticket_case_state is 'One reading per inbound message that landed on a ticket already read once: what the message changed about the case. Keyed per trigger message like ticket_investigations, because a thread''s readings are a trajectory rather than a current value. Records what was asked and answered, what was promised, and which prior evidence may be reused -- never what a tool returned.';
comment on table public.ticket_clusters is 'One row per topic found in a cluster run: its subject, size, cohesion, a representative excerpt and the messages in it. Written whole by cluster:tickets and read whole by the topic map.';
comment on table public.ticket_draft_edits is 'Append-only record of every human rewrite of a drafted reply, each carrying the model text it was an edit OF. The snapshot is the point: ticket_drafts.body_text is replaced by the next drafting run while approved_body_text is deliberately kept, so those two columns stop being a pair the moment a draft is re-run. Capture for Phase 7 memory; nothing reads it yet.';
comment on table public.ticket_drafts is 'One customer-facing reply per case version: what the agent would send, the mechanical checks it passed, and the human decision about it. Holds no recipient and cannot send. unique(shop_id, ticket_id, case_version) makes the pass safe to re-run and gives a case that moved a new row, leaving the old one stale with what its reviewer saw.';
comment on view public.ticket_first_inbound is 'One row per ticket: its earliest inbound message, already stripped of quoted reply chains by ingestion. Read by order resolution, which needs the customer''s own words rather than the thread.';
comment on table public.ticket_forwards is 'One row per email forwarded to a colleague, successful or not. Doubles as the idempotency ledger: unique(ticket_message_id) is what makes the forwarding step safe to re-run. Holds no message body -- the forwarded mail itself lives in the recipient mailbox and in ticket_messages.';
comment on table public.ticket_investigations is 'One case file per investigation run: what the agent established from the retrieval tools, what it could not verify, what is missing, and what must not be claimed. Consumed by the drafting stage and by the human queue. unique(shop_id, trigger_message_id) makes the pass safe to re-run and keeps a thread''s successive readings as separate rows.';
comment on view public.ticket_message_counts is 'Message count and inbound/outbound activity per ticket, excluding soft-deleted messages. Read by the dashboard queue instead of counting rows client-side.';
comment on table public.ticket_messages is 'Individual emails belonging to a ticket, one row per Microsoft Graph message. Inbound mail is ingested here idempotently (unique on shop_id + graph_message_id); outbound rows are the agent replies and team forwards.';
comment on table public.ticket_overrides is 'Every correction a person made to a ticket from the dashboard, and every reset to automatic. Append-only audit: the active values live in tickets.overrides.';
comment on view public.ticket_queue is 'One row per live ticket with its customer, message count and priority activity facts already joined -- the projection the dashboard list renders and the status write returns. Soft-deleted tickets are excluded here rather than by the caller; archived ones are kept and filtered in the UI. LEFT JOIN on customers: most tickets are unlinked until the customer-resolution pass runs.';
comment on view public.ticket_reply_times is 'First-response time per ticket: earliest inbound to the earliest outbound that came after it. `reply_hours` is null on a ticket the desk has not answered from the synced mailbox, which is the denominator the panel has to declare.';
comment on table public.ticket_routing is 'The forwarding router''s decision per ticket (forward to a destination, or keep), taken once and re-taken when the category or kind changes; and the once-per-ticket acknowledgement state.';
comment on table public.ticket_snoozes is 'A case hidden from the queue until something happens: one row per snooze, the open one (woke_at null) being the current. Not a ticket status: the status still says who acts next. Written only by scripts/lib/snooze-record.mjs. History is kept, so an automatic snooze a person undid early stays visible.';
comment on table public.tickets is 'Support conversations for the agent email workflow. One ticket per Microsoft Graph conversationId; the categorising agent fills category, request_kind, level, responsible_team, and the resolved Shopify order number. Access through the service-role worker only until dashboard roles and policies are implemented.';

reset check_function_bodies;
reset client_min_messages;
